INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13607, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指个体按照自己意愿行事、自我决定、自我管理的特性或能力。", "primary_collocate": null, "pronunciation": "zì zhǔ xìng", "ipa": "tsɨ˥˩ ʈʂu˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "可以断言，此类植根于社区自主性的实践，或将成为生态文明转型中最富生命力的基因单元。", "target_word": "自主性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种潜在的技术异化，迫使我们必须重新审视图灵测试之后的智能评估体系：是否应建立“自主性-责任性”双轴评价框架，以衡量代理在自由决策与社会嵌入之间的平衡能力？", "target_word": "自主性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "孩子需要有一点自主性。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作给了我很大的自主性。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想培养学生的自主性。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自主性强的人，不爱听别人安排。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管得太多，会让员工失去自主性。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的自主性很高，不用别人催。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在家里，孩子的自主性应该得到尊重。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习要有自主性，不能只听老师的。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自主权", "label": "复合"}, {"form": "自主学习", "label": "复合"}], "register": "中性", "sense_fingerprint": "自主性|按自己意愿行事、自我决定的特性或能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730e64f6-c995-4cfd-ab89-a28de46c42ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13607, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自主性", "is_correct": true, "explanation": "正确：「自主性」是个人自己决定、自己管理的特性，可以植根于社区的实践。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」是商品的标价，不是可以植根于社区的做法或特性。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」是气象状况，不能作为「植根于社区」的内容。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：「社区……的实践」需要抽象的特性或做法，「收入」是经济数字，不与「植根于」搭配。"}], "explanations": {"自主性": "正确：「自主性」是个人自己决定、自己管理的特性，可以植根于社区的实践。", "价格": "语义：「价格」是商品的标价，不是可以植根于社区的做法或特性。", "天气": "语义：「天气」是气象状况，不能作为「植根于社区」的内容。", "收入": "搭配：「社区……的实践」需要抽象的特性或做法，「收入」是经济数字，不与「植根于」搭配。"}, "sentence_index": 0, "correct_answer": "自主性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的自主性很高，很难切开。", "explanation": "这里应该用〈硬度〉。「硬度」说物体硬不硬，「自主性」是个体自己决定事情的能力，不能用来说石头。"}, {"text": "这个房间的自主性很大。", "explanation": "这里应该用〈面积〉。房间的大小要说「面积」，「自主性」指个人自我决定的特性，不能用来形容房间。"}, {"text": "这箱书的自主性很重。", "explanation": "这里应该用〈重量〉。箱子的轻重要说「重量」，「自主性」指个人自我决定的特性，不能用来形容一箱书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13607, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自主性", "is_correct": true, "explanation": "正确：「自主性」是可以被管理者削弱或失去的特性，与「管得太多」的后果相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是外观的属性，管得太多不会让员工失去颜色。"}, {"text": "美貌", "is_correct": false, "explanation": "体貌：「美貌」指外表，与「管得太多」的后果无关。"}, {"text": "重量", "is_correct": false, "explanation": "语义：「重量」是物体的轻重，员工不能「失去」重量，与「管得太多」的后果无关。"}], "explanations": {"自主性": "正确：「自主性」是可以被管理者削弱或失去的特性，与「管得太多」的后果相符。", "颜色": "语义：「颜色」是外观的属性，管得太多不会让员工失去颜色。", "美貌": "体貌：「美貌」指外表，与「管得太多」的后果无关。", "重量": "语义：「重量」是物体的轻重，员工不能「失去」重量，与「管得太多」的后果无关。"}, "sentence_index": 6, "correct_answer": "自主性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家的猫有一只自主性，很可爱。", "explanation": "这里量词用错。「只」用于动物，「自主性」是抽象的特性，不能像动物一样计数。"}, {"text": "他的自主性很亮，像一盏灯。", "explanation": "这里应该用〈亮度〉。「亮度」用来说光线的明暗，「自主性」没有亮暗，不能这样形容一个人。"}, {"text": "这份报告的自主性很厚，有五十页。", "explanation": "这里应该用〈厚度〉。「厚度」用来说物体厚不厚，报告的厚薄要说「厚度」；「自主性」没有厚薄，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13607, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他身上有一只自主性，不用别人催。", "corrected_sentence": "他身上有一种自主性，不用别人催。", "error_description": "错误：「一只自主性」。正确：「一种自主性」。「只」用于动物等，抽象的特性应该用「种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13607, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子身上有一片自主性。", "corrected_sentence": "这个孩子身上有一种自主性。", "error_description": "错误：「一片自主性」。正确：「一种自主性」。「片」用于森林、草地等大片的东西，抽象的特性应该用「种」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13609, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13609, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13609, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物生存、发展、活动的能力。", "primary_collocate": null, "pronunciation": "shēng mìng lì", "ipa": "ʂɤŋ˥ miŋ˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "可以断言，此类植根于社区自主性的实践，或将成为生态文明转型中最富生命力的基因单元。", "target_word": "生命力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种植物的生命力很强，石头缝里也能长。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野草的生命力比花园里的花强得多。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城充满了生命力。", "target_word": "生命力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的文化有很强的生命力。", "target_word": "生命力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天一到，大地又有了生命力。", "target_word": "生命力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家老店有一百年的历史，生命力很强。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小草从砖缝里长出来，生命力真顽强。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些新技术的生命力来自市场的需要。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大火后，这片森林又恢复了生命力。", "target_word": "生命力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "生命力：事物生存、发展的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cb5dee-9d44-4bb3-8c39-0659efa57b2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13609, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生命力", "is_correct": true, "explanation": "正确。“最富生命力”指这个基因单元生存、发展的能力最强，与句意相合。"}, {"text": "幽默感", "is_correct": false, "explanation": "语义：幽默感是人的性格特征，基因单元不具备这种性质，句子不合逻辑。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：“富”不与“历史”搭配，应说“历史悠久”，不能说“最富历史”。"}, {"text": "同情心", "is_correct": false, "explanation": "语义：同情心属于有感情的人，用来形容基因单元不合逻辑。"}], "explanations": {"生命力": "正确。“最富生命力”指这个基因单元生存、发展的能力最强，与句意相合。", "幽默感": "语义：幽默感是人的性格特征，基因单元不具备这种性质，句子不合逻辑。", "历史": "搭配：“富”不与“历史”搭配，应说“历史悠久”，不能说“最富历史”。", "同情心": "语义：同情心属于有感情的人，用来形容基因单元不合逻辑。"}, "sentence_index": 0, "correct_answer": "生命力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只乌龟的生命力有一百年。", "explanation": "这里应该用〈寿命〉。生命力指事物生存、发展的能力，说活了多长时间要用寿命。"}, {"text": "医生全力挽救他的生命力。", "explanation": "这里应该用〈生命〉。挽救的是人的性命，生命力指生存、发展的能力，不能说“挽救生命力”。"}, {"text": "他的生命力很大，能一口气背下整本词典。", "explanation": "这里应该用〈记性〉。生命力指生存、发展的能力，不指记忆力；说记性好要用〈记性〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生命力", "is_correct": true, "explanation": "正确。“生命力很强”描述老店存续的能力，与“一百年的历史”相合。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“很强”形容生存能力，寿命应说“长”或“短”，不说“寿命很强”。"}, {"text": "体力", "is_correct": false, "explanation": "语义：体力指人的身体力量，老店没有体力，句子不合理。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重指人或动物的重量，不能说“体重很强”。"}], "explanations": {"生命力": "正确。“生命力很强”描述老店存续的能力，与“一百年的历史”相合。", "寿命": "搭配：“很强”形容生存能力，寿命应说“长”或“短”，不说“寿命很强”。", "体力": "语义：体力指人的身体力量，老店没有体力，句子不合理。", "体重": "搭配：体重指人或动物的重量，不能说“体重很强”。"}, "sentence_index": 6, "correct_answer": "生命力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的生命力很强，吃一片就能止痛。", "explanation": "这里应该用〈药效〉。生命力指生存、发展的能力，不指药物的作用。"}, {"text": "这位老人生命力很好，能看清报纸上的小字。", "explanation": "这里应该用〈视力〉。能否看清小字说的是眼睛的能力，不是生命力。"}, {"text": "他的生命力很高，数学题一看就会。", "explanation": "这里应该用〈智力〉。智力指认识和思维能力，生命力不能用来形容解题能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这株草有一只很强的生命力，雨后长得很快。", "corrected_sentence": "这株草有一股很强的生命力，雨后长得很快。", "error_description": "量词错误：“生命力”前应用“股”或“种”，不能用“只”（“只”多用于动物或成对之物）。正确说法是“一股很强的生命力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨后的野花生命力强很，很快就开满了山坡。", "corrected_sentence": "雨后的野花生命力很强，很快就开满了山坡。", "error_description": "程度副词位置错误：“很”应放在形容词“强”前，说“生命力很强”，不能放在“强”后，说“生命力强很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cac23582-e853-459d-ad4c-734c6a4be683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
