INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13611, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种能自我复制并推动系统变革的基本单位", "primary_collocate": null, "pronunciation": "dān yuán", "ipa": "tan˥˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "可以断言，此类植根于社区自主性的实践，或将成为生态文明转型中最富生命力的基因单元。", "target_word": "单元", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "研究者提出，真正推动系统变革的，往往不是宏大的规划，而是那些能够自我复制的单元。", "target_word": "单元", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "基因是生命的遗传单元。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个单元能自己复制，也能一直生长。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种单元会不断复制自己并带动系统变革。", "target_word": "单元", "complexity_tier": "T3", "furigana": "zhè zhǒng dān yuán huì bú duàn fù zhì zì jǐ bìng dài dòng xì tǒng biàn gé", "sentence_source": "generated"}, {"text": "细胞是生物最小的单元。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个好的单元会在人群中不断复制并传播。", "target_word": "单元", "complexity_tier": "T3", "furigana": "yí gè hǎo de dān yuán huì zài rén qún zhōng bú duàn fù zhì bìng chuán bō", "sentence_source": "generated"}, {"text": "一个单元能不断复制，就会改变整个系统。", "target_word": "单元", "complexity_tier": "T3", "furigana": "yí gè dān yuán néng bú duàn fù zhì jiù huì gǎi biàn zhěng gè xì tǒng", "sentence_source": "generated"}, {"text": "一个能自我复制的单元会推动社会变革。", "target_word": "单元", "complexity_tier": "T3", "furigana": "yí gè néng zì wǒ fù zhì de dān yuán huì tuī dòng shè huì biàn gé", "sentence_source": "generated"}, {"text": "这个小单元推动了整个系统的改变。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "基因单元", "label": "复合"}, {"form": "基本单元", "label": "复合"}], "register": "中性", "sense_fingerprint": "单元|能自我复制并推动系统变革的基本单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730e64f6-c995-4cfd-ab89-a28de46c42ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单元", "is_correct": true, "explanation": "正确：“基因单元”指能自我复制、推动变革的基本单位，与句中的“生命力”“转型”语义相合。"}, {"text": "基因病", "is_correct": false, "explanation": "语义：“基因病”指遗传疾病，与“最富生命力”的积极语义冲突，不能成为推动生态文明转型的力量。"}, {"text": "基因检测", "is_correct": false, "explanation": "语义：「基因检测」是化验基因的技术手段，不是能自我复制、推动变革的基本单位，与句意不合。"}, {"text": "基因枪", "is_correct": false, "explanation": "语义：「基因枪」是一种实验器械，不是能自我复制、推动变革的基本单位，与句意不合。"}], "explanations": {"单元": "正确：“基因单元”指能自我复制、推动变革的基本单位，与句中的“生命力”“转型”语义相合。", "基因病": "语义：“基因病”指遗传疾病，与“最富生命力”的积极语义冲突，不能成为推动生态文明转型的力量。", "基因检测": "语义：「基因检测」是化验基因的技术手段，不是能自我复制、推动变革的基本单位，与句意不合。", "基因枪": "语义：「基因枪」是一种实验器械，不是能自我复制、推动变革的基本单位，与句意不合。"}, "sentence_index": 0, "correct_answer": "单元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "单元突变会导致遗传病。", "explanation": "这里应该用〈基因〉。突变指遗传物质发生改变，要说“基因突变”；“单元”指能复制、推动变革的基本单位，不用于突变。"}, {"text": "这个单元有一大片森林，面积有几百平方公里。", "explanation": "这里应该用〈地区〉。“单元”指能复制、推动变革的基本单位，不指一片地域；描述一大片森林的范围要说“地区”。"}, {"text": "我们研究了一只单元，它能自己复制。", "explanation": "量词〈只〉用于动物，不能修饰“单元”，这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单元", "is_correct": true, "explanation": "正确：“一个好的单元”指能在人群中复制、传播的基本单位，与“不断复制并传播”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能在人群中“复制并传播”，与句中“不断复制”冲突。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“复制”“传播”多用于信息、想法、文件，不说房间被复制、传播。"}, {"text": "账户", "is_correct": false, "explanation": "语义：账户是财务记录，不能在人群中传播，与“人群中传播”的语境冲突。"}], "explanations": {"单元": "正确：“一个好的单元”指能在人群中复制、传播的基本单位，与“不断复制并传播”相合。", "桌子": "语义：桌子是家具，不能在人群中“复制并传播”，与句中“不断复制”冲突。", "房间": "搭配：“复制”“传播”多用于信息、想法、文件，不说房间被复制、传播。", "账户": "语义：账户是财务记录，不能在人群中传播，与“人群中传播”的语境冲突。"}, "sentence_index": 6, "correct_answer": "单元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在一家国企工作，那个单元很大。", "explanation": "这里应该用〈单位〉。“单元”指能复制、推动变革的基本单位，不指工作的机构；谈论工作的地方要说“单位”。"}, {"text": "这个单元有十栋楼，都是新盖的。", "explanation": "这里应该用〈小区〉。“单元”是楼内的一部分，不能包含十栋楼；整片住宅区要说“小区”。"}, {"text": "这颗单元推动了整个系统的改变。", "explanation": "量词〈颗〉用于颗粒状的小东西，“单元”是抽象的基本单位，这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只单元只要能自己复制，就能慢慢改变整个系统。", "corrected_sentence": "一个单元只要能自己复制，就能慢慢改变整个系统。", "error_description": "量词错误：“单元”是抽象的基本单位，应搭配通用量词“个”，不能用动物量词“只”。正确说法是“一个单元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这颗单元在社区里不断复制，并慢慢扩散开来。", "corrected_sentence": "这个单元在社区里不断复制，并慢慢扩散开来。", "error_description": "量词错误：“单元”应搭配通用量词“个”，“颗”用于种子、粒状物，不能修饰抽象的基本单位。正确说法是“这个单元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
