INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13613, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用石磨或机器将小麦等谷物磨成面粉。", "primary_collocate": null, "pronunciation": "mò miàn", "ipa": "mwo˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "很久以前，人们用风车磨面。", "target_word": "磨面", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "农民用石磨磨面。", "target_word": "磨面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶年轻时每天早上磨面。", "target_word": "磨面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里有一台机器专门磨面。", "target_word": "磨面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小麦收了以后，要先晒干再磨面。", "target_word": "磨面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前没有机器，家家都要自己磨面。", "target_word": "磨面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷推着石磨，慢慢地磨面。", "target_word": "磨面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用驴拉磨来磨面。", "target_word": "磨面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "磨面的时候，院子里到处是白粉。", "target_word": "磨面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器一小时能磨面五十斤。", "target_word": "磨面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "磨面机", "label": "复合"}], "register": "中性", "sense_fingerprint": "把小麦等谷物磨成面粉的劳动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c21dd34c-16ba-43e7-a982-0b6076900aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13613, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "磨面", "is_correct": true, "explanation": "「用风车磨面」指用风车把谷物磨成面粉，符合题干语境。"}, {"text": "收割", "is_correct": false, "explanation": "语义：「收割」指割取庄稼，不能用风车完成，与题干不合。"}, {"text": "播种", "is_correct": false, "explanation": "语义：「播种」指把种子埋进土里，与风车无关，与题干不合。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指点燃或加热，风车不能用来烧谷物，与题干“用风车磨面”的动作不合。"}], "explanations": {"磨面": "「用风车磨面」指用风车把谷物磨成面粉，符合题干语境。", "收割": "语义：「收割」指割取庄稼，不能用风车完成，与题干不合。", "播种": "语义：「播种」指把种子埋进土里，与风车无关，与题干不合。", "烧": "语义：“烧”指点燃或加热，风车不能用来烧谷物，与题干“用风车磨面”的动作不合。"}, "sentence_index": 0, "correct_answer": "磨面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面团要用力磨面，才能做出筋道的面条。", "explanation": "这里应该用〈和面〉。“磨面”指把谷物磨成面粉，揉面团要用“和面”。"}, {"text": "妈妈用手磨饺子，一个个捏得很漂亮。", "explanation": "这里应该用〈包〉。包饺子要用“包”，“磨”是把谷物磨成粉，不能用来做饺子。"}, {"text": "妈妈在案板上磨面，准备擀饺子皮。", "explanation": "这里应该用〈擀面〉。擀饺子皮要用擀面杖擀，不说“磨面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "磨面", "is_correct": true, "explanation": "「慢慢地磨面」指慢慢把谷物磨成面粉，与推石磨的动作一致。"}, {"text": "登山", "is_correct": false, "explanation": "语义：推着石磨无法「登山」，「慢慢地登山」与题干动作不合。"}, {"text": "绣花", "is_correct": false, "explanation": "语义：推石磨的劳动与「绣花」的精细动作不合，语境上不成立。"}, {"text": "泼", "is_correct": false, "explanation": "配价：「泼」需带宾语（泼水），这里「慢慢地泼」缺少对象。"}], "explanations": {"磨面": "「慢慢地磨面」指慢慢把谷物磨成面粉，与推石磨的动作一致。", "登山": "语义：推着石磨无法「登山」，「慢慢地登山」与题干动作不合。", "绣花": "语义：推石磨的劳动与「绣花」的精细动作不合，语境上不成立。", "泼": "配价：「泼」需带宾语（泼水），这里「慢慢地泼」缺少对象。"}, "sentence_index": 6, "correct_answer": "磨面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "包饺子时，边缘要磨紧，不能漏馅。", "explanation": "这里应该用〈捏〉。封饺子边要用“捏”，“磨”是把谷物磨成粉，不能用来封口。"}, {"text": "妈妈把面团磨成细条，做了一锅面条。", "explanation": "这里应该用〈切〉。把面团做成细条要切，“磨”是把谷物磨成面粉。"}, {"text": "奶奶在锅里磨饼，香味飘满了屋子。", "explanation": "这里应该用〈烙〉。烙饼要用热锅烙，“磨”只指把谷物磨碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶磨面得很快，做了馒头。", "corrected_sentence": "奶奶磨面磨得很快，做了馒头。", "error_description": "补语错误：动宾短语带补语时要重复动词，应说“磨面磨得很快”，不能只说“磨面得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨天没磨面了，只好去买面。", "corrected_sentence": "他们昨天没磨面，只好去买面。", "error_description": "体标错误：“没”否定已发生的动作时，句中不能再用“了”，应说“没磨面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
