INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13617, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "片状的硬物体，比如木头做的板子。", "primary_collocate": null, "pronunciation": "bǎn", "ipa": "pan˨˩˦", "syllable_count": 1, "sentences": [{"text": "现在，我们用太阳能板发电。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "从风车到太阳能板，都在变好。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "这块板很硬，不能用来写字。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸把一块板钉在墙上。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门口放着一块板，上面写着营业时间。", "target_word": "板", "complexity_tier": "T3", "furigana": "mén kǒu fàng zhe yí kuài bǎn, shàng miàn xiě zhe yíng yè shí jiān.", "sentence_source": "generated"}, {"text": "这块板太重了，我一个人搬不动。", "target_word": "板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一块板挡住了风。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把那块板递给我。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子下面有两块板。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块板太薄了，坐上去会断。", "target_word": "板", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "木板", "label": "复合"}, {"form": "黑板", "label": "复合"}], "register": "中性", "sense_fingerprint": "片状的硬物体，如木板、太阳能板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ff5dce4-678f-4afa-8fc7-dd6993e1a005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13617, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "板", "is_correct": true, "explanation": "正确答案：板（bǎn），指片状的硬物体，如木板。"}, {"text": "办", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是办理、办法。"}, {"text": "满", "is_correct": false, "explanation": "声母 m 与 b 不同，声调同为第三声，意思是装满、满足。"}, {"text": "反", "is_correct": false, "explanation": "声母 f 与 b 不同，声调同为第三声，意思是相反。"}, {"text": "绑", "is_correct": false, "explanation": "韵尾 ng 与 n 不同（bǎng 与 bǎn），意思是捆绑。"}, {"text": "班", "is_correct": false, "explanation": "bān（第一声）与 bǎn（第三声）声调不同，意思是班级。"}], "explanations": {"板": "正确答案：板（bǎn），指片状的硬物体，如木板。", "办": "bàn（第四声）与 bǎn（第三声）声调不同，意思是办理、办法。", "满": "声母 m 与 b 不同，声调同为第三声，意思是装满、满足。", "反": "声母 f 与 b 不同，声调同为第三声，意思是相反。", "绑": "韵尾 ng 与 n 不同（bǎng 与 bǎn），意思是捆绑。", "班": "bān（第一声）与 bǎn（第三声）声调不同，意思是班级。"}, "sentence_index": null, "correct_answer": "板"}, "level_3": {"options": [{"text": "水", "is_correct": false, "explanation": "语义：水不是可以用来发电的装置，“用太阳能水发电”说不通。"}, {"text": "板", "is_correct": true, "explanation": "正确：板，指太阳能板，即用来吸收太阳光发电的板状装置。"}, {"text": "煤", "is_correct": false, "explanation": "搭配：“太阳能”后不接“煤”，二者不能组成修饰关系。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是用电的器具，不能用来发电，与“发电”的意思相矛盾。"}], "explanations": {"水": "语义：水不是可以用来发电的装置，“用太阳能水发电”说不通。", "板": "正确：板，指太阳能板，即用来吸收太阳光发电的板状装置。", "煤": "搭配：“太阳能”后不接“煤”，二者不能组成修饰关系。", "灯": "语义：灯是用电的器具，不能用来发电，与“发电”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秋天，院子里落满了一板树叶。", "explanation": "这里应该用〈片〉。树叶这类薄而轻的东西用“片”，“板”指硬而厚的板子，不能用来数树叶。"}, {"text": "他把这块板揉成一团，扔进了垃圾桶。", "explanation": "这里应该用〈纸〉。板是硬的片状物，不能揉成一团；揉成一团的是纸、布等软薄的东西。"}, {"text": "这只板很硬，搬不动。", "explanation": "这里应该用〈块〉。板是块状的，应用量词“块”；“只”多用于动物等，不能用来数板子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13617, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "半", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是一半。"}, {"text": "板", "is_correct": true, "explanation": "正确答案：板（bǎn），指片状的硬物体，如木板。"}, {"text": "毯", "is_correct": false, "explanation": "tǎn（第三声）与 bǎn 声母不同（t 与 b），意思是地毯。"}, {"text": "晚", "is_correct": false, "explanation": "声母 w 与 b 不同，声调同为第三声，意思是晚上。"}, {"text": "产", "is_correct": false, "explanation": "chǎn（第三声）与 bǎn 声母不同（ch 与 b），意思是生产。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn（第三声）与 bǎn 声母不同（h 与 b），意思是大声叫。"}], "explanations": {"半": "bàn（第四声）与 bǎn（第三声）声调不同，意思是一半。", "板": "正确答案：板（bǎn），指片状的硬物体，如木板。", "毯": "tǎn（第三声）与 bǎn 声母不同（t 与 b），意思是地毯。", "晚": "声母 w 与 b 不同，声调同为第三声，意思是晚上。", "产": "chǎn（第三声）与 bǎn 声母不同（ch 与 b），意思是生产。", "喊": "hǎn（第三声）与 bǎn 声母不同（h 与 b），意思是大声叫。"}, "sentence_index": null, "correct_answer": "板"}, "level_3": {"options": [{"text": "糖", "is_correct": false, "explanation": "语义：糖太小且易溶，挡不住风，与“挡住了风”矛盾。"}, {"text": "纸屑", "is_correct": false, "explanation": "体貌：纸屑细碎、不成块状，无法挡住风，与“一块”的形态不符。"}, {"text": "板", "is_correct": true, "explanation": "正确：板，指片状的硬物体，能够挡住风。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能用来挡风，与“挡住了风”不相符。"}], "explanations": {"糖": "语义：糖太小且易溶，挡不住风，与“挡住了风”矛盾。", "纸屑": "体貌：纸屑细碎、不成块状，无法挡住风，与“一块”的形态不符。", "板": "正确：板，指片状的硬物体，能够挡住风。", "面包": "语义：面包是食物，不能用来挡风，与“挡住了风”不相符。"}, "sentence_index": 6, "correct_answer": "板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他搬起一把板，走进了屋子。", "explanation": "这里应该用〈块〉。“把”用于有柄的器具，如刀、椅子；板子是块状的，不能用“把”。"}, {"text": "他把这块板撕成了碎片，扔在地上。", "explanation": "这里应该用〈纸〉。撕成碎片是对纸等软薄物的动作，板是硬的片状物，不能这样撕。"}, {"text": "他用一板砖砌了一面墙。", "explanation": "这里应该用〈块〉。砖是块状的，应用“块”；“板”指片状的硬板，不用来数砖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗边放着一只板，挡住了光。", "corrected_sentence": "窗边放着一块板，挡住了光。", "error_description": "“板”是块状的硬物，量词应用“块”，不能用“只”。错误在量词“只”，正确说法是“一块板”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一根板放在桌子上。", "corrected_sentence": "他把一块板放在桌子上。", "error_description": "“板”是块状的硬物，不是细长条，量词应用“块”，不能用“根”。错误在量词“根”，正确说法是“一块板”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13622, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13622, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13622, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想出指通过思考产生某个想法、办法或结论。", "primary_collocate": null, "pronunciation": "xiǎng chū", "ipa": "ɕiɑŋ˨˩˦ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "人们想出好办法，让风吹、太阳晒都能发电。", "target_word": "想出", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他终于想出了一个好办法。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能想出别的答案吗？", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想了很久，也没想出名字。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们想出一个有趣的题目。", "target_word": "想出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想出了怎么去机场的路。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起想出了很多主意。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我还没想出送他什么礼物。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想出办法了吗？", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想出过一个很好玩的游戏。", "target_word": "想出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "想出了", "label": "体标"}, {"form": "想出过", "label": "体标"}, {"form": "想不出", "label": "复合"}, {"form": "想得出", "label": "复合"}], "register": "中性", "sense_fingerprint": "通过思考得出办法、想法或结论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ff5dce4-678f-4afa-8fc7-dd6993e1a005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13622, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "想出", "is_correct": true, "explanation": "正确答案：想出（xiǎng chū），指通过思考产生办法或想法。"}, {"text": "显出", "is_correct": false, "explanation": "xiǎn 与 xiǎng 韵母不同（an 与 ang），声调相同，意思是显露出来。"}, {"text": "讲出", "is_correct": false, "explanation": "声母 j 与 x 不同，jiǎng 与 xiǎng 声调相同，意思是说出来。"}, {"text": "长出", "is_correct": false, "explanation": "声母 zh 与 x 不同，zhǎng 与 xiǎng 声调相同，意思是生长出来。"}, {"text": "省出", "is_correct": false, "explanation": "xǐng 与 xiǎng 韵母不同（ing 与 iang），声调相同，意思是节省出来。"}], "explanations": {"想出": "正确答案：想出（xiǎng chū），指通过思考产生办法或想法。", "显出": "xiǎn 与 xiǎng 韵母不同（an 与 ang），声调相同，意思是显露出来。", "讲出": "声母 j 与 x 不同，jiǎng 与 xiǎng 声调相同，意思是说出来。", "长出": "声母 zh 与 x 不同，zhǎng 与 xiǎng 声调相同，意思是生长出来。", "省出": "xǐng 与 xiǎng 韵母不同（ing 与 iang），声调相同，意思是节省出来。"}, "sentence_index": null, "correct_answer": "想出"}, "level_3": {"options": [{"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的对象多为食物，不能接“办法”作宾语，与“好办法”不搭。"}, {"text": "想出", "is_correct": true, "explanation": "正确：想出，表示通过思考产生办法，与“好办法”搭配。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：办法是抽象的，不能被“打碎”，与“好办法”矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”一般接歌曲等对象，不接“办法”作宾语。"}], "explanations": {"吃掉": "搭配：“吃掉”的对象多为食物，不能接“办法”作宾语，与“好办法”不搭。", "想出": "正确：想出，表示通过思考产生办法，与“好办法”搭配。", "打碎": "语义：办法是抽象的，不能被“打碎”，与“好办法”矛盾。", "唱": "搭配：“唱”一般接歌曲等对象，不接“办法”作宾语。"}, "sentence_index": 0, "correct_answer": "想出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一进门就想出了桌上的那杯水。", "explanation": "这里应该用〈看见〉。想出用于思考产生的办法或想法，看到眼前的实物要用“看见”。"}, {"text": "他想出了一瓶水。", "explanation": "这里应该用〈拿〉或〈买〉。想出指通过思考产生想法或办法，“水”是实物，拿或买一瓶水要用“拿”“买”，不能用“想出”。"}, {"text": "我终于想出了丢失的钥匙。", "explanation": "这里应该用〈找到〉。想出用于办法、想法，找丢失的东西要用“找到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13622, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "想出", "is_correct": true, "explanation": "正确答案：想出（xiǎng chū），指通过思考产生办法或想法。"}, {"text": "养出", "is_correct": false, "explanation": "yǎng（第三声）与 xiǎng 声母不同（y 与 x），声调相同，意思是养育出。"}, {"text": "省出", "is_correct": false, "explanation": "xǐng（第三声）与 xiǎng 韵母不同（ing 与 iang），声调相同，意思是节省出来。"}, {"text": "讲出", "is_correct": false, "explanation": "jiǎng（第三声）与 xiǎng 声母不同（j 与 x），声调相同，意思是说出来。"}, {"text": "相处", "is_correct": false, "explanation": "xiāng chǔ 与 xiǎng chū 两个音节的声调都不同，意思是彼此交往。"}], "explanations": {"想出": "正确答案：想出（xiǎng chū），指通过思考产生办法或想法。", "养出": "yǎng（第三声）与 xiǎng 声母不同（y 与 x），声调相同，意思是养育出。", "省出": "xǐng（第三声）与 xiǎng 韵母不同（ing 与 iang），声调相同，意思是节省出来。", "讲出": "jiǎng（第三声）与 xiǎng 声母不同（j 与 x），声调相同，意思是说出来。", "相处": "xiāng chǔ 与 xiǎng chū 两个音节的声调都不同，意思是彼此交往。"}, "sentence_index": null, "correct_answer": "想出"}, "level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象多为食物，不能接“主意”作宾语。"}, {"text": "想出", "is_correct": true, "explanation": "正确：想出，表示想出主意，与“很多主意”搭配。"}, {"text": "踢", "is_correct": false, "explanation": "语义：主意是抽象的，不能被“踢”，与“想”的语义矛盾。"}, {"text": "穿", "is_correct": false, "explanation": "语义：主意不能被穿戴，与“很多主意”的语义不相容。"}], "explanations": {"煮": "搭配：“煮”的对象多为食物，不能接“主意”作宾语。", "想出": "正确：想出，表示想出主意，与“很多主意”搭配。", "踢": "语义：主意是抽象的，不能被“踢”，与“想”的语义矛盾。", "穿": "语义：主意不能被穿戴，与“很多主意”的语义不相容。"}, "sentence_index": 6, "correct_answer": "想出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "放学路上，我想出了一只小猫。", "explanation": "这里应该用〈看见〉。想出是思考产生想法，看到具体的东西要用“看见”。"}, {"text": "他想出了一块糖，塞进了嘴里。", "explanation": "想出的宾语应是办法、想法等抽象内容；“糖”是实物，不能用“想出”，拿出实物要用“拿出”。"}, {"text": "他从包里想出了钱。", "explanation": "这里应该用〈取出〉。想出用于思考产生的内容，从包里拿东西要用“取出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈终于想出着一个好办法。", "corrected_sentence": "妈妈终于想出了一个好办法。", "error_description": "“想出”表示思考后得出结果，已经完成，应用“了”；“着”表示状态持续，不能与“想出”搭配。错误在“着”，正确说法是“想出了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小红不想出过一个有趣的题目。", "corrected_sentence": "小红没想出过一个有趣的题目。", "error_description": "“想出过”表示曾有过的经历，否定经历要用“没”，不能用“不”。错误在否定词“不”，应改为“没”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13624, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13624, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13624, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放在太阳光下，让太阳光把东西弄干或变热。", "primary_collocate": null, "pronunciation": "shài", "ipa": "ʂai˥˩", "syllable_count": 1, "sentences": [{"text": "人们把湿木柴摊在院子里，让风吹、太阳晒，很快就干了。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把湿衣服拿到阳台上晒。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，农民把玉米放在院子里晒干。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把床单拿到外面晒了一个下午。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在门口晒着红辣椒。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿鞋子别放在屋里，拿出去晒一晒。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气好，我想把书拿出来晒晒。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的人把鱼晒成鱼干，可以放很久。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完的衣服要晒在太阳下面才会干。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的帽子湿了，快拿去晒吧。", "target_word": "晒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晒了", "label": "体标"}, {"form": "晒着", "label": "体标"}, {"form": "晒过", "label": "体标"}, {"form": "晒晒", "label": "重叠"}, {"form": "晒干", "label": "复合"}, {"form": "曬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西放在阳光下弄干或变热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ff5dce4-678f-4afa-8fc7-dd6993e1a005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13624, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "晒", "is_correct": true, "explanation": "正确答案。晒 shài，意思是把东西放在太阳下弄干或变热。"}, {"text": "赛", "is_correct": false, "explanation": "sài（第四声）与 shài 声母不同（s 与 sh），意思是比赛。"}, {"text": "债", "is_correct": false, "explanation": "zhài（第四声）与 shài 声母不同（zh 与 sh），意思是债务。"}, {"text": "哨", "is_correct": false, "explanation": "shào（第四声）与 shài 韵母不同（ao 与 ai），意思是哨子。"}, {"text": "筛", "is_correct": false, "explanation": "shāi（第一声）与 shài（第四声）声调不同，意思是筛子。"}], "explanations": {"晒": "正确答案。晒 shài，意思是把东西放在太阳下弄干或变热。", "赛": "sài（第四声）与 shài 声母不同（s 与 sh），意思是比赛。", "债": "zhài（第四声）与 shài 声母不同（zh 与 sh），意思是债务。", "哨": "shào（第四声）与 shài 韵母不同（ao 与 ai），意思是哨子。", "筛": "shāi（第一声）与 shài（第四声）声调不同，意思是筛子。"}, "sentence_index": null, "correct_answer": "晒"}, "level_3": {"options": [{"text": "晒", "is_correct": true, "explanation": "正确。晒指太阳光照使东西变干，与“让风吹”并列，都能让木柴变干。"}, {"text": "唱", "is_correct": false, "explanation": "语义：太阳不会唱歌，“太阳唱”与“让风吹”并列的动作不合理。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“太阳”搭配作并列的动作，“太阳吃”不成立。"}, {"text": "跑", "is_correct": false, "explanation": "语义：太阳不会跑，与“让风吹”并列的动作不合理。"}], "explanations": {"晒": "正确。晒指太阳光照使东西变干，与“让风吹”并列，都能让木柴变干。", "唱": "语义：太阳不会唱歌，“太阳唱”与“让风吹”并列的动作不合理。", "吃": "搭配：“吃”不能与“太阳”搭配作并列的动作，“太阳吃”不成立。", "跑": "语义：太阳不会跑，与“让风吹”并列的动作不合理。"}, "sentence_index": 0, "correct_answer": "晒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把湿鞋子放在暖气旁边晒干。", "explanation": "这里应该用〈烘〉。晒要靠太阳光，靠暖气加热把东西弄干要用烘。"}, {"text": "他把床单拿到屋里晒了一个下午。", "explanation": "这里应该用〈晾〉。晒要在太阳光下进行，在屋里阴干应该用晾。"}, {"text": "他把红薯放在炉子上晒熟了。", "explanation": "这里应该用〈烤〉。晒靠阳光，用炉火加热使食物变熟要用烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13624, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "晒", "is_correct": true, "explanation": "正确答案。晒 shài，意思是把东西放在太阳下弄干或变热。"}, {"text": "帅", "is_correct": false, "explanation": "shuài（第四声）与 shài 只差介音 u（uai 与 ai），意思是英俊、帅气。"}, {"text": "赖", "is_correct": false, "explanation": "lài（第四声）与 shài 只差声母（l 与 sh），意思是耍赖、依赖。"}, {"text": "上", "is_correct": false, "explanation": "shàng（第四声）与 shài 只差韵尾（ang 与 ai），意思是上面。"}, {"text": "善", "is_correct": false, "explanation": "shàn（第四声）与 shài 韵母不同（an 与 ai），意思是善良。"}], "explanations": {"晒": "正确答案。晒 shài，意思是把东西放在太阳下弄干或变热。", "帅": "shuài（第四声）与 shài 只差介音 u（uai 与 ai），意思是英俊、帅气。", "赖": "lài（第四声）与 shài 只差声母（l 与 sh），意思是耍赖、依赖。", "上": "shàng（第四声）与 shài 只差韵尾（ang 与 ai），意思是上面。", "善": "shàn（第四声）与 shài 韵母不同（an 与 ai），意思是善良。"}, "sentence_index": null, "correct_answer": "晒"}, "level_3": {"options": [{"text": "晒", "is_correct": true, "explanation": "正确。晒晒指把书放到太阳下弄干，与“天气好”相合。"}, {"text": "冻", "is_correct": false, "explanation": "语义：“冻”指寒冷，与“天气好”矛盾，天气好时不会要冻书。"}, {"text": "淋", "is_correct": false, "explanation": "搭配：“淋”说水浇落下来，不用于拿书出来晒。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指用火点燃，与把书拿出来晾一晾的意思相反。"}], "explanations": {"晒": "正确。晒晒指把书放到太阳下弄干，与“天气好”相合。", "冻": "语义：“冻”指寒冷，与“天气好”矛盾，天气好时不会要冻书。", "淋": "搭配：“淋”说水浇落下来，不用于拿书出来晒。", "烧": "语义：“烧”指用火点燃，与把书拿出来晾一晾的意思相反。"}, "sentence_index": 6, "correct_answer": "晒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把花拿到雨里晒了一下午。", "explanation": "这里的“晒”用错了：晒要靠太阳光把东西弄干或变热，让东西在雨中湿透应说“淋”，不能用“晒”。"}, {"text": "他把床单拿到屋外晒了一整夜。", "explanation": "这里的“晒”用错了：晒要在白天的阳光下进行，夜里没有太阳光，这里应说“放”，不能说“晒”。"}, {"text": "妈妈把湿鞋子放进冰箱里晒干。", "explanation": "这里的“晒”用错了：晒靠太阳光，冰箱是低温，不能让湿鞋子靠低温“晒”干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些衣服晒了干。", "corrected_sentence": "这些衣服晒干了。", "error_description": "错误：“晒干”中的结果补语“干”要紧跟在“晒”后面，“了”放在句末。“晒了干”语序不对，应说“这些衣服晒干了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件衣服洗完了，快拿去晒了吧。", "corrected_sentence": "这件衣服洗完了，快拿去晒吧。", "error_description": "错误：祈使语气“快……吧”中，“晒”后面不能加“了”。应去掉“了”，说“快拿去晒吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
