INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13627, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13627, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指风或气流使物体移动或飘动。", "primary_collocate": null, "pronunciation": "chuī dòng", "ipa": "tʂʰweɪ˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "很早以前，人们用风吹动风车来工作。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "风吹动叶片，叶片转动，可以磨面粉或抽水。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "风吹动叶片，叶片带动机器内部的零件转动，这样就能产生电了。", "target_word": "吹动", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "风吹动窗帘，房间里很凉快。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风吹动着树枝，发出沙沙的声音。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹动了河边的小草。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微风吹动她的头发，她笑了。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上的风吹动着小船，船慢慢往前走。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的风吹动落叶，落叶飘到地上。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开窗户，风吹动了桌上的纸。", "target_word": "吹动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吹动了", "label": "体标"}, {"form": "吹动着", "label": "体标"}, {"form": "吹动过", "label": "体标"}], "register": "中性", "sense_fingerprint": "风或气流使物体移动、飘动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8ddd3f-1e11-496c-a1ad-5495bc12503a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13627, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吹动", "is_correct": true, "explanation": "正确答案：吹动（chuī dòng），指风或气流使物体移动或飘动。"}, {"text": "推动", "is_correct": false, "explanation": "tuī（第一声）与 chuī（第一声）声母不同（t 与 ch），意思是用力使物体向前移动，不指风的作用。"}, {"text": "催动", "is_correct": false, "explanation": "cuī（第一声）与 chuī（第一声）声母不同（c 与 ch），意思是促使事物开始运转。"}, {"text": "出动", "is_correct": false, "explanation": "chū（第一声）与 chuī（第一声）韵母不同（少了 i 音），意思是派出人员或车辆行动。"}], "explanations": {"吹动": "正确答案：吹动（chuī dòng），指风或气流使物体移动或飘动。", "推动": "tuī（第一声）与 chuī（第一声）声母不同（t 与 ch），意思是用力使物体向前移动，不指风的作用。", "催动": "cuī（第一声）与 chuī（第一声）声母不同（c 与 ch），意思是促使事物开始运转。", "出动": "chū（第一声）与 chuī（第一声）韵母不同（少了 i 音），意思是派出人员或车辆行动。"}, "sentence_index": null, "correct_answer": "吹动"}, "level_3": {"options": [{"text": "吹动", "is_correct": true, "explanation": "正确：吹动表示风使风车转动，符合“用风”的语境。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”是使动作结束，与“用风来工作”的目的相反。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”要求人作施事，风不能修理风车。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使东西着火，风车不能靠被点燃来工作。"}], "explanations": {"吹动": "正确：吹动表示风使风车转动，符合“用风”的语境。", "停止": "语义：“停止”是使动作结束，与“用风来工作”的目的相反。", "修理": "配价：“修理”要求人作施事，风不能修理风车。", "点燃": "语义：“点燃”指使东西着火，风车不能靠被点燃来工作。"}, "sentence_index": 0, "correct_answer": "吹动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用力吹动了那辆车，车子慢慢往前走。", "explanation": "这里应该用〈推动〉。吹动要靠风或气流使物体动起来，人用力使车前进要用推动。"}, {"text": "妈妈吹动了那块大石头，把它搬到了屋外。", "explanation": "这里应该用〈搬动〉。吹动要靠风或气流，人挪动大石头要用搬动。"}, {"text": "地震的时候，房子吹动了很久。", "explanation": "这里应该用〈晃动〉。吹动的动力是风或气流，地震引起的摇晃要用晃动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13627, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吹动", "is_correct": true, "explanation": "正确：吹动表示微风使头发飘动，符合语境。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：“砍”一般接树木、柴草，不能说砍头发。"}, {"text": "割", "is_correct": false, "explanation": "搭配：“割”的对象多是草、麦等，不说割头发。"}, {"text": "染", "is_correct": false, "explanation": "体貌：“染”会改变头发的颜色，微风不能使头发变色。"}], "explanations": {"吹动": "正确：吹动表示微风使头发飘动，符合语境。", "砍": "搭配：“砍”一般接树木、柴草，不能说砍头发。", "割": "搭配：“割”的对象多是草、麦等，不说割头发。", "染": "体貌：“染”会改变头发的颜色，微风不能使头发变色。"}, "sentence_index": 6, "correct_answer": "吹动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她吹动手臂，向朋友打招呼。", "explanation": "这里应该用〈挥动〉。吹动要靠风或气流，人挥手臂要用挥动。"}, {"text": "她轻轻吹动琴弦，唱起歌来。", "explanation": "这里应该用〈拨动〉。吹动要靠风或气流，用手拨琴弦要用拨动。"}, {"text": "工人吹动了那个重箱子。", "explanation": "这里应该用〈拖动〉。吹动要靠风或气流，人用力移动箱子要用拖动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13627, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风吹动了了窗帘。", "corrected_sentence": "风吹动了窗帘。", "error_description": "动态助词错误：“了”重复。“吹动了”之后不能再加“了”，应为“风吹动了窗帘”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13627, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海风吹动了着远处的帆船。", "corrected_sentence": "海风吹动着远处的帆船。", "error_description": "动态助词错误：表示持续的“着”不能与“了”叠用，应为“海风吹动着远处的帆船”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
