INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13637, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容体积、数量、程度等超过一般，非常大。", "primary_collocate": null, "pronunciation": "dà dà de", "ipa": "ta˥˩ ta˥˩ tə", "syllable_count": 3, "sentences": [{"text": "他有一双大大的眼睛。", "target_word": "大大的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上放着一个大大的蛋糕。", "target_word": "大大的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给了我一个大大的拥抱。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们张着大大的嘴巴看魔术。", "target_word": "大大的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间有一扇大大的窗户。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他背着一个大大的书包去学校。", "target_word": "大大的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的耳朵大大的，很可爱。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家门口有一棵大大的树。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈买了一个大大的西瓜。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她高兴地笑了，脸上挂着大大的笑容。", "target_word": "大大的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "重叠式形容词，修饰名词，表示体积、数量、程度明显超过一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab33c06f-7df9-4a5c-b347-e98431a3920c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13637, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大大的", "is_correct": true, "explanation": "正确答案。dà dà de 即“体积、数量或程度超过一般”。"}, {"text": "哒哒的", "is_correct": false, "explanation": "dā dā de 与 dà dà de 只有声调不同（第一声与第四声），意思是拟声词，形容马蹄等的声音。"}, {"text": "嗒嗒的", "is_correct": false, "explanation": "dā dā de 与 dà dà de 只有声调不同（第一声与第四声），意思是拟声词，形容轻敲的声音。"}, {"text": "答答的", "is_correct": false, "explanation": "dá dá de 与 dà dà de 只有声调不同（第二声与第四声），意思是湿漉漉、水滴落的样子，如“湿答答的”。"}], "explanations": {"大大的": "正确答案。dà dà de 即“体积、数量或程度超过一般”。", "哒哒的": "dā dā de 与 dà dà de 只有声调不同（第一声与第四声），意思是拟声词，形容马蹄等的声音。", "嗒嗒的": "dā dā de 与 dà dà de 只有声调不同（第一声与第四声），意思是拟声词，形容轻敲的声音。", "答答的": "dá dá de 与 dà dà de 只有声调不同（第二声与第四声），意思是湿漉漉、水滴落的样子，如“湿答答的”。"}, "sentence_index": null, "correct_answer": "大大的"}, "level_3": {"options": [{"text": "大大的", "is_correct": true, "explanation": "正确答案。形容眼睛很大，符合句意。"}, {"text": "薄薄的", "is_correct": false, "explanation": "语义：“薄”形容物体的厚度小，眼睛不能用“薄”来形容。"}, {"text": "硬硬的", "is_correct": false, "explanation": "语义：“硬”形容质地，与描写眼睛的语境不合。"}, {"text": "热热的", "is_correct": false, "explanation": "搭配：“热”一般不用来描写“眼睛”，这一搭配不自然。"}], "explanations": {"大大的": "正确答案。形容眼睛很大，符合句意。", "薄薄的": "语义：“薄”形容物体的厚度小，眼睛不能用“薄”来形容。", "硬硬的": "语义：“硬”形容质地，与描写眼睛的语境不合。", "热热的": "搭配：“热”一般不用来描写“眼睛”，这一搭配不自然。"}, "sentence_index": 0, "correct_answer": "大大的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他讲了一个大大的道理。", "explanation": "这里应该用〈深刻〉。“大大的”多形容具体事物的形体或数量，抽象的“道理”要用“深刻”等。"}, {"text": "这次考试的成绩大大的，大家都很惊讶。", "explanation": "这里应该用〈高〉。“大大的”多形容具体事物的形体或数量，成绩一般说“高”。"}, {"text": "这个人的脸色大大的，看起来很健康。", "explanation": "这里应该用〈好〉。“大大的”形容体积、数量或程度，不能用来形容气色，应说“脸色好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大大的", "is_correct": true, "explanation": "正确答案。形容小狗的耳朵很大，符合句意。"}, {"text": "深深的", "is_correct": false, "explanation": "语义：“深”形容由表面到底部的距离大，不能用来形容耳朵的大小。"}, {"text": "甜甜的", "is_correct": false, "explanation": "搭配：“甜”一般用来形容味道或声音，不能用来描写“耳朵”。"}, {"text": "饱饱的", "is_correct": false, "explanation": "语义：“饱饱的”形容吃足或充满，用来描述耳朵不合常理，句意不通。"}], "explanations": {"大大的": "正确答案。形容小狗的耳朵很大，符合句意。", "深深的": "语义：“深”形容由表面到底部的距离大，不能用来形容耳朵的大小。", "甜甜的": "搭配：“甜”一般用来形容味道或声音，不能用来描写“耳朵”。", "饱饱的": "语义：“饱饱的”形容吃足或充满，用来描述耳朵不合常理，句意不通。"}, "sentence_index": 6, "correct_answer": "大大的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做事大大的，很让人放心。", "explanation": "这里应该用〈周到〉。“大大的”不用来形容做事的细致程度，应说“周到”。"}, {"text": "今天的天气大大的，很适合出门。", "explanation": "这里应该用〈晴朗〉。“大大的”指体积或程度，不能用来形容天气的状况，应说“晴朗”。"}, {"text": "他说话大大的，声音很轻。", "explanation": "这里应该用〈轻〉。“大大的”与「声音很轻」自相矛盾，“大大的”不用来描述说话的声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的手很大大的，很有力气。", "corrected_sentence": "她的手大大的，很有力气。", "error_description": "错误：“很大大的”。正确：“大大的”。“大大的”本身已表示程度，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "广场中央立着一座很大大的雕像。", "corrected_sentence": "广场中央立着一座大大的雕像。", "error_description": "错误：“很大大的”。正确：“大大的”。“大大的”本身已表示程度，前面不能再加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
