INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体围绕一个中心或轴做圆周运动。", "primary_collocate": null, "pronunciation": "zhuàn dòng", "ipa": "ʈʂwan⁵¹ tʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "风吹动叶片，叶片转动，可以磨面粉或抽水。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "风吹动叶片，叶片带动机器内部的零件转动，这样就能产生电了。", "target_word": "转动", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "地球绕着地轴不停地转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电风扇的叶片在快速转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮子转动起来，车就走了。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "驴拉着磨盘，磨盘慢慢转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "涡轮高速转动，发电机开始工作。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车床上的零件在飞快地转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风停了，风车就不再转动了。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "砂轮高速转动，火花四处飞。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转动了", "label": "体标"}, {"form": "转动着", "label": "体标"}, {"form": "转动过", "label": "体标"}, {"form": "轉動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体绕中心或轴做圆周运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f59174-23ab-4b8b-9546-74dc82c078e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转动", "is_correct": true, "explanation": "转动：物体围绕中心或轴做圆周运动。"}, {"text": "颤动", "is_correct": false, "explanation": "韵母不同：zhàn 没有 u 介音，颤动表示轻微地抖动，不是转圈。"}, {"text": "钻洞", "is_correct": false, "explanation": "声母不同：zuàn 的声母是 z，zhuàn 的声母是 zh，钻洞指在物体上打洞。"}, {"text": "传动", "is_correct": false, "explanation": "声母和声调都不同：chuán 的声母是 ch、读第二声，意思是动力的传递。"}, {"text": "窜动", "is_correct": false, "explanation": "声母不同：chuàn 的声母是 ch，意思是快速地乱窜。"}], "explanations": {"转动": "转动：物体围绕中心或轴做圆周运动。", "颤动": "韵母不同：zhàn 没有 u 介音，颤动表示轻微地抖动，不是转圈。", "钻洞": "声母不同：zuàn 的声母是 z，zhuàn 的声母是 zh，钻洞指在物体上打洞。", "传动": "声母和声调都不同：chuán 的声母是 ch、读第二声，意思是动力的传递。", "窜动": "声母不同：chuàn 的声母是 ch，意思是快速地乱窜。"}, "sentence_index": null, "correct_answer": "转动"}, "level_3": {"options": [{"text": "转动", "is_correct": true, "explanation": "正确。转动指叶片绕轴转圈，与“风吹动”和“可以磨面粉或抽水”相符。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”表示不动，与前面的“风吹动叶片”和后面的“可以磨面粉或抽水”矛盾。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物长大，与叶片被风吹动后的运动无关。"}, {"text": "转身", "is_correct": false, "explanation": "搭配：“转身”一般用于人或动物，不说叶片转身。"}], "explanations": {"转动": "正确。转动指叶片绕轴转圈，与“风吹动”和“可以磨面粉或抽水”相符。", "停止": "语义：“停止”表示不动，与前面的“风吹动叶片”和后面的“可以磨面粉或抽水”矛盾。", "生长": "语义：“生长”指生物长大，与叶片被风吹动后的运动无关。", "转身": "搭配：“转身”一般用于人或动物，不说叶片转身。"}, "sentence_index": 0, "correct_answer": "转动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把箱子转动到了门口。", "explanation": "这里应该用〈移动〉。转动指物体绕轴旋转；箱子从一处挪到另一处是平移，要用“移动”。"}, {"text": "妈妈在厨房里转动，忙着做饭。", "explanation": "这里应该用〈走动〉。转动只用于物体绕轴旋转，人在屋里来回走要用“走动”。"}, {"text": "抽屉在轨道上转动，推进去了。", "explanation": "这里应该用〈滑动〉。抽屉沿直线推拉是滑动，不是绕轴旋转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转动", "is_correct": true, "explanation": "正确。转动指涡轮绕轴高速运转，能带动发电机工作。"}, {"text": "静止", "is_correct": false, "explanation": "语义：“静止”与“高速”矛盾，涡轮不动，发电机就无法工作。"}, {"text": "倒塌", "is_correct": false, "explanation": "搭配：“倒塌”多指建筑、墙壁等坍塌，不说涡轮倒塌。"}, {"text": "变形", "is_correct": false, "explanation": "语义：“变形”指形状改变，与“高速”的运转状态不符，也带不动发电机。"}], "explanations": {"转动": "正确。转动指涡轮绕轴高速运转，能带动发电机工作。", "静止": "语义：“静止”与“高速”矛盾，涡轮不动，发电机就无法工作。", "倒塌": "搭配：“倒塌”多指建筑、墙壁等坍塌，不说涡轮倒塌。", "变形": "语义：“变形”指形状改变，与“高速”的运转状态不符，也带不动发电机。"}, "sentence_index": 6, "correct_answer": "转动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钟摆在左右转动。", "explanation": "这里应该用〈摆动〉。钟摆左右来回摆，不是绕轴转圈，要用“摆动”。"}, {"text": "窗帘在风里转动，来回飘。", "explanation": "这里应该用〈飘动〉。窗帘被风吹得来回飘，是左右摇摆，不是绕轴旋转。"}, {"text": "心脏在胸口里转动。", "explanation": "这里应该用〈跳动〉。心脏一起一伏地搏动要用“跳动”，转动指绕轴旋转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风扇转动的很快。", "corrected_sentence": "风扇转动得很快。", "error_description": "错误：动词后表示程度的补语要用“得”连接，不能用“的”，应说“转动得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机器把转动了。", "corrected_sentence": "机器转动了。", "error_description": "错误：“把”字句要有宾语，“转动”这里没有宾语，不能用“把”，应说“机器转动了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注水", "is_correct": true, "explanation": "正确答案。注水指把水灌入某处，与抽水的方向相反，构成反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与抽水的动作无关，不是它的反义词。"}, {"text": "读书", "is_correct": false, "explanation": "读书与抽水没有相对的关系，二者不是同类动作。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫与抽水没有反义关系，不是相对的动作。"}], "correct_answer": "注水", "explanations": {"注水": "正确答案。注水指把水灌入某处，与抽水的方向相反，构成反义关系。", "跑步": "跑步与抽水的动作无关，不是它的反义词。", "读书": "读书与抽水没有相对的关系，二者不是同类动作。", "打扫": "打扫与抽水没有反义关系，不是相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注水", "is_correct": true, "explanation": "正确答案。注水指把水灌入某处，与抽水的方向相反，构成反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌与抽水没有相对的关系，不是它的反义词。"}, {"text": "散步", "is_correct": false, "explanation": "散步与抽水的动作无关，不构成反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字与抽水没有反义关系，二者不是相对的动作。"}], "correct_answer": "注水", "explanations": {"注水": "正确答案。注水指把水灌入某处，与抽水的方向相反，构成反义关系。", "唱歌": "唱歌与抽水没有相对的关系，不是它的反义词。", "散步": "散步与抽水的动作无关，不构成反义关系。", "写字": "写字与抽水没有反义关系，二者不是相对的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过水泵或类似设备将水从低处或水池中取出并输送到别处。", "primary_collocate": null, "pronunciation": "chōu shuǐ", "ipa": "ʈʂʰoʊ˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "风吹动叶片，叶片转动，可以磨面粉或抽水。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "农民用机器给田地抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨后，工人们在地下室抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台水泵每小时能抽水五吨。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河里没有水了，村民只好到井边抽水。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在池塘边抽水，想把鱼捉住。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用大机器抽水，房子很快就干了。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管坏了，我们没法抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暴雨后，消防员在街上抽水，积水很快就退了。", "target_word": "抽水", "complexity_tier": "T3", "furigana": "bào yǔ hòu, xiāofángyuán zài jiē shàng chōu shuǐ, jī shuǐ hěn kuài jiù tuì le.", "sentence_source": "generated"}, {"text": "夏天太干，农民每天都要抽水浇地。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽了水", "label": "体标：了"}, {"form": "抽过水", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "离合动词，用机器把水从低处或水池抽出送到别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab33c06f-7df9-4a5c-b347-e98431a3920c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抽水", "is_correct": true, "explanation": "正确答案。chōu shuǐ 指用水泵把水从低处或水池中取出并送到别处。"}, {"text": "冲水", "is_correct": false, "explanation": "冲水（chōng shuǐ）与抽水的韵母不同（ong 与 ou），意思是用水冲洗，不是取水。"}, {"text": "出水", "is_correct": false, "explanation": "出水（chū shuǐ）与抽水的韵母不同（u 与 ou），意思是水从里面流出，不是用机器取水。"}, {"text": "臭水", "is_correct": false, "explanation": "臭水（chòu shuǐ）与抽水的声调不同（第四声与第一声），意思是难闻的水。"}, {"text": "抽税", "is_correct": false, "explanation": "抽税（chōu shuì）与抽水的第二个音节声调不同（第四声与第三声），意思是征收税款。"}], "explanations": {"抽水": "正确答案。chōu shuǐ 指用水泵把水从低处或水池中取出并送到别处。", "冲水": "冲水（chōng shuǐ）与抽水的韵母不同（ong 与 ou），意思是用水冲洗，不是取水。", "出水": "出水（chū shuǐ）与抽水的韵母不同（u 与 ou），意思是水从里面流出，不是用机器取水。", "臭水": "臭水（chòu shuǐ）与抽水的声调不同（第四声与第一声），意思是难闻的水。", "抽税": "抽税（chōu shuì）与抽水的第二个音节声调不同（第四声与第三声），意思是征收税款。"}, "sentence_index": null, "correct_answer": "抽水"}, "level_3": {"options": [{"text": "抽水", "is_correct": true, "explanation": "正确答案。“可以磨面粉或抽水”指风车还能用来把水抽出，与前文风车的用途一致。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：风车靠风力转动，唱歌不是它的功能，与“磨面粉”并列也说不通。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”后面要接说的内容，此处缺少宾语，句子不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：风车是机器，不会睡觉，与“风吹动叶片，叶片转动”的描述矛盾。"}], "explanations": {"抽水": "正确答案。“可以磨面粉或抽水”指风车还能用来把水抽出，与前文风车的用途一致。", "唱歌": "语义：风车靠风力转动，唱歌不是它的功能，与“磨面粉”并列也说不通。", "说": "配价：“说”后面要接说的内容，此处缺少宾语，句子不成立。", "睡觉": "语义：风车是机器，不会睡觉，与“风吹动叶片，叶片转动”的描述矛盾。"}, "sentence_index": 0, "correct_answer": "抽水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水库闸门一开，水就往下游抽水灌溉。", "explanation": "这里应该用〈放水〉。抽水需要水泵把水吸走，闸门打开后水自己流下去，要说放水，不能说抽水。"}, {"text": "护士用针管从病人手臂上抽水，准备化验。", "explanation": "这里应该用〈抽血〉。抽水是用水泵把水输送走，从人体里取血要说抽血，不能说抽水。"}, {"text": "小猫在河边抽水，喝得很开心。", "explanation": "这里应该用〈喝水〉。抽水要借助水泵，小猫是自己低头饮水，不能说抽水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽水", "is_correct": true, "explanation": "正确答案。用大机器把积水抽走，房子才很快干了。"}, {"text": "吃", "is_correct": false, "explanation": "语义：机器不吃东西，“吃”与“房子很快就干了”的因果也对不上。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：大机器不会跳舞，与“工人用”的描述不相符。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要宾语，此处缺失，句子不完整。"}], "explanations": {"抽水": "正确答案。用大机器把积水抽走，房子才很快干了。", "吃": "语义：机器不吃东西，“吃”与“房子很快就干了”的因果也对不上。", "跳舞": "语义：大机器不会跳舞，与“工人用”的描述不相符。", "写": "配价：“写”需要宾语，此处缺失，句子不完整。"}, "sentence_index": 6, "correct_answer": "抽水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "干燥的季节，他每天都给皮肤抽水。", "explanation": "这里应该用〈补水〉。抽水是把水取出送走，不能用来给皮肤增加水分。"}, {"text": "屋檐还在一滴一滴地抽水。", "explanation": "这里应该用〈滴水〉。抽水是用机器把水取出，屋檐的水是自己往下滴，不能说抽水。"}, {"text": "纸巾可以抽水，擦干桌子。", "explanation": "这里应该用〈吸水〉。抽水是用水泵把水送到别处，纸巾靠纤维把水吸进去，不能说抽水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们昨天一个抽水，地下室才干了。", "corrected_sentence": "他们昨天一次抽水，地下室才干了。", "error_description": "错误在数量词：“抽水”这一动作应用动量词“次”计量，不能用“个”。正确：“一次抽水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人抽水着，房子慢慢干了。", "corrected_sentence": "工人抽着水，房子慢慢干了。", "error_description": "错误在“着”的位置：“着”表示动作持续，应紧跟动词，写成“抽着水”，不能放在“抽水”后面说“抽水着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
