INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13641, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在秘密或违法活动中，安排人警戒、观察周围动静，以防被人发现或打扰。", "primary_collocate": null, "pronunciation": "bǎ fēng", "ipa": "pa˨˩˦ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他在巷子口把风，见有人来就咳嗽一声。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷进屋偷东西，另一个人在门外把风。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在楼下把风，怕有人上来。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你去里面拿，我在门口给你把风。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察来了，在外面把风的人马上跑了。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们偷偷摘果子，小明负责把风。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人在路口把风，看见警察就吹口哨。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个人，两个进去，一个在外面把风。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在门口把风，怕妈妈突然回家。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板不在，你帮我在门口把风。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "把了风", "label": "体标：了"}, {"form": "把过风", "label": "体标：过"}], "register": "口语", "sense_fingerprint": "离合动词，秘密行动时在外面望风警戒，防止被人发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab33c06f-7df9-4a5c-b347-e98431a3920c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "把风", "is_correct": true, "explanation": "正确答案。“他在巷子口把风，见有人来就咳嗽一声”中的“把风”指望风警戒、提前报信，与句意相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：在巷口唱歌无法起到望风报信的作用，与“见有人来就咳嗽一声”的警戒意图不符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：在巷口吃饭不能起到警戒作用，与“见有人来就咳嗽一声”的意思不合。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”后面要接说的内容，此处缺少宾语，句子不成立。"}], "explanations": {"把风": "正确答案。“他在巷子口把风，见有人来就咳嗽一声”中的“把风”指望风警戒、提前报信，与句意相符。", "唱歌": "语义：在巷口唱歌无法起到望风报信的作用，与“见有人来就咳嗽一声”的警戒意图不符。", "吃饭": "语义：在巷口吃饭不能起到警戒作用，与“见有人来就咳嗽一声”的意思不合。", "说": "配价：“说”后面要接说的内容，此处缺少宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "把风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "监狱里的犯人每天把风半小时。", "explanation": "这里应该用〈放风〉。把风指在外面望风警戒，不是让犯人出来透气活动。"}, {"text": "他每天早上在公园把风，锻炼身体。", "explanation": "这里应该用〈锻炼〉。把风指秘密或违法活动中望风警戒，与体育锻炼无关。"}, {"text": "屋里太闷了，应该赶快把风。", "explanation": "这里应该用〈通风〉。把风是守望警戒，不是让空气流通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "把风", "is_correct": true, "explanation": "正确答案。那个人在路口望风警戒，看见警察就吹口哨报警。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时看不见警察，与“看见警察就吹口哨”的描述矛盾。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要宾语，此处缺失，句子不完整。"}, {"text": "骑", "is_correct": false, "explanation": "配价：“骑”后面要接被骑的东西，此处缺少宾语，句子不成立。"}], "explanations": {"把风": "正确答案。那个人在路口望风警戒，看见警察就吹口哨报警。", "睡觉": "语义：睡觉时看不见警察，与“看见警察就吹口哨”的描述矛盾。", "写": "配价：“写”需要宾语，此处缺失，句子不完整。", "骑": "配价：“骑”后面要接被骑的东西，此处缺少宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "把风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气很冷，他在窗前把风，身子直发抖。", "explanation": "这里应该用〈挡风〉。把风是守望警戒，不是阻挡风。"}, {"text": "晚上，他喜欢在阳台把风。", "explanation": "这里应该用〈吹风〉。把风是守望警戒，不是让风吹到身上。"}, {"text": "天热得很，他拿着扇子把风。", "explanation": "这里应该用〈扇风〉。把风是守望警戒，不能说用扇子把风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在楼下一个把风，怕有人上来。", "corrected_sentence": "他们在楼下把了一会儿风，怕有人上来。", "error_description": "错误在时量词：“把风”前不能直接用“一个”计量，应写成“把了一会儿风”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王在路口把风着，看见车就喊。", "corrected_sentence": "小王在路口把着风，看见车就喊。", "error_description": "错误在体标“着”的位置：“着”应紧跟“把”，写成“把着风”，表示动作持续；不能放在“风”后面写成“把风着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
