INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "风的大小或强度，通常用等级表示。", "primary_collocate": null, "pronunciation": "fēng lì", "ipa": "fɤŋ˥˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "海上风电场的兴起更将发电装置迁移至风力更稳定强劲的大陆架区域。", "target_word": "风力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "现代风力涡轮机已集成智能控制系统：激光雷达预判风速变化，实时调节桨距角以优化转矩；数字孪生技术则构建虚拟机组模型，实现故障预测性维护。", "target_word": "风力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工程师发明了风力发电机。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "风力发电机可以发电。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "从风车到风力发电机，从最早的实验到现代的太阳能电站，清洁能源的发展有很长的历史。", "target_word": "风力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今天风力很大，我们不去爬山了。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气预报说明天风力有六级。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风力太强，船不能出海。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风来的时候，风力会变得很大。", "target_word": "风力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶的风力比山下大得多。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "风力发电", "label": "复合"}, {"form": "风力发电机", "label": "复合"}], "register": "中性", "sense_fingerprint": "风的大小或强度，用等级表示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f59174-23ab-4b8b-9546-74dc82c078e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风力", "is_correct": true, "explanation": "正确。风力指风的强度，风电场迁移到风力更稳定强劲的区域，语义相符。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：“湿度”指空气的潮湿程度，不能说“更稳定强劲”。"}, {"text": "风向", "is_correct": false, "explanation": "搭配：“风向”指风吹来的方向，不能用“强劲”来形容。"}, {"text": "气温", "is_correct": false, "explanation": "语义：“气温”指冷热程度，不能用“强劲”形容。"}], "explanations": {"风力": "正确。风力指风的强度，风电场迁移到风力更稳定强劲的区域，语义相符。", "湿度": "语义：“湿度”指空气的潮湿程度，不能说“更稳定强劲”。", "风向": "搭配：“风向”指风吹来的方向，不能用“强劲”来形容。", "气温": "语义：“气温”指冷热程度，不能用“强劲”形容。"}, "sentence_index": 0, "correct_answer": "风力"}, "level_6": {"correct_sentence_index": 5, "wrong_sentences": [{"text": "风力从东边转到了北边。", "explanation": "这里应该用〈风向〉。风力指风的大小或强度，不指风吹来的方向。"}, {"text": "这场台风的风力达到每秒十五米。", "explanation": "这里应该用〈风速〉。风速才用“每秒多少米”计量，风力通常用等级表示。"}, {"text": "他的风力很大，能搬动那块石头。", "explanation": "这里应该用〈力气〉。风力只指风的力量，不能用来说人的力气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风力", "is_correct": true, "explanation": "正确。风力用等级表示风的强度，“有六级”与之相符。"}, {"text": "气温", "is_correct": false, "explanation": "搭配：“气温”一般用度数表示，不说有几级。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人体的温度，与天气预报无关，不说有几级。"}, {"text": "能见度", "is_correct": false, "explanation": "语义：“能见度”指看得多远，与风的等级无关。"}], "explanations": {"风力": "正确。风力用等级表示风的强度，“有六级”与之相符。", "气温": "搭配：“气温”一般用度数表示，不说有几级。", "体温": "语义：“体温”指人体的温度，与天气预报无关，不说有几级。", "能见度": "语义：“能见度”指看得多远，与风的等级无关。"}, "sentence_index": 6, "correct_answer": "风力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他学习很有风力，从不放弃。", "explanation": "这里应该用〈毅力〉。风力只指风的力量，不能用来形容人的意志。"}, {"text": "他的写作风力很独特。", "explanation": "这里应该用〈风格〉。风力指风的力量，不能用来说文章或作品的风格。"}, {"text": "她的风力很迷人。", "explanation": "这里应该用〈魅力〉。风力指风的力量，不能用来形容人的吸引力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天风力有四个。", "corrected_sentence": "今天风力有四级。", "error_description": "错误：风力的量词用错。风力等级要用“级”，应说“四级”，不说“四个”。", "correct_sentence_indices": [0, 5, 8]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们感受到一只很大的风力。", "corrected_sentence": "我们感受到一股很大的风力。", "error_description": "错误：风力的量词用错。风力常用“股”计量，应说“一股很大的风力”，不说“一只很大的风力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
