INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13643, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "将机械能、化学能等转换为电能的装置。", "primary_collocate": null, "pronunciation": "fā diàn jī", "ipa": "fa⁵⁵ tjɛn⁵¹ tɕi⁵⁵", "syllable_count": 3, "sentences": [{"text": "工程师发明了一台用风力工作的发电机。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台发电机可以连续发电，不需要用油。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从最早的实验到现代的工厂，发电机的样子变化很大，效率也提高了很多。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台发电机很大，工厂停电时可以用它。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院买了一台发电机，停电时也有电用。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的发电机每天晚上都要开两个小时。", "target_word": "发电机", "complexity_tier": "T3", "furigana": "cūn lǐ de fā diàn jī měi tiān wǎn shang dōu yào kāi liǎng gè xiǎo shí.", "sentence_source": "generated"}, {"text": "山里没有电，他们用小发电机给手机充电。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发电机坏了，我们只好点着蜡烛吃饭。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发电机一转起来，灯就亮了。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查发电机有没有问题。", "target_word": "发电机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "风力发电机", "label": "复合"}, {"form": "水力发电机", "label": "复合"}], "register": "中性", "sense_fingerprint": "把机械能等转换成电能的装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87c5817-34a3-497b-90f4-3778d20342d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13643, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发电机", "is_correct": true, "explanation": "正确：「用风力工作的发电机」能把风的机械能变成电能，符合「发明」的对象。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：「风力」指风能，蛋糕不是能源装置，「风力蛋糕」说不通。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发不是能源装置，「用风力工作的沙发」说不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：「风力」修饰能源装置，不能修饰饮品，「风力咖啡」不成立。"}], "explanations": {"发电机": "正确：「用风力工作的发电机」能把风的机械能变成电能，符合「发明」的对象。", "蛋糕": "语义：「风力」指风能，蛋糕不是能源装置，「风力蛋糕」说不通。", "沙发": "语义：沙发不是能源装置，「用风力工作的沙发」说不通。", "咖啡": "搭配：「风力」修饰能源装置，不能修饰饮品，「风力咖啡」不成立。"}, "sentence_index": 0, "correct_answer": "发电机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台发电机用来搅拌蛋糕糊，很省力。", "explanation": "这里应该用〈搅拌机〉。搅拌机负责搅拌食物，发电机是把能量转成电的装置，不能用来搅拌蛋糕糊。"}, {"text": "发电机把电能变成机械能，让风扇转起来。", "explanation": "这里应该用〈电动机〉。电动机把电能变成机械能；发电机正相反，是把机械能变成电能。"}, {"text": "这台发电机每天晚上能让牛奶保持冰凉。", "explanation": "这里应该用〈冰箱〉。冰箱靠制冷保持食物低温，发电机不能制冷，也不能让牛奶变凉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13643, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发电机", "is_correct": true, "explanation": "正确：山里没有电，需要能产生电的小机器，只有发电机能提供电。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡是用电的器具，不能产生电给手机充电。"}, {"text": "烤箱", "is_correct": false, "explanation": "搭配：「给手机充电」需要电源，烤箱是用电器，不能为手机供电。"}, {"text": "收音机", "is_correct": false, "explanation": "语义：收音机接收信号、消耗电，不能产生电给手机充电。"}], "explanations": {"发电机": "正确：山里没有电，需要能产生电的小机器，只有发电机能提供电。", "灯泡": "语义：灯泡是用电的器具，不能产生电给手机充电。", "烤箱": "搭配：「给手机充电」需要电源，烤箱是用电器，不能为手机供电。", "收音机": "语义：收音机接收信号、消耗电，不能产生电给手机充电。"}, "sentence_index": 6, "correct_answer": "发电机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台发电机能把墙上的灰尘吸干净。", "explanation": "这里应该用〈吸尘器〉。吸尘器靠吸力清除灰尘，发电机不能吸灰尘。"}, {"text": "这台发电机把水烧开，给工厂提供热水。", "explanation": "这里应该用〈锅炉〉。锅炉用来烧水，发电机只把能量变成电，不能烧水。"}, {"text": "这个发电机能把插座的电传给手机。", "explanation": "这里应该用〈充电器〉。充电器负责把电输送给设备，发电机是产生电的，不能把插座的电传过去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们厂买了一把新发电机。", "corrected_sentence": "我们厂买了一台新发电机。", "error_description": "量词错误：发电机是机器，应该用「台」，写作「一台新发电机」；「把」用于有柄或有把手的东西，不能用于发电机。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人修了好那台发电机。", "corrected_sentence": "工人修好了那台发电机。", "error_description": "补语错误：「好」是动词「修」的结果补语，要紧跟在动词后面，写作「修好了」；「修了好」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
