INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13645, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引导事物向前发展或使别人跟着自己的行动。", "primary_collocate": null, "pronunciation": "dài dòng", "ipa": "tai⁵¹ tʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这位老板的努力带动了全公司的进步。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项新政策带动了农村经济的发展。", "target_word": "带动", "complexity_tier": "T3", "furigana": "zhè xiàng xīn zhèng cè dài dòng le nóng cūn jīng jì de fā zhǎn", "sentence_source": "generated"}, {"text": "他的好成绩带动了全班同学努力学习。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工厂带动了这个小镇的发展。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带动大家一起唱歌。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位班长的积极态度带动了全班的学习热情。", "target_word": "带动", "complexity_tier": "T3", "furigana": "zhè wèi bān zhǎng de jī jí tài du dài dòng le quán bān de xué xí rè qíng", "sentence_source": "generated"}, {"text": "小王的热情带动了身边的人。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游带动了当地的经济。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公益项目带动了很多志愿者参与社区服务。", "target_word": "带动", "complexity_tier": "T3", "furigana": "zhè ge gōng yì xiàng mù dài dòng le hěn duō zhì yuàn zhě cān yǔ shè qū fú wù", "sentence_source": "generated"}, {"text": "好的领导能带动整个团队进步。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带动了", "label": "体标"}, {"form": "带动着", "label": "体标"}, {"form": "带动过", "label": "体标"}], "register": "中性", "sense_fingerprint": "引导事物发展或使别人跟着行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87c5817-34a3-497b-90f4-3778d20342d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13645, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带动", "is_correct": true, "explanation": "正确答案：带动（dài dòng），引导事物向前发展，或使别人跟着自己的行动。"}, {"text": "大洞", "is_correct": false, "explanation": "dà 与 dài 声调相同，只差韵母 -i，意思是“大洞”。"}, {"text": "耐冻", "is_correct": false, "explanation": "nài 与 dài 声母不同（n 与 d），声调相同，意思是“耐冻”。"}, {"text": "带痛", "is_correct": false, "explanation": "tòng 与 dòng 声母不同（t 与 d），声调相同，意思是“带着疼痛”。"}, {"text": "带通", "is_correct": false, "explanation": "tōng（第一声）与 dòng（第四声）声母和声调都不同，意思是“带通”，属于专业用语。"}], "explanations": {"带动": "正确答案：带动（dài dòng），引导事物向前发展，或使别人跟着自己的行动。", "大洞": "dà 与 dài 声调相同，只差韵母 -i，意思是“大洞”。", "耐冻": "nài 与 dài 声母不同（n 与 d），声调相同，意思是“耐冻”。", "带痛": "tòng 与 dòng 声母不同（t 与 d），声调相同，意思是“带着疼痛”。", "带通": "tōng（第一声）与 dòng（第四声）声母和声调都不同，意思是“带通”，属于专业用语。"}, "sentence_index": null, "correct_answer": "带动"}, "level_3": {"options": [{"text": "带动", "is_correct": true, "explanation": "正确：「带动」表示引导事物向前发展，「这位老板的努力带动了全公司的进步」符合句意。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：「阻止」与「进步」意思相反，「阻止了全公司的进步」与「努力」的正面语境矛盾。"}, {"text": "拖累", "is_correct": false, "explanation": "语义：「拖累」是妨碍、拖后腿，与「努力」的正面语境相反，句子说不通。"}, {"text": "依靠", "is_correct": false, "explanation": "搭配：「依靠」后接可依靠的人或力量，「依靠了全公司的进步」说不通。"}], "explanations": {"带动": "正确：「带动」表示引导事物向前发展，「这位老板的努力带动了全公司的进步」符合句意。", "阻止": "语义：「阻止」与「进步」意思相反，「阻止了全公司的进步」与「努力」的正面语境矛盾。", "拖累": "语义：「拖累」是妨碍、拖后腿，与「努力」的正面语境相反，句子说不通。", "依靠": "搭配：「依靠」后接可依靠的人或力量，「依靠了全公司的进步」说不通。"}, "sentence_index": 0, "correct_answer": "带动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天带动一箱牛奶上楼。", "explanation": "这里应该用〈搬〉。带动表示引导事物发展或使别人跟着行动，搬运东西上楼要用「搬」，不能说「带动」。"}, {"text": "这次合作带动了不少麻烦。", "explanation": "这里应该用〈带来〉。带动表示带领、促使事物向前发展，带来不好的结果要用带来。"}, {"text": "这个消息带动他离开了公司。", "explanation": "这里应该用〈促使〉。带动多指带头或引导他人跟着行动、让事情向前发展，消息让人做出决定要用促使。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13645, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "带动", "is_correct": true, "explanation": "正确答案：带动（dài dòng），引导事物向前发展，或使别人跟着自己的行动。"}, {"text": "抬动", "is_correct": false, "explanation": "tái 与 dài 声母不同（t 与 d），声调也不同（第二声与第四声），意思是“抬起来移动”。"}, {"text": "大动", "is_correct": false, "explanation": "dà 与 dài 声调相同，只差韵母 -i，意思是“大幅度、大动作”。"}, {"text": "再动", "is_correct": false, "explanation": "zài 与 dài 声母不同（z 与 d），声调相同，意思是“再次行动”。"}], "explanations": {"带动": "正确答案：带动（dài dòng），引导事物向前发展，或使别人跟着自己的行动。", "抬动": "tái 与 dài 声母不同（t 与 d），声调也不同（第二声与第四声），意思是“抬起来移动”。", "大动": "dà 与 dài 声调相同，只差韵母 -i，意思是“大幅度、大动作”。", "再动": "zài 与 dài 声母不同（z 与 d），声调相同，意思是“再次行动”。"}, "sentence_index": null, "correct_answer": "带动"}, "level_3": {"options": [{"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”与“热情”矛盾，热情的人不会冷落身边的人。"}, {"text": "带动", "is_correct": true, "explanation": "“小王的热情带动了身边的人”表示热情影响了周围的人，符合句意。"}, {"text": "浪费", "is_correct": false, "explanation": "搭配：“浪费”的对象多是钱财、时间、资源，不能说“浪费了身边的人”。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”与“热情”矛盾，句子的意思被颠倒了。"}], "explanations": {"冷落": "语义：“冷落”与“热情”矛盾，热情的人不会冷落身边的人。", "带动": "“小王的热情带动了身边的人”表示热情影响了周围的人，符合句意。", "浪费": "搭配：“浪费”的对象多是钱财、时间、资源，不能说“浪费了身边的人”。", "忽视": "语义：“忽视”与“热情”矛盾，句子的意思被颠倒了。"}, "sentence_index": 6, "correct_answer": "带动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天细心带动生病的爷爷。", "explanation": "这里应该用〈照顾〉。带动指引导事物发展或使别人跟着行动，照顾指关心并料理病人，不能说“带动”爷爷。"}, {"text": "警察带动了那个嫌疑人。", "explanation": "这里应该用〈带走〉。带动是引导发展或促使跟着行动，把人带离某处要用带走。"}, {"text": "他每天带动汽车去上班。", "explanation": "这里应该用〈驾驶〉。带动不能用来说操纵车辆，开车上班要用驾驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新的交通线了带动沿线城市的发展。", "corrected_sentence": "新的交通线带动沿线城市的发展。", "error_description": "“了”放错了位置：“带动”前不能加“了”，应去掉，写成“新的交通线带动沿线城市的发展”；若要表示完成，“了”应放在“带动”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂的新产品带动得附近的服务业。", "corrected_sentence": "这家工厂的新产品带动了附近的服务业。", "error_description": "“得”放错了（应为“了”）：“带动”后面表示已经发生应用“了”，写成“带动得”后不能直接接“附近的服务业”，应说“带动了附近的服务业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "持续地创造新事物或提出新想法。", "primary_collocate": null, "pronunciation": "bú duàn chuàng xīn", "ipa": "pu˧˥ tuan˥˩ ʈʂʰuaŋ˥˩ ɕin˥", "syllable_count": 4, "sentences": [{"text": "但经过不断创新，它变得越来越便宜，也更好用了。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这家公司想一直做得好，就必须不断创新。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家们不断创新，才发明了这种新电池。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有不断创新，我们的产品才能卖得好。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不断创新，让手机的功能越来越多。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师不断创新教学方法，学生都喜欢上他的课。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不断创新是这家小店成功的原因。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让工作更有意思，你要不断创新。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民不断创新种田的办法，今年的粮食更多了。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市不断创新，现在已经是有名的科技中心。", "target_word": "不断创新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不断地创新", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "持续地创造新事物或提出新想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87c5817-34a3-497b-90f4-3778d20342d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不断涨价", "is_correct": false, "explanation": "语义：“不断涨价”与“变得越来越便宜”矛盾，涨价不会让东西越来越便宜。"}, {"text": "不断创新", "is_correct": true, "explanation": "“经过不断创新，它变得越来越便宜，也更好用了”前后连贯，是正确答案。"}, {"text": "不断退步", "is_correct": false, "explanation": "语义：“不断退步”与“也更好用了”矛盾，退步不会让东西变得更好用。"}, {"text": "不断堆积", "is_correct": false, "explanation": "搭配：“堆积”指东西越积越多，不能用来表示使商品变便宜的过程。"}], "explanations": {"不断涨价": "语义：“不断涨价”与“变得越来越便宜”矛盾，涨价不会让东西越来越便宜。", "不断创新": "“经过不断创新，它变得越来越便宜，也更好用了”前后连贯，是正确答案。", "不断退步": "语义：“不断退步”与“也更好用了”矛盾，退步不会让东西变得更好用。", "不断堆积": "搭配：“堆积”指东西越积越多，不能用来表示使商品变便宜的过程。"}, "sentence_index": 0, "correct_answer": "不断创新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天不断创新学习英语。", "explanation": "这里应该用〈努力〉。不断创新指持续想出新东西，学习英语要用努力，不能用创新。"}, {"text": "我们正在不断创新产品的质量。", "explanation": "这里应该用〈改进〉。创新是提出新事物或新想法，提高质量要用改进。"}, {"text": "他不断创新同样的错误。", "explanation": "这里应该用〈重复〉。不断创新是持续想出新东西，同样的错误反复出现要用重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不断亏损", "is_correct": false, "explanation": "语义：“不断亏损”与“成功的原因”矛盾，亏损不可能是成功的原因。"}, {"text": "不断创新", "is_correct": true, "explanation": "“不断创新是这家小店成功的原因”表示持续创新带来了成功，符合句意。"}, {"text": "不断偷懒", "is_correct": false, "explanation": "语义：“不断偷懒”与“成功的原因”矛盾，偷懒不会带来成功。"}, {"text": "不断抱怨", "is_correct": false, "explanation": "搭配：“抱怨”是表达不满的动作，不适合作为“成功的原因”的主语。"}], "explanations": {"不断亏损": "语义：“不断亏损”与“成功的原因”矛盾，亏损不可能是成功的原因。", "不断创新": "“不断创新是这家小店成功的原因”表示持续创新带来了成功，符合句意。", "不断偷懒": "语义：“不断偷懒”与“成功的原因”矛盾，偷懒不会带来成功。", "不断抱怨": "搭配：“抱怨”是表达不满的动作，不适合作为“成功的原因”的主语。"}, "sentence_index": 6, "correct_answer": "不断创新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "侦探不断创新线索。", "explanation": "这里应该用〈寻找〉。不断创新指持续想出新东西，找线索要用寻找。"}, {"text": "妈妈不断创新孩子的作业。", "explanation": "这里应该用〈检查〉。不断创新是持续想出新东西，查看作业有没有错要用检查。"}, {"text": "他不断创新一杯水，然后喝了下去。", "explanation": "这里应该用〈喝〉。不断创新指持续想出新东西，喝水要用「喝」，不能说「创新一杯水」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司正在不断创新了，产品越来越好。", "corrected_sentence": "这家公司正在不断创新，产品越来越好。", "error_description": "“正在”表示动作正在进行，“创新”后面不能再加“了”，应去掉“了”，说“正在不断创新”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只要不断创新了，企业就会发展。", "corrected_sentence": "只要不断创新，企业就会发展。", "error_description": "“只要……”引出的假设条件表示未发生的情况，“不断创新”后不能加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
