INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13647, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沙漠是指降水极少、植被稀疏、地表以沙或岩石为主的地带。", "primary_collocate": null, "pronunciation": "shā mò", "ipa": "ʂa˥ mo˥˩", "syllable_count": 2, "sentences": [{"text": "今天，在屋顶、沙漠甚至太空中，都能看到太阳能电池板。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "沙漠里很少下雨，植物也很少。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的沙漠白天热得像火一样。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们骑着骆驼走过沙漠，一路上没有看到河。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠的夜晚很冷，旅行的人要带上厚衣服。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片沙漠很大，走几天也看不到城市。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里很少下雨，慢慢变成了沙漠。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，沙漠上的沙子就飞起来。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的植物有很深的根，才能找到水。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在沙漠里找到一口井，大家都很高兴。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "沙漠化", "label": "复合"}], "register": "中性", "sense_fingerprint": "降水极少、植被稀疏的沙地或岩石地带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87c5817-34a3-497b-90f4-3778d20342d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沙漠", "is_correct": true, "explanation": "“沙漠”指降水极少的地带，与“屋顶”“太空”并列，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书本的袋子，不是能看到太阳能电池板的地方，与“屋顶”“太空”并列不合理。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是艺术作品，不是可以安装电池板的场所，不能作为“中”前面的地点。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是能安装太阳能电池板的地方，与“屋顶”“太空”并列不合理。"}], "explanations": {"沙漠": "“沙漠”指降水极少的地带，与“屋顶”“太空”并列，符合句意。", "书包": "语义：书包是装书本的袋子，不是能看到太阳能电池板的地方，与“屋顶”“太空”并列不合理。", "歌曲": "语义：歌曲是艺术作品，不是可以安装电池板的场所，不能作为“中”前面的地点。", "课本": "语义：课本是书，不是能安装太阳能电池板的地方，与“屋顶”“太空”并列不合理。"}, "sentence_index": 0, "correct_answer": "沙漠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天到了，沙漠开始融化，河水涨了起来。", "explanation": "这里应该用〈冰川〉。冰川融化后会汇成河水；沙漠是干燥的沙石地带，不会融化，这里的“沙漠”用法不对。"}, {"text": "我的鞋里全是沙漠。", "explanation": "这里应该用〈沙子〉。沙子是颗粒状的材料，能钻进鞋里；沙漠指地区，不能当作装在鞋里的东西。"}, {"text": "昨天的沙漠让天空变得发黄。", "explanation": "这里应该用〈沙尘暴〉。沙尘暴是一种天气现象，能让天空发黄；沙漠只是地区，不会造成这种天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙漠", "is_correct": true, "explanation": "“沙漠”指降水极少的地带，与“很少下雨”的前提一致，“慢慢变成了”的结果也合理。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：湖泊需要充足的水，与“很少下雨”的前提矛盾。"}, {"text": "沼泽", "is_correct": false, "explanation": "语义：沼泽是积水很多的湿地，与“很少下雨”的前提矛盾。"}, {"text": "泽国", "is_correct": false, "explanation": "语域：“泽国”是文言式说法，指水很多的地方，与口语化的叙述不协调。"}], "explanations": {"沙漠": "“沙漠”指降水极少的地带，与“很少下雨”的前提一致，“慢慢变成了”的结果也合理。", "湖泊": "语义：湖泊需要充足的水，与“很少下雨”的前提矛盾。", "沼泽": "语义：沼泽是积水很多的湿地，与“很少下雨”的前提矛盾。", "泽国": "语域：“泽国”是文言式说法，指水很多的地方，与口语化的叙述不协调。"}, "sentence_index": 6, "correct_answer": "沙漠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，就去吃沙漠充饥。", "explanation": "“吃”的对象应是食物，沙漠是地区，不能吃，这里的“沙漠”用法不对。"}, {"text": "他一早就穿上沙漠，走进了教室。", "explanation": "“穿”的对象应是衣物，沙漠不能穿，这里的“沙漠”用法不对。"}, {"text": "她渴得厉害，跑过去喝沙漠。", "explanation": "“喝”的对象应是液体，沙漠是地区，不能喝，这里的“沙漠”用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们穿过了一大只沙漠。", "corrected_sentence": "我们穿过了一大片沙漠。", "error_description": "“沙漠”的量词应该用“片”，写成“只”是错误的。“只”多用于动物，指一大片地面要用“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于走出了一沙漠。", "corrected_sentence": "他们终于走出了一片沙漠。", "error_description": "“沙漠”前的量词漏掉了。“一”后面要接量词，“沙漠”的量词应是“片”，应写作“一片沙漠”，不能直接说“一沙漠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
