INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指地球大气层以外的宇宙空间，非常广阔，几乎没有空气，物体处于失重状态。", "primary_collocate": null, "pronunciation": "tài kōng", "ipa": "tʰai˥˩ kʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "今天，在屋顶、沙漠甚至太空中，都能看到太阳能电池板。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "宇航员坐着火箭飞向太空。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空中没有空气，人必须穿特别的衣服。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国已经把很多卫星送到了太空。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在太空里，东西不会往下掉。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想成为去太空工作的人。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从太空看地球，它像一个蓝色的球。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇航员在太空里住了半年。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空非常广阔，我们还有很多不知道的事。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个望远镜能拍到太空中很远的星星。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "太空人", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球大气层以外广阔的宇宙空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87c5817-34a3-497b-90f4-3778d20342d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13648, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "太空", "is_correct": true, "explanation": "“太空”指地球大气层以外的宇宙空间，与听到的读音相符。"}, {"text": "天空", "is_correct": false, "explanation": "tiān（第一声）与 tài（第四声）韵母不同，意思是天空，指地面上方的天，不是宇宙空间。"}, {"text": "卖空", "is_correct": false, "explanation": "mài（第四声）与 tài 声母不同，意思是卖空，是一种金融操作，不指宇宙空间。"}, {"text": "太公", "is_correct": false, "explanation": "gōng 与 kōng 声母不同，意思是祖父或对老人的敬称，不指宇宙空间。"}], "explanations": {"太空": "“太空”指地球大气层以外的宇宙空间，与听到的读音相符。", "天空": "tiān（第一声）与 tài（第四声）韵母不同，意思是天空，指地面上方的天，不是宇宙空间。", "卖空": "mài（第四声）与 tài 声母不同，意思是卖空，是一种金融操作，不指宇宙空间。", "太公": "gōng 与 kōng 声母不同，意思是祖父或对老人的敬称，不指宇宙空间。"}, "sentence_index": null, "correct_answer": "太空"}, "level_3": {"options": [{"text": "太空", "is_correct": true, "explanation": "“太空”指地球大气层以外的宇宙空间，与“屋顶”“沙漠”并列，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是室内家电，与“屋顶”的高处和“太空”的范围并列不合理，也不能看到电池板。"}, {"text": "地下室", "is_correct": false, "explanation": "语义：地下室在地面以下，与“屋顶”的高处并列矛盾，句意不通。"}, {"text": "幽冥", "is_correct": false, "explanation": "语域：“幽冥”是文言用语，指阴间，与现代说明文式的叙述不协调。"}], "explanations": {"太空": "“太空”指地球大气层以外的宇宙空间，与“屋顶”“沙漠”并列，符合句意。", "冰箱": "语义：冰箱是室内家电，与“屋顶”的高处和“太空”的范围并列不合理，也不能看到电池板。", "地下室": "语义：地下室在地面以下，与“屋顶”的高处并列矛盾，句意不通。", "幽冥": "语域：“幽冥”是文言用语，指阴间，与现代说明文式的叙述不协调。"}, "sentence_index": 0, "correct_answer": "太空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨停以后，太空上的草长得特别绿。", "explanation": "这里应该用〈地面〉。草长在地面上，要靠土壤、水和空气；太空没有这些，这里的“太空”用法不对。"}, {"text": "太空下起了小雨，街上的人都撑起了伞。", "explanation": "这里应该用〈天空〉。雨从天空落下，太空没有空气，不会下雨，这里的“太空”用法不对。"}, {"text": "小鸟在太空里飞来飞去，叫个不停。", "explanation": "这里应该用〈空中〉。鸟在空中飞，太空没有空气，鸟无法在那里飞，这里的“太空”用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太空", "is_correct": true, "explanation": "“太空”指地球外的宇宙空间，从那里才能看到整个地球的形状，符合句意。"}, {"text": "海底", "is_correct": false, "explanation": "语义：从海底看不到地球的整体形状，与“从……看地球”的视角矛盾。"}, {"text": "矿井", "is_correct": false, "explanation": "语义：矿井在地下狭窄处，视野受限，无法看到地球像一个球的样子。"}, {"text": "冥界", "is_correct": false, "explanation": "语域：“冥界”是神话或宗教用语，与这句科普式的描述不协调。"}], "explanations": {"太空": "“太空”指地球外的宇宙空间，从那里才能看到整个地球的形状，符合句意。", "海底": "语义：从海底看不到地球的整体形状，与“从……看地球”的视角矛盾。", "矿井": "语义：矿井在地下狭窄处，视野受限，无法看到地球像一个球的样子。", "冥界": "语域：“冥界”是神话或宗教用语，与这句科普式的描述不协调。"}, "sentence_index": 6, "correct_answer": "太空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，就跑去吃太空。", "explanation": "“吃”的对象应是食物，太空是宇宙空间，不能吃，这里的“太空”用法不对。"}, {"text": "我们每天乘坐太空去上学。", "explanation": "“乘坐”的对象应是交通工具，太空不是交通工具，这里的“太空”用法不对。"}, {"text": "妈妈给我穿上一件太空，说天冷了。", "explanation": "“穿”的对象应是衣物，太空不能穿，这里的“太空”用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我抬头看到了一只太空。", "corrected_sentence": "我抬头看到了一片太空。", "error_description": "“太空”的量词应该用“片”，写成“只”是错误的。“只”多用于动物，指一片广阔的空间要用“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火箭终于飞了进太空。", "corrected_sentence": "火箭终于飞进了太空。", "error_description": "补语“进”和“了”的位置错了。应写作“飞进了太空”，“进”紧跟在动词“飞”后面，“了”放在补语后；“飞了进太空”的语序是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13649, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13649, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13649, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乡村指以农业为主要经济活动、人口分布较分散、自然景观为主的居住区域，与城市相对。", "primary_collocate": null, "pronunciation": "xiāng cūn", "ipa": "ɕjaŋ⁵⁵ tsʰwən⁵⁵", "syllable_count": 2, "sentences": [{"text": "它们把阳光变成电，为城市和乡村供电。", "target_word": "乡村", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "爷爷住在乡村，我们周末去看他。", "target_word": "乡村", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乡村的空气比城市好。", "target_word": "乡村", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢乡村安静的生活。", "target_word": "乡村", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "乡村小路两边都是田地。", "target_word": "乡村", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从乡村来到城市上学。", "target_word": "乡村", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个乡村有一百多户人家。", "target_word": "乡村", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天我们去乡村玩，吃了新鲜的菜。", "target_word": "乡村", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乡村的孩子常常在河边玩。", "target_word": "乡村", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想在乡村开一家小书店。", "target_word": "乡村", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "乡村音乐", "label": "复合"}, {"form": "鄉村", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以农业为主、人口分散、与城市相对的居住区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f88850e-622b-426b-b7db-fbf12d98ab7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13649, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳是把阳光变成电的能量来源，不是接受供电的地方，与“为……供电”不符。"}, {"text": "乡村", "is_correct": true, "explanation": "正确：“乡村”是需要供电的地方，与“城市”并列，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“供电”的对象应是用电的场所或设施，“空气”不能与“供电”搭配。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不用电，与“为城市和……供电”的语境无关。"}], "explanations": {"太阳": "语义：太阳是把阳光变成电的能量来源，不是接受供电的地方，与“为……供电”不符。", "乡村": "正确：“乡村”是需要供电的地方，与“城市”并列，符合句意。", "空气": "搭配：“供电”的对象应是用电的场所或设施，“空气”不能与“供电”搭配。", "课本": "语义：课本不用电，与“为城市和……供电”的语境无关。"}, "sentence_index": 0, "correct_answer": "乡村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个乡村的证券交易所每天都很热闹。", "explanation": "这里应该用〈城市〉。证券交易所设在城市的金融中心，乡村不设这类机构。"}, {"text": "这个乡村是国家的首都。", "explanation": "这里应该用〈首都〉。乡村指以农田和自然景观为主的地方，国家的政治中心要用〈首都〉。"}, {"text": "这个乡村的地铁站每天都很挤。", "explanation": "这里应该用〈城市〉。地铁和拥挤的车站是城市的特点，乡村以农田和自然景观为主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13649, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机不住人，不能说“有一百多户人家”。"}, {"text": "乡村", "is_correct": true, "explanation": "正确：“乡村”是有人居住的地方，可以说“有一百多户人家”，符合句意。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是供人游览的地方，不住人家，与“有一百多户人家”冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“汽车”不是居住区，不能与“有一百多户人家”搭配。"}], "explanations": {"手机": "语义：手机不住人，不能说“有一百多户人家”。", "乡村": "正确：“乡村”是有人居住的地方，可以说“有一百多户人家”，符合句意。", "公园": "语义：公园是供人游览的地方，不住人家，与“有一百多户人家”冲突。", "汽车": "搭配：“汽车”不是居住区，不能与“有一百多户人家”搭配。"}, "sentence_index": 6, "correct_answer": "乡村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乡村都来参加会议。", "explanation": "这里应该用〈村民〉。“乡村”指地方，不能来参加会议，指人要用〈村民〉。"}, {"text": "乡村都在田里干活。", "explanation": "这里应该用〈农民〉。“乡村”是地方，不能下田干活，指人要用〈农民〉。"}, {"text": "乡村都在课堂上做作业。", "explanation": "这里应该用〈学生〉。“乡村”是地方，不能在课堂上做作业，指学生要用〈学生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只乡村每年都有很多游客。", "corrected_sentence": "那个乡村每年都有很多游客。", "error_description": "量词错误：“乡村”的量词是“个”，“只”用于动物，应改为“那个乡村”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们乡村住了三年。", "corrected_sentence": "他们在乡村住了三年。", "error_description": "介词缺失：表示地点的“乡村”前要加介词“在”，“乡村住”不成立，应说“在乡村住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
