INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13650, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提供电力，通常指从电源向用电设备输送电能。", "primary_collocate": null, "pronunciation": "gōng diàn", "ipa": "kʊŋ⁵⁵ tjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "它们把阳光变成电，为城市和乡村供电。", "target_word": "供电", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这座电站给整个小镇供电。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暴雨以后，城里一些地方停止供电。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的电站已经开始供电了。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天用电量大，电站要保证供电。", "target_word": "供电", "complexity_tier": "T3", "furigana": "xià tiān yòng diàn liàng dà, diàn zhàn yào bǎo zhèng gōng diàn。", "sentence_source": "generated"}, {"text": "工人正在修线路，今天下午不供电。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电站为十万户人家供电。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山区的小村子也用太阳能供电。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的备用发电机会马上开始供电。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条线路专门给学校供电。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "供电了", "label": "体标"}, {"form": "供电系统", "label": "复合"}, {"form": "供电局", "label": "复合"}, {"form": "供電", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从电源向用电的地方或设备输送电力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f88850e-622b-426b-b7db-fbf12d98ab7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "供电", "is_correct": true, "explanation": "正确答案。听到的是“供电”（gōng diàn），指电站或电力部门向用户输送电力。"}, {"text": "充电", "is_correct": false, "explanation": "充电（chōng diàn）与 gōng 声母不同（ch 与 g），意思是给电池或设备补充电能。"}, {"text": "通电", "is_correct": false, "explanation": "通电（tōng diàn）与 gōng 声母不同（t 与 g），意思是电流接通、有了电。"}, {"text": "共电", "is_correct": false, "explanation": "共电（gòng diàn）与 gōng 声调不同（第四声与第一声），是电话术语，指由局端统一供电的方式。"}], "explanations": {"供电": "正确答案。听到的是“供电”（gōng diàn），指电站或电力部门向用户输送电力。", "充电": "充电（chōng diàn）与 gōng 声母不同（ch 与 g），意思是给电池或设备补充电能。", "通电": "通电（tōng diàn）与 gōng 声母不同（t 与 g），意思是电流接通、有了电。", "共电": "共电（gòng diàn）与 gōng 声调不同（第四声与第一声），是电话术语，指由局端统一供电的方式。"}, "sentence_index": null, "correct_answer": "供电"}, "level_3": {"options": [{"text": "供电", "is_correct": true, "explanation": "正确答案。“为城市和乡村”引出受益对象，电站把电送给它们只能用“供电”。"}, {"text": "供水", "is_correct": false, "explanation": "搭配：前文说“把阳光变成电”，“供水”的对象是水，与句中的电不符。"}, {"text": "耗电", "is_correct": false, "explanation": "语义：“耗电”是消耗电能，意思与“给……送电”相反，不能说为城市耗电。"}, {"text": "输油", "is_correct": false, "explanation": "语义：“输油”输送的是石油，与句中的电不符，也不能表示供给电力。"}], "explanations": {"供电": "正确答案。“为城市和乡村”引出受益对象，电站把电送给它们只能用“供电”。", "供水": "搭配：前文说“把阳光变成电”，“供水”的对象是水，与句中的电不符。", "耗电": "语义：“耗电”是消耗电能，意思与“给……送电”相反，不能说为城市耗电。", "输油": "语义：“输油”输送的是石油，与句中的电不符，也不能表示供给电力。"}, "sentence_index": 0, "correct_answer": "供电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每天都供电，电费也很高。", "explanation": "这里应该用〈用电〉。供电是供应方向用户送电，工厂付高额电费是用电的一方，不能说工厂供电。"}, {"text": "我的手机快没电了，我得去供电。", "explanation": "这里应该用〈充电〉。给手机或电池补充电能用“充电”，“供电”指电站或电网向用户供应电力。"}, {"text": "孩子们应该少供电，出门要随手关灯。", "explanation": "这里应该用〈节电〉。节电是减少用电，孩子们是用电的一方；供电是供应方的工作，不能用来节约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "供电", "is_correct": true, "explanation": "正确答案。“为十万户人家”引出服务对象，电站向用户输送电力正是“供电”。"}, {"text": "送水", "is_correct": false, "explanation": "语义：电站送的是电，不是水，句子的主语与所送之物对不上。"}, {"text": "停水", "is_correct": false, "explanation": "语义：“停水”是中断供水，与“为十万户人家”服务的意思相反。"}, {"text": "下雨", "is_correct": false, "explanation": "配价：“下雨”是不及物动词，不能带“为十万户人家”这样的受益对象。"}], "explanations": {"供电": "正确答案。“为十万户人家”引出服务对象，电站向用户输送电力正是“供电”。", "送水": "语义：电站送的是电，不是水，句子的主语与所送之物对不上。", "停水": "语义：“停水”是中断供水，与“为十万户人家”服务的意思相反。", "下雨": "配价：“下雨”是不及物动词，不能带“为十万户人家”这样的受益对象。"}, "sentence_index": 6, "correct_answer": "供电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每周给报社供电一篇稿。", "explanation": "这里应该用〈供稿〉。“供稿”是向报社提供文章，“供电”的对象是电力，不能用于文章。"}, {"text": "学校食堂每天给学生供电午饭。", "explanation": "这里应该用〈供应〉。供电的对象是电力，不能用于饭菜；“供应”可以带食物或物资。"}, {"text": "这条管道每天把燃气供电到千家万户。", "explanation": "这里应该用〈输送〉。“供电”只用于电力，燃气是气体，不能说供电燃气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座电站每天都工厂供电。", "corrected_sentence": "这座电站每天都给工厂供电。", "error_description": "“供电”前漏了引出受益对象的“给”，应说“给工厂供电”，不能说“工厂供电”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天凌晨三点开始供电了。", "corrected_sentence": "明天凌晨三点开始供电。", "error_description": "“明天凌晨三点”是将来的时间，将来的动作不能加“了”，应去掉“了”，说“明天凌晨三点开始供电”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
