INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13652, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电站是发电的场所，通过不同方式把能量变成电。", "primary_collocate": null, "pronunciation": "diàn zhàn", "ipa": "tjɛn⁵¹ ʈʂan⁵¹", "syllable_count": 2, "sentences": [{"text": "从风车到风力发电机，从最早的实验到现代的太阳能电站，清洁能源的发展有很长的历史。", "target_word": "电站", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座电站建在大河边，用水发电。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电站里的工人每天检查发电机。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上新建了一座靠太阳发电的电站。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电站一年能发很多电。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电站发出的电送到了附近的城市。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们正在修理电站的发电机。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为河水很多，所以这里适合建电站。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在电站工作了十年，负责管理发电机。", "target_word": "电站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电站出了问题，城里很多地方没有电。", "target_word": "电站", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "水电站", "label": "复合"}, {"form": "核电站", "label": "复合"}, {"form": "電站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "发电的场所，把水、风、太阳等能量变成电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f88850e-622b-426b-b7db-fbf12d98ab7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水库", "is_correct": false, "explanation": "语义：“水库”是蓄水的地方，与“太阳能”“清洁能源”发电的语境不符。"}, {"text": "电站", "is_correct": true, "explanation": "正确：“电站”是发电的场所，与“太阳能”“清洁能源”的语境相符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：“图书馆”供人借阅书籍，与“清洁能源的发展”的语境无关。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“太阳能”修饰能源设施，不能修饰食品，“面包”与之不搭配。"}], "explanations": {"水库": "语义：“水库”是蓄水的地方，与“太阳能”“清洁能源”发电的语境不符。", "电站": "正确：“电站”是发电的场所，与“太阳能”“清洁能源”的语境相符。", "图书馆": "语义：“图书馆”供人借阅书籍，与“清洁能源的发展”的语境无关。", "面包": "搭配：“太阳能”修饰能源设施，不能修饰食品，“面包”与之不搭配。"}, "sentence_index": 0, "correct_answer": "电站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座电站每天生产很多零件。", "explanation": "这里应该用〈工厂〉。电站用来发电，生产零件要用〈工厂〉。"}, {"text": "这个电站每天有很多人上下车。", "explanation": "这里应该用〈车站〉。电站是发电的地方，供人上下车要用〈车站〉。"}, {"text": "这家电站每天有很多病人。", "explanation": "这里应该用〈医院〉。电站是发电设施，接待病人要用〈医院〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不会发电，“修理……的发电机”的所属不能是蛋糕。"}, {"text": "电站", "is_correct": true, "explanation": "正确：电站里有发电机，句中修理的是电站的发电机，符合句意。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“衣服”没有发电机，“……的发电机”不能与“衣服”搭配。"}, {"text": "手表", "is_correct": false, "explanation": "语义：手表不会有发电机，与句中“修理发电机”的语境冲突。"}], "explanations": {"蛋糕": "语义：蛋糕不会发电，“修理……的发电机”的所属不能是蛋糕。", "电站": "正确：电站里有发电机，句中修理的是电站的发电机，符合句意。", "衣服": "搭配：“衣服”没有发电机，“……的发电机”不能与“衣服”搭配。", "手表": "语义：手表不会有发电机，与句中“修理发电机”的语境冲突。"}, "sentence_index": 6, "correct_answer": "电站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座电站每年挖出很多煤。", "explanation": "这里应该用〈煤矿〉。挖煤要用〈煤矿〉，电站是用来发电的。"}, {"text": "这座电站每天卖很多汽油。", "explanation": "这里应该用〈加油站〉。卖汽油要用〈加油站〉，电站不卖燃油。"}, {"text": "这个电站每天有很多顾客。", "explanation": "这里应该用〈商场〉。接待顾客、卖东西要用〈商场〉，电站不接待顾客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只电站每年发出很多电。", "corrected_sentence": "那座电站每年发出很多电。", "error_description": "量词错误：“电站”的量词是“座”，“只”用于动物，应改为“那座电站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人修好了一电站。", "corrected_sentence": "工人修好了一座电站。", "error_description": "量词缺失：数词“一”后的名词需要量词，应说“一座电站”，不能说“一电站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
