INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种从地下提取的黑色液体，用作燃料和能源", "primary_collocate": null, "pronunciation": "shí yóu", "ipa": "ʂɨ˧˥ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "未来，我们可能会用更多的清洁电力，减少对煤和石油的依赖。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "石油是一种从地下取出来的黑色液体。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家靠卖石油赚钱。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机和汽车都需要石油做燃料。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个海边城市有一家大石油公司。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油用得太多，会让空气变脏。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸在石油公司工作，常常出差。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中东有世界上最多的石油。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天用的暖气，有些也靠石油。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想找石油以外的新能源。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一桶石油", "label": "量词"}, {"form": "石油气", "label": "复合"}], "register": "中性", "sense_fingerprint": "地下提取的黑色液体，用作燃料和能源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffaa23c-0615-48bd-8fdc-16ab6fa2cc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13656, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "石油", "is_correct": true, "explanation": "正确。石油（shí yóu）是目标词，指从地下提取的黑色液体。"}, {"text": "时有", "is_correct": false, "explanation": "shí yǒu（第三声）与 shí yóu（第二声）声调不同，意思是“有时”。"}, {"text": "事由", "is_correct": false, "explanation": "shì yóu（第四声）与 shí yóu（第二声）第一音节声调不同，意思是“事情的缘由”。"}, {"text": "试油", "is_correct": false, "explanation": "shì yóu（第四声）与 shí yóu（第二声）第一音节声调不同，意思是“试油”，即油田测试。"}], "explanations": {"石油": "正确。石油（shí yóu）是目标词，指从地下提取的黑色液体。", "时有": "shí yǒu（第三声）与 shí yóu（第二声）声调不同，意思是“有时”。", "事由": "shì yóu（第四声）与 shí yóu（第二声）第一音节声调不同，意思是“事情的缘由”。", "试油": "shì yóu（第四声）与 shí yóu（第二声）第一音节声调不同，意思是“试油”，即油田测试。"}, "sentence_index": null, "correct_answer": "石油"}, "level_3": {"options": [{"text": "石油", "is_correct": true, "explanation": "正确。“减少对煤和石油的依赖”符合句意，煤和石油都是化石能源。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“依赖”多指能源、资源，“友谊”不属此类，不说“对友谊的依赖”来与煤并列。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是可依赖的能源，与“煤”并列不合句意。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是人，不能与“煤”并列作为能源依赖对象，句意不合。"}], "explanations": {"石油": "正确。“减少对煤和石油的依赖”符合句意，煤和石油都是化石能源。", "友谊": "搭配：“依赖”多指能源、资源，“友谊”不属此类，不说“对友谊的依赖”来与煤并列。", "大海": "语义：大海不是可依赖的能源，与“煤”并列不合句意。", "老师": "语义：“老师”是人，不能与“煤”并列作为能源依赖对象，句意不合。"}, "sentence_index": 0, "correct_answer": "石油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天用石油刷牙。", "explanation": "这里应该用〈牙膏〉。“我每天用牙膏刷牙”是自然的说法；刷牙要用牙膏，石油不能用来刷牙。"}, {"text": "植物需要石油生长。", "explanation": "这里应该用〈水〉。“植物需要水生长”是自然的说法；植物生长需要水，石油不能提供这种条件。"}, {"text": "我买了一个石油。", "explanation": "这里应该用〈桶〉。“一桶石油”是自然的说法；石油以桶或吨计，不能用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石油", "is_correct": true, "explanation": "正确。“他爸爸在石油公司工作”是自然的说法，石油公司是常见的企业类型。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“公司”前接具体行业或企业名称，不接抽象概念“时间”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”不是公司所属的行业，句意不合。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”是疾病，不能作为公司所属的行业，句意不合。"}], "explanations": {"石油": "正确。“他爸爸在石油公司工作”是自然的说法，石油公司是常见的企业类型。", "时间": "搭配：“公司”前接具体行业或企业名称，不接抽象概念“时间”。", "河流": "语义：“河流”不是公司所属的行业，句意不合。", "感冒": "搭配：“感冒”是疾病，不能作为公司所属的行业，句意不合。"}, "sentence_index": 6, "correct_answer": "石油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我喝了一杯石油。", "explanation": "这里应该用〈果汁〉。“我喝了一杯果汁”是自然的说法；石油不能饮用。"}, {"text": "工厂用石油造船。", "explanation": "这里应该用〈钢铁〉。“工厂用钢铁造船”是自然的说法；造船要用钢铁，石油不能用来造船。"}, {"text": "他用石油给手机充电。", "explanation": "这里应该用〈充电器〉。“他用充电器给手机充电”是自然的说法；给手机充电要用充电器接电，石油不能直接给手机充电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这艘船运走了一个石油。", "corrected_sentence": "这艘船运走了一船石油。", "error_description": "错误形式是量词“一个”，正确形式是“一船”。运输大批石油时应说“一船石油”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电厂烧了很石油。", "corrected_sentence": "电厂烧了很多石油。", "error_description": "错误形式是“很”后缺少“多”，“很石油”不成词。石油是不可数的液体，表示数量多要说“很多石油”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
