INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13661, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "比喻事物发展迅速，进步很大。", "primary_collocate": null, "pronunciation": "fēi yuè", "ipa": "fei˥ yɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这座城市近十年飞跃发展，变化很大。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了一年汉语，水平有了飞跃。", "target_word": "飞跃", "complexity_tier": "T3", "furigana": "Tā xué le yì nián Hànyǔ, shuǐpíng yǒu le fēiyuè.", "sentence_source": "generated"}, {"text": "科技飞跃发展，我们的生活越来越方便。", "target_word": "飞跃", "complexity_tier": "T3", "furigana": "Kējì fēiyuè fāzhǎn, wǒmen de shēnghuó yuèlái yuè fāngbiàn.", "sentence_source": "generated"}, {"text": "公司这几年飞跃发展，已经是大企业了。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的成绩在一个学期里有了飞跃。", "target_word": "飞跃", "complexity_tier": "T3", "furigana": "Tā de chéngjì zài yí ge xuéqī lǐ yǒu le fēiyuè.", "sentence_source": "generated"}, {"text": "经过改革，当地的经济飞跃发展起来。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机技术飞跃发展，大家都用上了智能手机。", "target_word": "飞跃", "complexity_tier": "T3", "furigana": "Shǒujī jìshù fēiyuè fāzhǎn, dàjiā dōu yòng shàng le zhìnéng shǒujī.", "sentence_source": "generated"}, {"text": "这个小镇的教育飞跃发展，孩子们都能上好学校。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了三个月，书法有了飞跃。", "target_word": "飞跃", "complexity_tier": "T3", "furigana": "Tā liàn le sān ge yuè, shūfǎ yǒu le fēiyuè.", "sentence_source": "generated"}, {"text": "中国的高铁飞跃发展，出门坐车很快。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞跃了", "label": "体标"}, {"form": "飛躍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比喻义：事物发展迅速、进步很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6965bde7-6897-4797-b880-940007ee84e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞跃", "is_correct": true, "explanation": "飞跃比喻事物发展迅速、进步很大，与“近十年”和“变化很大”相符。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：停滞指不再前进，与“变化很大”的语境矛盾。"}, {"text": "倒退", "is_correct": false, "explanation": "语义：倒退指向后退步，与“变化很大”的发展说法冲突。"}, {"text": "萎缩", "is_correct": false, "explanation": "搭配：萎缩多指规模、市场缩小，不说“萎缩发展”。"}], "explanations": {"飞跃": "飞跃比喻事物发展迅速、进步很大，与“近十年”和“变化很大”相符。", "停滞": "语义：停滞指不再前进，与“变化很大”的语境矛盾。", "倒退": "语义：倒退指向后退步，与“变化很大”的发展说法冲突。", "萎缩": "搭配：萎缩多指规模、市场缩小，不说“萎缩发展”。"}, "sentence_index": 0, "correct_answer": "飞跃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今年的身高飞跃了五厘米。", "explanation": "这里应该用〈增长〉。飞跃用于发展、水平等质的进步，身高这类数量的增长要用〈增长〉。"}, {"text": "小鸟从树枝飞跃到另一棵树上。", "explanation": "这里用的是本义，指小鸟跳过去，不是比喻义的事物迅速发展、进步很大。"}, {"text": "这个月我的体重飞跃了三公斤。", "explanation": "这里应该用〈增加〉。飞跃用于发展、水平，体重这类数量的变化要用〈增加〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞跃", "is_correct": true, "explanation": "飞跃比喻技术迅速发展，与“大家都用上了智能手机”的结果相符。"}, {"text": "退化", "is_correct": false, "explanation": "语义：退化指变差、衰退，与“大家都用上了智能手机”的进步结果矛盾。"}, {"text": "停顿", "is_correct": false, "explanation": "语义：停顿指暂时停止，与“飞跃发展”所表示的快速进步相反，句意矛盾。"}, {"text": "徘徊", "is_correct": false, "explanation": "搭配：徘徊指原地来回走动，不说“徘徊发展”。"}], "explanations": {"飞跃": "飞跃比喻技术迅速发展，与“大家都用上了智能手机”的结果相符。", "退化": "语义：退化指变差、衰退，与“大家都用上了智能手机”的进步结果矛盾。", "停顿": "语义：停顿指暂时停止，与“飞跃发展”所表示的快速进步相反，句意矛盾。", "徘徊": "搭配：徘徊指原地来回走动，不说“徘徊发展”。"}, "sentence_index": 6, "correct_answer": "飞跃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座公园的面积飞跃了一倍。", "explanation": "这里应该用〈扩大〉。飞跃用于发展、进步，面积这类范围的变化要用〈扩大〉。"}, {"text": "这个月的电费飞跃了三成。", "explanation": "这里应该用〈上涨〉。飞跃用于发展、进步，费用和价格的上升要用〈上涨〉。"}, {"text": "图书馆的藏书飞跃了三万册。", "explanation": "这里应该用〈增多〉。飞跃用于发展、进步，藏书这类数量的增加要用〈增多〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年，我们公司被飞跃发展，业务越来越多。", "corrected_sentence": "这几年，我们公司飞跃发展，业务越来越多。", "error_description": "错误在“被”。飞跃是不及物动词，不能用“被”构成被动句。正确说法是“公司飞跃发展”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，中国的高铁把飞跃发展，出门坐车快多了。", "corrected_sentence": "这些年，中国的高铁飞跃发展，出门坐车快多了。", "error_description": "错误在“把”。飞跃是不及物动词，不能带“把”字的处置宾语。应去掉“把”，说“高铁飞跃发展”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
