INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "环境压力指自然环境或社会环境中对生物或人类造成负担、影响生存或发展的各种因素。", "primary_collocate": null, "pronunciation": "huán jìng yā lì", "ipa": "xwan˧˥ tɕiŋ˥˩ ja˥ li˥˩", "syllable_count": 4, "sentences": [{"text": "这一历程并非线性前进，而是在资源危机、环境压力与科学突破的交织推动下，不断重构能源获取的范式。", "target_word": "环境压力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "城市里的环境压力越来越大。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鱼受不了水温变化带来的环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境压力让很多小动物慢慢减少了。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出的脏水给河里的鱼带来很大的环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对环境压力，植物会长出更深的根。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用新办法，减轻了庄稼面临的环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气候变暖是动物面临的环境压力之一。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口增加会加重人类面临的环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林帮我们减轻环境压力。", "target_word": "环境压力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境壓力", "label": "繁体"}], "register": "书面", "sense_fingerprint": "自然或社会环境中影响生存发展的负担因素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6965bde7-6897-4797-b880-940007ee84e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境压力", "is_correct": true, "explanation": "环境压力指自然或社会环境对生物造成的负担，与资源危机、科学突破的宏观语境相符。"}, {"text": "心理压力", "is_correct": false, "explanation": "语义：心理压力指个人的精神负担，与资源危机、科学突破的宏观语境不符。"}, {"text": "环境压迫", "is_correct": false, "explanation": "搭配：压迫多指人对人的强制，不说“环境压迫”。"}, {"text": "人际关系", "is_correct": false, "explanation": "语义：人际关系不是推动能源变革的力量，与“交织推动”的语境不符。"}], "explanations": {"环境压力": "环境压力指自然或社会环境对生物造成的负担，与资源危机、科学突破的宏观语境相符。", "心理压力": "语义：心理压力指个人的精神负担，与资源危机、科学突破的宏观语境不符。", "环境压迫": "搭配：压迫多指人对人的强制，不说“环境压迫”。", "人际关系": "语义：人际关系不是推动能源变革的力量，与“交织推动”的语境不符。"}, "sentence_index": 0, "correct_answer": "环境压力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头对地面的环境压力有一百公斤。", "explanation": "这里应该用〈重量〉。环境压力指环境对生物或人类造成的负担，不能用来说石头对地面的重量。"}, {"text": "小鸟在森林里唱歌，环境压力让它们很开心。", "explanation": "这里应该用〈环境舒适〉。环境压力指对生物造成负担、影响生存的因素，不会让小鸟开心。"}, {"text": "树上的苹果很甜，环境压力让它们长得很大。", "explanation": "这里应该用〈养分〉。环境压力指造成负担的因素，不能促进苹果生长；促进生长的是〈养分〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境压力", "is_correct": true, "explanation": "环境压力指环境对庄稼造成的负担，与“减轻了庄稼面临的”这一搭配相符。"}, {"text": "生活成本", "is_correct": false, "explanation": "语义：生活成本指日常开销，不能说“庄稼面临的生活成本”，句子语义不通。"}, {"text": "个人情绪", "is_correct": false, "explanation": "语义：个人情绪是心理状态，不是庄稼面临的环境负担，句子语义不通。"}, {"text": "利润", "is_correct": false, "explanation": "搭配：利润是经营的结果，不说“庄稼面临的利润”。"}], "explanations": {"环境压力": "环境压力指环境对庄稼造成的负担，与“减轻了庄稼面临的”这一搭配相符。", "生活成本": "语义：生活成本指日常开销，不能说“庄稼面临的生活成本”，句子语义不通。", "个人情绪": "语义：个人情绪是心理状态，不是庄稼面临的环境负担，句子语义不通。", "利润": "搭配：利润是经营的结果，不说“庄稼面临的利润”。"}, "sentence_index": 6, "correct_answer": "环境压力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的环境压力很有名，很多人都来吃饭。", "explanation": "这里应该用〈名气〉。环境压力指造成负担的因素，不能用“有名”来形容餐厅；餐厅有名要用〈名气〉。"}, {"text": "湖水清澈见底，环境压力让鱼儿游得很欢快。", "explanation": "这里应该用〈环境优美〉。环境压力指造成负担、影响生存的因素，不会让鱼儿欢快。"}, {"text": "这首歌的环境压力很动听，大家都喜欢听。", "explanation": "这里应该用〈旋律〉。环境压力指造成负担的因素，不能用来形容歌曲动听；说歌曲动听要用〈旋律〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城市里有一座环境压力，让动物们不安。", "corrected_sentence": "城市里有一种环境压力，让动物们不安。", "error_description": "量词错误。“环境压力”不用量词“座”，应说“一种环境压力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农田里有一条环境压力，影响着庄稼。", "corrected_sentence": "农田里有一种环境压力，影响着庄稼。", "error_description": "量词错误。“环境压力”不用量词“条”，应说“一种环境压力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
