INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指不同的东西互相穿插、结合在一起。", "primary_collocate": null, "pronunciation": "jiāo zhī", "ipa": "tɕjɑʊ˥˥ ʈʂʅ˥˥", "syllable_count": 2, "sentences": [{"text": "这一历程并非线性前进，而是在资源危机、环境压力与科学突破的交织推动下，不断重构能源获取的范式。", "target_word": "交织", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "归根结底，蜜蜂的命运与人类的粮食安全紧密交织。", "target_word": "交织", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "她的脸上交织着高兴和紧张。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里，高楼和老街交织在一起。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河流在平原上交织成一张大网。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话声和说话声交织在一起。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的雨声和风声交织着。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里，历史和故事交织在一起。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首音乐里，欢乐和悲伤交织。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田野里，小路和小河交织着。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交织着", "label": "体标"}, {"form": "交织了", "label": "体标"}, {"form": "交织过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不同的事物互相穿插、结合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f59174-23ab-4b8b-9546-74dc82c078e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：交织 jiāo zhī，意思是不同的事物互相穿插、结合在一起。"}, {"text": "脚趾", "is_correct": false, "explanation": "脚趾 jiǎozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是脚趾。"}, {"text": "角质", "is_correct": false, "explanation": "角质 jiǎozhì（第三声、第四声）与 jiāo zhī（第一声、第一声）声调不同，意思是角质层。"}, {"text": "校址", "is_correct": false, "explanation": "校址 jiàozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是学校的地址。"}, {"text": "姜汁", "is_correct": false, "explanation": "姜汁 jiāngzhī 的韵母（-ang）与 jiāo 的韵母（-ao）不同，意思是姜的汁液。"}], "explanations": {"交织": "正确：交织 jiāo zhī，意思是不同的事物互相穿插、结合在一起。", "脚趾": "脚趾 jiǎozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是脚趾。", "角质": "角质 jiǎozhì（第三声、第四声）与 jiāo zhī（第一声、第一声）声调不同，意思是角质层。", "校址": "校址 jiàozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是学校的地址。", "姜汁": "姜汁 jiāngzhī 的韵母（-ang）与 jiāo 的韵母（-ao）不同，意思是姜的汁液。"}, "sentence_index": null, "correct_answer": "交织"}, "level_3": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：“交织”指多股力量互相穿插、共同作用，与“资源危机、环境压力与科学突破”并列作用的语境相符。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：“雪花”不是推动历程的力量，不能用于此处。"}, {"text": "沉默", "is_correct": false, "explanation": "搭配：“推动”的动力应是力量或事件，“沉默”不能推动历程。"}, {"text": "闲聊", "is_correct": false, "explanation": "语域：“闲聊”是口语化的日常交谈，与这段书面、学术的论述语体不符。"}], "explanations": {"交织": "正确：“交织”指多股力量互相穿插、共同作用，与“资源危机、环境压力与科学突破”并列作用的语境相符。", "雪花": "语义：“雪花”不是推动历程的力量，不能用于此处。", "沉默": "搭配：“推动”的动力应是力量或事件，“沉默”不能推动历程。", "闲聊": "语域：“闲聊”是口语化的日常交谈，与这段书面、学术的论述语体不符。"}, "sentence_index": 0, "correct_answer": "交织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把作业交织给老师。", "explanation": "这里应该用〈交给〉。交织指事物互相穿插、结合；把东西转给别人要用交给。"}, {"text": "汤里交织着几粒沙子。", "explanation": "这里应该用〈夹杂〉。交织强调几股事物相互穿插、结合，外来的杂物混在汤里要用夹杂。"}, {"text": "几位同学交织着值日。", "explanation": "这里应该用〈轮换〉。交织不表示轮流承担，轮流值日要用轮换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：交织 jiāo zhī，意思是不同的事物互相穿插、结合在一起。"}, {"text": "娇妻", "is_correct": false, "explanation": "娇妻 jiāoqī 的第二音节声母 q 与 zh 不同，意思是受宠爱的妻子。"}, {"text": "胶质", "is_correct": false, "explanation": "胶质 jiāozhì 的第二音节声调为第四声，与 zhī 不同，意思是胶状物质。"}, {"text": "教职", "is_correct": false, "explanation": "教职 jiàozhí 的两个音节声调都与 jiāo zhī 不同，意思是教学工作的职务。"}, {"text": "胶纸", "is_correct": false, "explanation": "胶纸 jiāozhǐ 的第二音节声调为第三声，与 zhī 不同，意思是带胶的纸。"}], "explanations": {"交织": "正确：交织 jiāo zhī，意思是不同的事物互相穿插、结合在一起。", "娇妻": "娇妻 jiāoqī 的第二音节声母 q 与 zh 不同，意思是受宠爱的妻子。", "胶质": "胶质 jiāozhì 的第二音节声调为第四声，与 zhī 不同，意思是胶状物质。", "教职": "教职 jiàozhí 的两个音节声调都与 jiāo zhī 不同，意思是教学工作的职务。", "胶纸": "胶纸 jiāozhǐ 的第二音节声调为第三声，与 zhī 不同，意思是带胶的纸。"}, "sentence_index": null, "correct_answer": "交织"}, "level_3": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：“交织着”表示雨声和风声相互穿插、混在一起，与“着”搭配自然。"}, {"text": "聚集", "is_correct": false, "explanation": "搭配：“聚集”多用于人群或物体汇集，声音不说“聚集”。"}, {"text": "静止", "is_correct": false, "explanation": "语义：“静止”与“雨声和风声”的流动、声响相矛盾。"}, {"text": "倒塌", "is_correct": false, "explanation": "搭配：“倒塌”指建筑或物体崩坏，不能用于声音。"}], "explanations": {"交织": "正确：“交织着”表示雨声和风声相互穿插、混在一起，与“着”搭配自然。", "聚集": "搭配：“聚集”多用于人群或物体汇集，声音不说“聚集”。", "静止": "语义：“静止”与“雨声和风声”的流动、声响相矛盾。", "倒塌": "搭配：“倒塌”指建筑或物体崩坏，不能用于声音。"}, "sentence_index": 6, "correct_answer": "交织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "几张照片交织着放在桌上。", "explanation": "这里应该用〈重叠〉。交织指互相穿插、结合；照片叠放在一起是重叠，不是交织。"}, {"text": "两班人在门口交织工作。", "explanation": "这里应该用〈交接〉。交织不表示先后转交；两班人依次转交工作要用交接。"}, {"text": "老师把试卷交织给我们。", "explanation": "这里应该用〈发〉。交织指互相穿插、结合；把试卷分给学生要用发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山路在林子里交织一张网。", "corrected_sentence": "山路在林子里交织成一张网。", "error_description": "错误形式：“交织一张网”。正确形式：“交织成一张网”。“交织”后面要用“成”引出结果，再接宾语“一张网”，不能直接带宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨丝和阳光交织窗前。", "corrected_sentence": "雨丝和阳光交织在窗前。", "error_description": "错误形式：“交织窗前”。正确形式：“交织在窗前”。表示处所时要用“在”引出，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然力指自然界中固有的、非人为的力量或能量，如风力、水力、太阳能等。", "primary_collocate": null, "pronunciation": "zì rán lì", "ipa": "tsɨ˥˩ ʐan˧˥ li˥˩", "syllable_count": 3, "sentences": [{"text": "早期文明对可再生能源的利用，体现为对自然力的直接转化。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "风力和水力都是自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人靠自然力推动水车磨米。", "target_word": "自然力", "complexity_tier": "T3", "furigana": "gǔ rén kào zìrànlì tuīdòng shuǐchē mó mǐ", "sentence_source": "generated"}, {"text": "人们用自然力发电，不用烧煤。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然力有时很大，人很难挡住。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帆船靠自然力在海上前进。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能也是一种自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民很早就懂得利用自然力种地。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大水冲走了桥，这就是自然力的作用。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代工厂尽量利用自然力，以减少污染。", "target_word": "自然力", "complexity_tier": "T3", "furigana": "xiàndài gōngchǎng jǐnliàng lìyòng zìrànlì, yǐ jiǎnshǎo wūrǎn", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "自然界固有的非人为力量或能量，如风力、水力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6965bde7-6897-4797-b880-940007ee84e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然力", "is_correct": true, "explanation": "自然力指自然界固有的非人为力量，与“可再生能源转化”的语境相符，是唯一能填入空格的词。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“转化”的对象须是能量或物质，时间不能被直接转化为能源，句子语义不通。"}, {"text": "文字", "is_correct": false, "explanation": "搭配：“转化”一般搭配能量、物质，“文字”不能被直接转化为能源，搭配不当。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语色彩很重，与这句书面语的说明语气不协调。"}], "explanations": {"自然力": "自然力指自然界固有的非人为力量，与“可再生能源转化”的语境相符，是唯一能填入空格的词。", "时间": "语义：“转化”的对象须是能量或物质，时间不能被直接转化为能源，句子语义不通。", "文字": "搭配：“转化”一般搭配能量、物质，“文字”不能被直接转化为能源，搭配不当。", "玩意儿": "语域：“玩意儿”口语色彩很重，与这句书面语的说明语气不协调。"}, "sentence_index": 0, "correct_answer": "自然力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂排放的废气污染了自然力。", "explanation": "这里应该用〈自然环境〉。“污染”的对象是环境，自然力指力量，不能被污染。"}, {"text": "帆船被一台自然力推着前进。", "explanation": "这里应该用〈股〉。自然力是抽象的力量，量词用“股”；“台”用于机器，不能用来数自然力。"}, {"text": "他跑完马拉松，只剩下一点自然力了。", "explanation": "这里应该用〈体力〉。自然力指自然界的力量，不指人的体力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然力", "is_correct": true, "explanation": "自然力指自然界的力量，太阳能正属于此类，是唯一能填入的词。"}, {"text": "手机", "is_correct": false, "explanation": "语义：太阳能不是手机，“太阳能也是一种手机”语义不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是心理状态，不是自然界的力量，“太阳能也是一种心情”语义不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，不能说太阳能是一种体重，句子语义不通。"}], "explanations": {"自然力": "自然力指自然界的力量，太阳能正属于此类，是唯一能填入的词。", "手机": "语义：太阳能不是手机，“太阳能也是一种手机”语义不通。", "心情": "语义：心情是心理状态，不是自然界的力量，“太阳能也是一种心情”语义不通。", "体重": "语义：“体重”指人或物的重量，不能说太阳能是一种体重，句子语义不通。"}, "sentence_index": 6, "correct_answer": "自然力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现代工厂尽量节约自然力，以减少污染。", "explanation": "这里应该用〈能源〉。“节约”的对象是能源这类可消耗的资源，自然力是力量本身，不能说节约。"}, {"text": "他凭着好自然力跑完了全程马拉松。", "explanation": "这里应该用〈体能〉。跑完马拉松靠的是人的体能；自然力指自然界的力量，不指人的体能。"}, {"text": "他靠自然力考上了大学。", "explanation": "这里应该用〈天赋〉。自然力指自然界的力量，不指人的天赋或才能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台老水车靠一台自然力转动，不用电。", "corrected_sentence": "这台老水车靠一股自然力转动，不用电。", "error_description": "量词错误：“自然力”是抽象的力量，应用量词“股”；“台”用于机器，不能用来数自然力，这里应改为“股”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一台自然力推动着帆船。", "corrected_sentence": "一股自然力推动着帆船。", "error_description": "量词错误：“自然力”是抽象的力量，应说“一股自然力”；“台”用于机器，不能用来数自然力。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
