INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13667, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装置指为特定功能而组装、安装的器械、设备或系统。", "primary_collocate": null, "pronunciation": "zhuāng zhì", "ipa": "ʈʂwaŋ˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "海上风电场的兴起更将发电装置迁移至风力更稳定强劲的大陆架区域。", "target_word": "装置", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂里新装了一套净水装置。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套装置能把太阳能变成电。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有一个很复杂的实验装置。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查报警装置有没有问题。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院为病人准备了一套供氧装置。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥上安装着自动监测装置。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个装置很简单，学生自己就能做。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用一个小装置给我们演示了电的原理。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车有一个安全装置，能保护司机。", "target_word": "装置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "裝置", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为实现某种功能而组装安装的成套设备或系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6965bde7-6897-4797-b880-940007ee84e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13667, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指为某种功能而组装的器械或设备，是所听到的词。"}, {"text": "壮志", "is_correct": false, "explanation": "壮志（zhuàng zhì）与装置（zhuāng zhì）第一音节声调不同，意思是远大的志向。"}, {"text": "专制", "is_correct": false, "explanation": "专制（zhuān zhì）与装置（zhuāng zhì）韵母不同（an/ang），意思是独断统治。"}, {"text": "荒置", "is_correct": false, "explanation": "荒置（huāng zhì）与装置（zhuāng zhì）声母不同（h/zh），意思是闲置不用。"}], "explanations": {"装置": "装置指为某种功能而组装的器械或设备，是所听到的词。", "壮志": "壮志（zhuàng zhì）与装置（zhuāng zhì）第一音节声调不同，意思是远大的志向。", "专制": "专制（zhuān zhì）与装置（zhuāng zhì）韵母不同（an/ang），意思是独断统治。", "荒置": "荒置（huāng zhì）与装置（zhuāng zhì）声母不同（h/zh），意思是闲置不用。"}, "sentence_index": null, "correct_answer": "装置"}, "level_3": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指为特定功能而组装的设备，“发电装置”迁移到大陆架区域，语义通顺，是唯一能填入的词。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是心理状态，不能被“发电”，也不能被迁移到大陆架区域，句子语义不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是发电的设备，“发电书包”迁移至大陆架，语义不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能发电，也不能被迁移到大陆架，句子语义不通。"}], "explanations": {"装置": "装置指为特定功能而组装的设备，“发电装置”迁移到大陆架区域，语义通顺，是唯一能填入的词。", "心情": "语义：心情是心理状态，不能被“发电”，也不能被迁移到大陆架区域，句子语义不通。", "书包": "语义：书包不是发电的设备，“发电书包”迁移至大陆架，语义不通。", "歌曲": "语义：歌曲不能发电，也不能被迁移到大陆架，句子语义不通。"}, "sentence_index": 0, "correct_answer": "装置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵们穿着全套装置，准备出发。", "explanation": "这里应该用〈装备〉。装备指人员随身使用的器材，可以穿戴；装置指安装好的设备，不能穿在身上。"}, {"text": "工厂里新装了一张净水装置。", "explanation": "这里应该用〈套〉。装置是成套的设备，量词用“套”，“张”用于平面的东西，不用于装置。"}, {"text": "这位同学会弹一种装置。", "explanation": "这里应该用〈乐器〉。装置指安装好的器械设备，不是可以演奏的乐器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13667, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指为特定功能而组装的器械或设备，是所听到的词。"}, {"text": "专治", "is_correct": false, "explanation": "专治（zhuān zhì）与装置（zhuāng zhì）韵母不同（an/ang），意思是专门医治。"}, {"text": "壮志", "is_correct": false, "explanation": "壮志（zhuàng zhì）与装置（zhuāng zhì）第一音节声调不同，意思是远大的志向。"}, {"text": "章制", "is_correct": false, "explanation": "章制（zhāng zhì）与装置（zhuāng zhì）韵母不同（去掉 u），意思是章程制度。"}], "explanations": {"装置": "装置指为特定功能而组装的器械或设备，是所听到的词。", "专治": "专治（zhuān zhì）与装置（zhuāng zhì）韵母不同（an/ang），意思是专门医治。", "壮志": "壮志（zhuàng zhì）与装置（zhuāng zhì）第一音节声调不同，意思是远大的志向。", "章制": "章制（zhāng zhì）与装置（zhuāng zhì）韵母不同（去掉 u），意思是章程制度。"}, "sentence_index": null, "correct_answer": "装置"}, "level_3": {"options": [{"text": "装置", "is_correct": true, "explanation": "装置指为特定功能而组装的设备，“自动监测装置”安装在桥上，语义通顺，是唯一能填入的词。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是监测设备，“自动监测厨房”语义不通。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“监测”一般搭配设备、数据、信号，“饮料”不能被自动监测，搭配不当。"}, {"text": "书本", "is_correct": false, "explanation": "语义：桥上安装的设备不能去监测书本，“自动监测书本”语义不通。"}], "explanations": {"装置": "装置指为特定功能而组装的设备，“自动监测装置”安装在桥上，语义通顺，是唯一能填入的词。", "厨房": "语义：厨房不是监测设备，“自动监测厨房”语义不通。", "饮料": "搭配：“监测”一般搭配设备、数据、信号，“饮料”不能被自动监测，搭配不当。", "书本": "语义：桥上安装的设备不能去监测书本，“自动监测书本”语义不通。"}, "sentence_index": 6, "correct_answer": "装置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在玩具店挑选了一个新装置。", "explanation": "这里应该用〈玩具〉。装置指器械设备，不是供孩子玩的东西。"}, {"text": "这家餐厅的菜单上有一道新装置。", "explanation": "这里应该用〈菜〉。装置不是食物，不能出现在菜单的菜品中。"}, {"text": "他用装置唱了一首歌。", "explanation": "这里应该用〈嗓子〉。唱歌要用嗓子，装置是器械设备，不能用来唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人仔细检查了一条报警装置。", "corrected_sentence": "工人仔细检查了一套报警装置。", "error_description": "量词错误：装置是成套的设备，应说“一套”；“条”用于细长的东西，不能用于装置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车间里多了一把自动装置。", "corrected_sentence": "车间里多了一套自动装置。", "error_description": "量词错误：装置是成套的设备，应说“一套”；“把”用于有柄的器具，不能用于装置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
