INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体由于机械运动而具有的能量。", "primary_collocate": null, "pronunciation": "dòng néng", "ipa": "tʊŋ˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "动能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "球滚得越快，动能就越大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车的速度快，动能也大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水从高处流下来，位能变成了动能。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "物理课上，老师讲了动能和位能。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风的动能可以用来发电。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "质量越大，物体的动能越大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车停下来以后，它的动能就没有了。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把石头扔出去，石头获得了很大的动能。", "target_word": "动能", "complexity_tier": "T3", "furigana": "tā bǎ shítou rēng chūqù, shítou huòdé le hěn dà de dòngnéng.", "sentence_source": "generated"}, {"text": "运动员跑得快，身体的动能很大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "物理学中物体因机械运动而具有的能量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c7e75e3-72ef-41eb-a7d0-3ec13fec9d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动能", "is_correct": true, "explanation": "正确。叶片捕捉的是气流的运动能量，用来驱动磨坊。"}, {"text": "电能", "is_correct": false, "explanation": "语义：气流本身不含电能，叶片捕捉的是气流的运动能量，而不是电。"}, {"text": "阻力", "is_correct": false, "explanation": "搭配：“捕捉”的对象是能量，不能说捕捉“阻力”，而且驱动磨坊需要能量。"}, {"text": "水分", "is_correct": false, "explanation": "语义：气流不能提供水分来驱动磨坊，“捕捉气流水分”的说法与前后语境不相符。"}], "explanations": {"动能": "正确。叶片捕捉的是气流的运动能量，用来驱动磨坊。", "电能": "语义：气流本身不含电能，叶片捕捉的是气流的运动能量，而不是电。", "阻力": "搭配：“捕捉”的对象是能量，不能说捕捉“阻力”，而且驱动磨坊需要能量。", "水分": "语义：气流不能提供水分来驱动磨坊，“捕捉气流水分”的说法与前后语境不相符。"}, "sentence_index": 0, "correct_answer": "动能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台发动机的动能很强，车跑得很快。", "explanation": "这里应该用〈动力〉。动能指运动物体本身所具有的能量，说发动机推动车辆的能力要用动力。"}, {"text": "这块电池储存了很多动能。", "explanation": "这里应该用〈能量〉。电池储存的是化学能，不是运动物体的动能，应说储存了很多能量。"}, {"text": "这块石头放在山顶上，它的动能很大。", "explanation": "这里应该用〈势能〉。石头静止在山顶，具有的是重力势能，动能指运动物体的能量，静止的石头没有动能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动能", "is_correct": true, "explanation": "正确。句子说的是质量与物体动能之间的关系。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“越大”说的是大小或程度，颜色不能这样描述，而且颜色与质量无关。"}, {"text": "声音", "is_correct": false, "explanation": "语义：质量与声音的大小没有因果关系，前句“质量越大”无法推出“声音越大”。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：形状不用“越大”来描述，这里的“越大”说的是大小或程度。"}], "explanations": {"动能": "正确。句子说的是质量与物体动能之间的关系。", "颜色": "搭配：“越大”说的是大小或程度，颜色不能这样描述，而且颜色与质量无关。", "声音": "语义：质量与声音的大小没有因果关系，前句“质量越大”无法推出“声音越大”。", "形状": "搭配：形状不用“越大”来描述，这里的“越大”说的是大小或程度。"}, "sentence_index": 6, "correct_answer": "动能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的动能很大，能一口气举起两百公斤的杠铃。", "explanation": "这里应该用〈力气〉。动能指运动物体的能量，人能举起重物靠的是力气，不能说动能。"}, {"text": "这辆车的动能很快，十分钟就到了。", "explanation": "这里应该用〈速度〉。动能是能量的大小，只能说大或小，描述快慢要用速度。"}, {"text": "这个学生的动能很大，什么难题都能解决。", "explanation": "这里应该用〈能力〉。动能指运动物体的能量，说一个人的本领要用能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗子弹的动能很多。", "corrected_sentence": "这颗子弹的动能很大。", "error_description": "“动能”是表示大小的抽象量，描述大小要用“大”，不能用“很多”。错误在于补语“很多”，正确说法是“很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一脚把球踢出去，球就获得了一只动能。", "corrected_sentence": "他一脚把球踢出去，球就获得了一点动能。", "error_description": "量词错误：“动能”是抽象的量，数量常用“点”来计量；“只”用于动物或成对、成套的器物，不能用来数动能。错误在于量词“只”，应为“一点动能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
