INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "磨坊是加工谷物，把小麦等磨成面粉的作坊。", "primary_collocate": null, "pronunciation": "mò fáng", "ipa": "mwo˥˩ faŋ˧˥", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物。", "target_word": "磨坊", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "村口有一座老磨坊，农民常把小麦送到那里磨面。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊里的水车一直转着，面粉越磨越多。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲在磨坊工作了三十年。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座磨坊靠风力推动石磨。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我常去外婆家旁边的磨坊玩。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊的主人每天早上都要检查石磨。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊里到处是白白的面粉。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的磨坊现在成了一家小博物馆。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个磨坊需要很多水才能带动水车。", "target_word": "磨坊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "作坊：把小麦等谷物磨成面粉的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e92c63b-3679-442a-a17d-628878172573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "磨坊", "is_correct": true, "explanation": "磨坊：靠风力或水力推动石磨、加工谷物的作坊，与句中“碾磨谷物”相符。"}, {"text": "船", "is_correct": false, "explanation": "语义：船不能碾磨谷物，“驱动船碾磨谷物”说不通。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“驱动”后接的应是能碾磨谷物的装置，水泥不能用来碾磨谷物。"}, {"text": "书房", "is_correct": false, "explanation": "语义：书房是读书的地方，不能碾磨谷物。"}], "explanations": {"磨坊": "磨坊：靠风力或水力推动石磨、加工谷物的作坊，与句中“碾磨谷物”相符。", "船": "语义：船不能碾磨谷物，“驱动船碾磨谷物”说不通。", "水泥": "搭配：“驱动”后接的应是能碾磨谷物的装置，水泥不能用来碾磨谷物。", "书房": "语义：书房是读书的地方，不能碾磨谷物。"}, "sentence_index": 0, "correct_answer": "磨坊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们村有一只磨坊，农民都去那里磨面。", "explanation": "这里应该用〈座〉。磨坊是建筑，量词用“座”；“只”多用于动物或成对的物件，不能用来数磨坊。"}, {"text": "这家磨坊每天织出几百米布。", "explanation": "这里应该用〈布坊〉。磨坊加工谷物，织布要说〈布坊〉。"}, {"text": "这家磨坊每天做很多桌椅。", "explanation": "这里应该用〈作坊〉。磨坊只用来磨面粉，做桌椅的地方要说〈作坊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "磨坊", "is_correct": true, "explanation": "磨坊：加工谷物的作坊，主人要检查石磨，与句意相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行没有石磨，“银行的主人检查石磨”说不通。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：体育馆与石磨无关，“体育馆的主人检查石磨”说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“检查石磨”说明主体是磨坊或作坊之类的场所，钢琴不搭配。"}], "explanations": {"磨坊": "磨坊：加工谷物的作坊，主人要检查石磨，与句意相符。", "银行": "语义：银行没有石磨，“银行的主人检查石磨”说不通。", "体育馆": "语义：体育馆与石磨无关，“体育馆的主人检查石磨”说不通。", "钢琴": "搭配：“检查石磨”说明主体是磨坊或作坊之类的场所，钢琴不搭配。"}, "sentence_index": 6, "correct_answer": "磨坊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家磨坊每天烤出几百个面包，香味飘满了街道。", "explanation": "这里应该用〈面包房〉。磨坊只磨面粉，烤面包要用〈面包房〉。"}, {"text": "这家磨坊每天熬出几百斤白糖。", "explanation": "这里应该用〈糖坊〉。磨坊加工谷物，熬制白糖要用〈糖坊〉。"}, {"text": "这家磨坊每天酿出几百斤白酒。", "explanation": "这里应该用〈酒坊〉。磨坊不酿酒，酿白酒要说〈酒坊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村东头有一只磨坊，很多年没人用了。", "corrected_sentence": "村东头有一座磨坊，很多年没人用了。", "error_description": "量词错误：磨坊前应用“座”，不能用“只”（“只”多用于动物或成对的物件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们磨坊里磨了一上午面。", "corrected_sentence": "他们在磨坊里磨了一上午面。", "error_description": "漏掉介词“在”：表示动作地点要说“在磨坊里”，不能直接把“磨坊里”接在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
