INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用工具把东西压碎或磨成粉末。", "primary_collocate": null, "pronunciation": "niǎn mó", "ipa": "njɛn˨˩˦ mwo˧˥", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "农民用石磨碾磨小麦，做成面粉。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用石磨碾磨玉米，准备做饼。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能把豆子碾磨成粉。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人用大石头碾磨粮食。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水车的力量带动石磨碾磨麦子。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把药材碾磨了很久，终于变成细粉。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊里有人碾磨着新收的稻谷。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆要先碾磨，再用热水冲泡。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在碾磨石灰石，准备做水泥。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "碾磨了", "label": "完成体"}, {"form": "碾磨着", "label": "持续体"}, {"form": "碾磨过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用石磨、机器等工具把谷物、药材等压碎磨成粉末", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f2cad4d-5806-43f6-8a3e-713804406461') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收割", "is_correct": false, "explanation": "语义：收割是在田里割取作物，磨坊不进行收割，句中指的是加工环节。"}, {"text": "碾磨", "is_correct": true, "explanation": "碾磨：用磨具把谷物压碎磨成粉，与磨坊的加工作用相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”一般只与液体或饮品搭配，不能与固体谷物搭配。"}, {"text": "生长", "is_correct": false, "explanation": "配价：生长是不及物动词，不能带宾语“谷物”。"}], "explanations": {"收割": "语义：收割是在田里割取作物，磨坊不进行收割，句中指的是加工环节。", "碾磨": "碾磨：用磨具把谷物压碎磨成粉，与磨坊的加工作用相符。", "喝": "搭配：“喝”一般只与液体或饮品搭配，不能与固体谷物搭配。", "生长": "配价：生长是不及物动词，不能带宾语“谷物”。"}, "sentence_index": 0, "correct_answer": "碾磨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把刀碾磨得很锋利。", "explanation": "这里应该用〈磨〉。磨刀是使刀口变锋利，碾磨是把东西压碎成粉末，不能用于刀具。"}, {"text": "这台压路机能把路面碾磨平整。", "explanation": "这里应该用〈碾压〉。碾压指用重物滚压使表面平整，碾磨指压成粉末，路面不会变成粉末。"}, {"text": "奶奶用擀面杖把面团碾磨成薄饼。", "explanation": "这里应该用〈擀〉。擀是用擀面杖把面团压成薄饼，碾磨是把东西磨成粉末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：煮只能使药材变软、出味，不能把药材磨成细粉。"}, {"text": "站", "is_correct": false, "explanation": "配价：站是不及物动词，不能带宾语“药材”，也不能用于“把”字句。"}, {"text": "碾磨", "is_correct": true, "explanation": "碾磨：压碎磨成粉，与“终于变成细粉”的结果相呼应。"}, {"text": "浸泡", "is_correct": false, "explanation": "语义：浸泡是让药材泡在水里，不会使药材变成细粉。"}], "explanations": {"煮": "语义：煮只能使药材变软、出味，不能把药材磨成细粉。", "站": "配价：站是不及物动词，不能带宾语“药材”，也不能用于“把”字句。", "碾磨": "碾磨：压碎磨成粉，与“终于变成细粉”的结果相呼应。", "浸泡": "语义：浸泡是让药材泡在水里，不会使药材变成细粉。"}, "sentence_index": 6, "correct_answer": "碾磨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他碾磨了很久这个问题，还是没有结论。", "explanation": "这里应该用〈研究〉。研究可用于问题、课题，碾磨只用于把实物压碎，不能与抽象问题搭配。"}, {"text": "他把牛奶碾磨了一遍，然后喝掉了。", "explanation": "这里应该用〈搅〉。碾磨只能把固体压成粉末，牛奶是液体，不能碾磨。"}, {"text": "工人用砂纸把铁器碾磨得很光亮。", "explanation": "这里应该用〈抛光〉。抛光是使表面光滑发亮，碾磨是把东西压成粉末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把黄豆碾磨很细。", "corrected_sentence": "妈妈把黄豆碾磨得很细。", "error_description": "“碾磨很细”缺少“得”。动词带程度补语时，动词与补语之间要用“得”，正确形式为“碾磨得很细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器昨天把玉米碾磨了成粗粉。", "corrected_sentence": "这台机器昨天把玉米碾磨成了粗粉。", "error_description": "“了”位置错误。完成标记“了”应放在补语“成”之后，正确形式为“碾磨成了粗粉”，不能放在动词与补语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
