INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13671, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "谷物是指稻谷、小麦、玉米、高粱等可供食用的禾本科植物的籽粒，是人类主要的食物来源。", "primary_collocate": null, "pronunciation": "gǔ wù", "ipa": "ku˨˩˦ u˥˩", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "小麦、玉米和大米都是常见的谷物。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖各种谷物，也卖豆子。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在秋天收获谷物。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谷物需要放在干燥的地方保存。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早餐吃一碗谷物粥。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里堆满了一袋袋谷物。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水多，谷物长得很好。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包是用谷物磨成的粉做的。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谷物里有很多纤维，对身体好。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一袋谷物", "label": "量词"}, {"form": "一堆谷物", "label": "量词"}, {"form": "穀物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "稻谷、小麦、玉米等可食用的禾本科作物籽粒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f2cad4d-5806-43f6-8a3e-713804406461') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13671, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "污水", "is_correct": false, "explanation": "搭配：污水是液体，不能被碾磨加工。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是气体，不是可以碾磨的固体。"}, {"text": "谷物", "is_correct": true, "explanation": "谷物：可食用的禾本科籽粒，是磨坊碾磨的对象。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是抽象的艺术作品，不能用碾磨加工。"}], "explanations": {"污水": "搭配：污水是液体，不能被碾磨加工。", "空气": "语义：空气是气体，不是可以碾磨的固体。", "谷物": "谷物：可食用的禾本科籽粒，是磨坊碾磨的对象。", "歌曲": "语义：歌曲是抽象的艺术作品，不能用碾磨加工。"}, "sentence_index": 0, "correct_answer": "谷物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "棉花是重要的谷物。", "explanation": "这里应该用〈作物〉。棉花是经济作物，不属于谷物，谷物只指稻谷、小麦等禾本科籽粒。"}, {"text": "黄瓜是常见的谷物。", "explanation": "这里应该用〈蔬菜〉。黄瓜是蔬菜，不属于谷物。"}, {"text": "妈妈炒菜时放了一点谷物作调料。", "explanation": "这里应该用〈调料〉。谷物指稻谷、小麦等可供食用的籽粒，不是调味品，不能用作调料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "搭配：量词“袋”不能用来量汽车，“一袋袋汽车”不成立。"}, {"text": "蜜蜂", "is_correct": false, "explanation": "语义：活的蜜蜂不会装在袋子里堆放。"}, {"text": "谷物", "is_correct": true, "explanation": "谷物：装在袋中堆放的粮食，与“一袋袋”的量词搭配相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能装袋堆放在仓库里。"}], "explanations": {"汽车": "搭配：量词“袋”不能用来量汽车，“一袋袋汽车”不成立。", "蜜蜂": "语义：活的蜜蜂不会装在袋子里堆放。", "谷物": "谷物：装在袋中堆放的粮食，与“一袋袋”的量词搭配相符。", "月亮": "语义：月亮是天体，不能装袋堆放在仓库里。"}, "sentence_index": 6, "correct_answer": "谷物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种萝卜属于谷物。", "explanation": "这里应该用〈蔬菜〉。萝卜是蔬菜，不是禾本科植物的籽粒，不属于谷物。"}, {"text": "苹果是常见的谷物。", "explanation": "这里应该用〈水果〉。苹果是水果，不是谷物。"}, {"text": "猪肉属于谷物。", "explanation": "这里应该用〈肉类〉。猪肉属于肉类，不属于谷物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农场里晒着两只谷物。", "corrected_sentence": "农场里晒着两袋谷物。", "error_description": "量词用错。谷物常用“袋”计量，“只”多用于动物，不用于谷物，正确形式为“两袋谷物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仓库里有很多谷物们。", "corrected_sentence": "仓库里有很多谷物。", "error_description": "“们”用错。“们”只用于指人，不能加在“谷物”后面，正确形式为“有很多谷物”，“谷物们”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
