INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13672, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "借助水泵、风机等机械，把积水、废气等抽出并排放或移除。", "primary_collocate": null, "pronunciation": "chōu pái", "ipa": "ʈʂʰoʊ˥ pʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "工人用水泵抽排地下室的积水。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，村里的水要及时抽排。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的风机会把油烟抽排到室外。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "矿井里的有害气体必须抽排干净。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们连夜抽排了河边的污水。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风机正抽排着车间里的热气。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把池塘里的水抽排出去了。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隧道里要安装设备，抽排废气。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水位太高，必须马上抽排。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽排了", "label": "完成体"}, {"form": "抽排着", "label": "持续体"}, {"form": "抽排过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "借助水泵、风机等把积水、废气等排出或移除", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f2cad4d-5806-43f6-8a3e-713804406461') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽排", "is_correct": true, "explanation": "正确：抽排指借助机器把水、气弄走，与“驱动……抽排沼泽积水”的语境相符。"}, {"text": "灌溉", "is_correct": false, "explanation": "语义：灌溉是把水引入田地，与排除积水的意思相反。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于庄稼，不能和“积水”搭配。"}, {"text": "翻耕", "is_correct": false, "explanation": "语义：翻耕是翻松土地，与处理沼泽积水无关。"}], "explanations": {"抽排": "正确：抽排指借助机器把水、气弄走，与“驱动……抽排沼泽积水”的语境相符。", "灌溉": "语义：灌溉是把水引入田地，与排除积水的意思相反。", "收割": "搭配：“收割”用于庄稼，不能和“积水”搭配。", "翻耕": "语义：翻耕是翻松土地，与处理沼泽积水无关。"}, "sentence_index": 0, "correct_answer": "抽排"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工程师很快抽排了机器的故障。", "explanation": "这里应该用〈排除〉。抽排只指抽出水、气等，不能用于故障。"}, {"text": "这个难题我们很快就抽排了。", "explanation": "这里应该用〈解决〉。抽排指弄走水、气，不能用于问题。"}, {"text": "我们把客人抽排走了。", "explanation": "这里应该用〈送〉。抽排只用于水、气等，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽排", "is_correct": true, "explanation": "正确：抽排指把热气等弄走，与“风机”的作用相符。"}, {"text": "加热", "is_correct": false, "explanation": "语义：热气已经是热的，风机是把它排走，不是加热它。"}, {"text": "凝结", "is_correct": false, "explanation": "语义：凝结是遇冷变成液体，风机并不这样处理热气。"}, {"text": "烘烤", "is_correct": false, "explanation": "搭配：“烘烤”用于食物，不能和“车间里的热气”搭配。"}], "explanations": {"抽排": "正确：抽排指把热气等弄走，与“风机”的作用相符。", "加热": "语义：热气已经是热的，风机是把它排走，不是加热它。", "凝结": "语义：凝结是遇冷变成液体，风机并不这样处理热气。", "烘烤": "搭配：“烘烤”用于食物，不能和“车间里的热气”搭配。"}, "sentence_index": 6, "correct_answer": "抽排"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司从各部门抽排了几名员工。", "explanation": "这里应该用〈抽调〉。抽排只指弄走水、气，不能用于调配人员。"}, {"text": "科学家抽排了很多数据。", "explanation": "这里应该用〈收集〉。抽排不能用于数据。"}, {"text": "他们抽排了田里的害虫。", "explanation": "这里应该用〈消灭〉。抽排只指弄走水、气，不能用于害虫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器能把废气抽排在屋外。", "corrected_sentence": "这台机器能把废气抽排到屋外。", "error_description": "“抽排”的去向要用介词“到”，表示排出的目的地；用“在”表示位置，不符合说法，应说“抽排到屋外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们连夜把河边的污水抽排了干净了。", "corrected_sentence": "他们连夜把河边的污水抽排干净了。", "error_description": "“抽排”后直接跟结果补语“干净”，中间不能再加“了”。结果补语应紧跟动词，“了”放在句末，应说“抽排干净了”，不能说“抽排了干净了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
