INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13675, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利用机械装置（如齿轮、链条、皮带等）将动力或运动从原动机传递到工作机的过程。", "primary_collocate": null, "pronunciation": "jī xiè chuán dòng", "ipa": "tɕi˥ ɕjɛ˥˩ tʂʰwan˧˥ twʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这种机械传动模式虽效率有限，却在缺乏化石燃料的地域构建了自洽的能源循环。", "target_word": "机械传动", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "自行车靠链条实现机械传动。", "target_word": "机械传动", "complexity_tier": "T3", "furigana": "zì xíng chē kào liàn tiáo shí xiàn jī xiè chuán dòng", "sentence_source": "generated"}, {"text": "汽车里有很多机械传动的零件。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "齿轮是常见的机械传动方式。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器的机械传动出了问题，声音很大。", "target_word": "机械传动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在检查机械传动系统。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮带和链条都可以用于机械传动。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机械传动能把电机的动力传到轮子上。", "target_word": "机械传动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了机械传动的原理。", "target_word": "机械传动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和电力传动比，机械传动更简单，也便宜。", "target_word": "机械传动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "机械传动系统", "label": "复合"}, {"form": "機械傳動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用齿轮、链条、皮带等把动力传给工作机的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f2cad4d-5806-43f6-8a3e-713804406461') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机械传动", "is_correct": true, "explanation": "正确。“机械传动模式”指用机械方式传递动力的模式，与效率和能源循环的语境相合。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：饮食模式与效率、能源循环无关，句子读不通。"}, {"text": "货币", "is_correct": false, "explanation": "语义：货币模式不能构建能源循环。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“语言模式”指言语结构，与“构建能源循环”不搭。"}], "explanations": {"机械传动": "正确。“机械传动模式”指用机械方式传递动力的模式，与效率和能源循环的语境相合。", "饮食": "语义：饮食模式与效率、能源循环无关，句子读不通。", "货币": "语义：货币模式不能构建能源循环。", "语言": "搭配：“语言模式”指言语结构，与“构建能源循环”不搭。"}, "sentence_index": 0, "correct_answer": "机械传动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机械传动很大，工人搬不动它。", "explanation": "这里应该用〈机器〉。机械传动是传递动力的方式，不是可以搬动的实物，不能说“这台”“很大”。"}, {"text": "机械传动把电能变成动力。", "explanation": "这里应该用〈电动机〉。机械传动只是传递动力，不能把电能转换成动力。"}, {"text": "这台机器的机械传动来自柴油。", "explanation": "这里应该用〈动力〉。动力是能量的来源，柴油可以提供动力；机械传动是传递动力的过程，不能作为能量的来源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机械传动", "is_correct": true, "explanation": "正确。皮带和链条可以用于机械传动。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：皮带和链条不能用于烹饪。"}, {"text": "诗歌", "is_correct": false, "explanation": "搭配：“用于”后接的是应用对象，皮带和链条不用于诗歌。"}, {"text": "礼仪", "is_correct": false, "explanation": "语义：皮带和链条与礼仪场合无关，句子读不通。"}], "explanations": {"机械传动": "正确。皮带和链条可以用于机械传动。", "烹饪": "语义：皮带和链条不能用于烹饪。", "诗歌": "搭配：“用于”后接的是应用对象，皮带和链条不用于诗歌。", "礼仪": "语义：皮带和链条与礼仪场合无关，句子读不通。"}, "sentence_index": 6, "correct_answer": "机械传动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生建议他每天做适量机械传动。", "explanation": "这里应该用〈运动〉。机械传动指用零件传递动力，不能用来指人的锻炼。"}, {"text": "工厂里用机械传动煎鸡蛋。", "explanation": "这里应该用〈煎锅〉。机械传动是传递动力的方式，不能用来煎鸡蛋，煎鸡蛋要用煎锅。"}, {"text": "他每天晚上都住在机械传动里。", "explanation": "这里应该用〈房间〉。人住在房间里；机械传动是传递动力的过程，不是可以居住的地方，不能说“住在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把机械传动是新换的。", "corrected_sentence": "这套机械传动是新换的。", "error_description": "量词错误：「这把机械传动」应为「这套机械传动」。“把”用于有柄的器具，机械传动这类成套的系统要用“套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器的机械传动了坏。", "corrected_sentence": "这台机器的机械传动坏了。", "error_description": "了的位置错误：「传动了坏」应为「传动坏了」。“坏”在这里作谓语，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
