INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13677, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "燃料是指能够通过燃烧或化学反应释放能量，用于产生热能或动力的物质。", "primary_collocate": null, "pronunciation": "rán liào", "ipa": "ɻan˧˥ liɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个地区缺乏化石燃料，只能靠风能和太阳能发电。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来能源图景或将超越“发电”本身——建筑幕墙成为透明太阳能收集器，道路涂层集成压电发电单元，甚至人工光合作用系统直接将二氧化碳转化为燃料。", "target_word": "燃料", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "汽车需要燃料才能跑。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种燃料烧起来很干净。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭用的燃料很特别。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加油站卖汽车用的燃料。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上的燃料快用完了，我们得回港口。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂想用便宜的燃料代替煤。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞行前，工人要先加满燃料。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燃料的价格涨了，运费也跟着涨了。", "target_word": "燃料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "化石燃料", "label": "复合"}], "register": "中性", "sense_fingerprint": "通过燃烧或化学反应释放能量以产生热或动力的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6965bde7-6897-4797-b880-940007ee84e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13677, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃料", "is_correct": true, "explanation": "正确：“化石燃料”是固定说法，指煤、石油、天然气等。"}, {"text": "电池", "is_correct": false, "explanation": "搭配：“化石电池”不是常用说法，不能与“化石”构成固定搭配。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材不属于化石，“化石木材”与句中的能源语境不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“化石石头”重复且不成词，与句中能源语境无关。"}], "explanations": {"燃料": "正确：“化石燃料”是固定说法，指煤、石油、天然气等。", "电池": "搭配：“化石电池”不是常用说法，不能与“化石”构成固定搭配。", "木材": "语义：木材不属于化石，“化石木材”与句中的能源语境不符。", "石头": "搭配：“化石石头”重复且不成词，与句中能源语境无关。"}, "sentence_index": 0, "correct_answer": "燃料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们从仓库里搬来了一只燃料。", "explanation": "这里应该用〈桶〉。燃料作量词不用“只”，“只”用于动物，应使用“桶”或“袋”。"}, {"text": "这种燃料吃起来很香。", "explanation": "这里应该用〈粮食〉。燃料是用来燃烧的，不能吃，粮食才能用“吃”来形容。"}, {"text": "农场用这种燃料喂牛。", "explanation": "这里应该用〈饲料〉。燃料用于燃烧产生能量，不能用来喂养牲畜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "燃料", "is_correct": true, "explanation": "正确：船上的燃料快用完了，所以需要回港口补给。"}, {"text": "船长", "is_correct": false, "explanation": "语义：船长不是可以“用完”的消耗品，“船长快用完了”不成立。"}, {"text": "桥梁", "is_correct": false, "explanation": "搭配：“桥梁”不能与“用完了”搭配，且与船上的情境无关。"}, {"text": "灯塔", "is_correct": false, "explanation": "语义：灯塔是固定的建筑，不能“用完”，句子不通。"}], "explanations": {"燃料": "正确：船上的燃料快用完了，所以需要回港口补给。", "船长": "语义：船长不是可以“用完”的消耗品，“船长快用完了”不成立。", "桥梁": "搭配：“桥梁”不能与“用完了”搭配，且与船上的情境无关。", "灯塔": "语义：灯塔是固定的建筑，不能“用完”，句子不通。"}, "sentence_index": 6, "correct_answer": "燃料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼用的燃料很结实。", "explanation": "这里应该用〈材料〉。燃料指用来燃烧的物质，建筑用的是材料，不是燃料。"}, {"text": "这种燃料可以治病。", "explanation": "这里应该用〈药材〉。燃料用于燃烧，不能用来治病。"}, {"text": "孩子们喜欢这个燃料。", "explanation": "这里应该用〈玩具〉。燃料是用来燃烧的物质，孩子们不会把它当作玩具来喜欢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在仓库里存了一只燃料。", "corrected_sentence": "他们在仓库里存了一桶燃料。", "error_description": "量词错误：燃料不用“只”来数，这里应改为“桶”。", "correct_sentence_indices": [2, 4, 5]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把燃料加进着油箱。", "corrected_sentence": "工人把燃料加进了油箱。", "error_description": "体标错误：把字句表示已完成的动作，动词后应用“了”，不能用“着”。正确说法是“把燃料加进了油箱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
