INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13678, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物自身逻辑一致，没有矛盾。", "primary_collocate": null, "pronunciation": "zì qià", "ipa": "tsɨ˥˩ tɕʰja˥˩", "syllable_count": 2, "sentences": [{"text": "他把每一步推理都串起来，整个论证十分自洽。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的理论很自洽，前后没有矛盾。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事不自洽，前面说他没去过，后面又说他去了。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的推理很自洽，逻辑清楚。", "target_word": "自洽", "complexity_tier": "T3", "furigana": "lǎo shī shuō wǒ de tuī lǐ hěn zì qià, luó jí qīngchu.", "sentence_source": "generated"}, {"text": "这篇文章的观点不够自洽。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想让这个模型更自洽。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的说法听起来自洽，别人也能接受。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个自洽的计划，每一步都互相配合。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个结论互相矛盾，所以整个理论不自洽。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的解释很自洽，我找不到问题。", "target_word": "自洽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自洽性", "label": "派生"}], "register": "书面语", "sense_fingerprint": "理论、说法本身逻辑一致，前后没有矛盾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb351630-da49-476b-8754-b40ebd05cc45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自洽", "is_correct": true, "explanation": "自洽：指论证前后一致、没有矛盾，修饰“论证”最恰当，与“每一步推理都串起来”的语境相符"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，论证没有咸淡，句意不通"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容嗓音，论证没有嗓音，句意不通"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容含水分的状态，不用来形容论证"}], "explanations": {"自洽": "自洽：指论证前后一致、没有矛盾，修饰“论证”最恰当，与“每一步推理都串起来”的语境相符", "咸": "语义：“咸”形容味道，论证没有咸淡，句意不通", "沙哑": "语义：“沙哑”形容嗓音，论证没有嗓音，句意不通", "潮湿": "语义：“潮湿”形容含水分的状态，不用来形容论证"}, "sentence_index": 0, "correct_answer": "自洽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个人的看法很自洽。", "explanation": "这里应该用〈一致〉。自洽指说法或理论内部前后没有矛盾，不用来说两个人之间的看法相同"}, {"text": "同事之间的关系很自洽。", "explanation": "这里应该用〈融洽〉。自洽形容说法、理论本身没有矛盾，不用来形容人与人之间的关系"}, {"text": "这个价格很自洽。", "explanation": "这里应该用〈合理〉。自洽指内部逻辑一致，不用来评价价格是否公道"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自洽", "is_correct": true, "explanation": "自洽：说法本身前后一致、合乎逻辑，与“别人也能接受”相符"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，说法听不出咸淡，句意不通"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”形容人不说话，说法本身不会沉默"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”多形容颜色，不与“听起来”搭配，也不用于说法"}], "explanations": {"自洽": "自洽：说法本身前后一致、合乎逻辑，与“别人也能接受”相符", "咸": "语义：“咸”形容味道，说法听不出咸淡，句意不通", "沉默": "语义：“沉默”形容人不说话，说法本身不会沉默", "鲜艳": "搭配：“鲜艳”多形容颜色，不与“听起来”搭配，也不用于说法"}, "sentence_index": 6, "correct_answer": "自洽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的色彩很自洽。", "explanation": "这里应该用〈和谐〉。自洽指说法或体系内部没有矛盾，不用来形容色彩搭配是否协调"}, {"text": "各部门配合得很自洽。", "explanation": "这里应该用〈协调〉。自洽形容一个体系内部前后一致，不用来形容各部门之间的配合"}, {"text": "这顿饭的营养很自洽。", "explanation": "这里应该用〈平衡〉。自洽指逻辑上前后不矛盾，不用来形容饭菜的营养是否均衡"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作者提出了一个自洽地解释框架。", "corrected_sentence": "作者提出了一个自洽的解释框架。", "error_description": "错误：“自洽地”。正确：“自洽的”。“一个”后面要接名词性结构，“自洽地解释框架”是动词性结构，应用定语“自洽的”修饰名词“解释框架”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套推导很自洽性，每一步都站得住。", "corrected_sentence": "这套推导很自洽，每一步都站得住。", "error_description": "错误：“很自洽性”。正确：“很自洽”。“自洽性”是名词，不能受程度副词“很”修饰，这里应用形容词“自洽”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13679, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主动式", "is_correct": true, "explanation": "反义：被动式与主动式相对，主动式的主语发出动作，被动式的主语承受动作"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是家具，与被动式的语法或做事态度都无关"}, {"text": "天空", "is_correct": false, "explanation": "无关：“天空”是自然景物，与被动式没有反义关系"}, {"text": "花朵", "is_correct": false, "explanation": "无关：“花朵”是植物的一部分，与被动式没有反义关系"}], "correct_answer": "主动式", "explanations": {"主动式": "反义：被动式与主动式相对，主动式的主语发出动作，被动式的主语承受动作", "桌子": "无关：“桌子”是家具，与被动式的语法或做事态度都无关", "天空": "无关：“天空”是自然景物，与被动式没有反义关系", "花朵": "无关：“花朵”是植物的一部分，与被动式没有反义关系"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13679, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主动式", "is_correct": true, "explanation": "反义：主动式与被动式相对，主语发出动作，与被动式的主语承受动作相反"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与被动式的语法或做事态度无关"}, {"text": "石头", "is_correct": false, "explanation": "无关：“石头”是自然物，与被动式没有反义关系"}, {"text": "星星", "is_correct": false, "explanation": "无关：“星星”是天体，与被动式没有反义关系"}], "correct_answer": "主动式", "explanations": {"主动式": "反义：主动式与被动式相对，主语发出动作，与被动式的主语承受动作相反", "河流": "无关：“河流”是地理事物，与被动式的语法或做事态度无关", "石头": "无关：“石头”是自然物，与被动式没有反义关系", "星星": "无关：“星星”是天体，与被动式没有反义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13679, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "主语是动作的承受者，表示接受动作的状态或方式。", "primary_collocate": null, "pronunciation": "bèi dòng shì", "ipa": "pei˥˩ tʊŋ˥˩ ʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "“书被他弄丢了”是典型的被动式。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话用的是被动式，主语接受动作。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英语里被动式很常见。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天讲了被动式的用法。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语的被动式有时不用特别的词。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分不清主动式和被动式。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个句子改成被动式。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有很多被动式的例子。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被动式的主语不做动作，只接受动作。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个练习是学被动式，不难。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "主语承受动作的句式或方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb351630-da49-476b-8754-b40ebd05cc45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13679, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被动式", "is_correct": true, "explanation": "被动式：主语“书”承受“弄丢”的动作，是典型的被动式句式，与句意相符"}, {"text": "把字句", "is_correct": false, "explanation": "语义：句中用“被”引出施事，不是把字句（把字句用“把”）"}, {"text": "疑问句", "is_correct": false, "explanation": "语义：句中是陈述，没有疑问，不是疑问句"}, {"text": "比较句", "is_correct": false, "explanation": "语义：句中没有比较关系，不是比较句"}], "explanations": {"被动式": "被动式：主语“书”承受“弄丢”的动作，是典型的被动式句式，与句意相符", "把字句": "语义：句中用“被”引出施事，不是把字句（把字句用“把”）", "疑问句": "语义：句中是陈述，没有疑问，不是疑问句", "比较句": "语义：句中没有比较关系，不是比较句"}, "sentence_index": 0, "correct_answer": "被动式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天把书借给了朋友，这句话用的是被动式。", "explanation": "这里应该用〈主动式〉。句子的主语“我”是动作的发出者，应当用主动式"}, {"text": "这句话用的是被动式，主语是动作的发出者。", "explanation": "这里应该用〈主动式〉。句子的主语是动作的发出者，被动式的主语承受动作，应当用主动式"}, {"text": "他对这件事的态度很被动式。", "explanation": "这里应该用〈被动〉。被动式是语法名词，不能用“很”修饰，形容态度应说“被动”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13679, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被动式", "is_correct": true, "explanation": "被动式：指主语承受动作的句式，与“改成”的对象相符"}, {"text": "草坪", "is_correct": false, "explanation": "语义：句子不能改成草坪，“草坪”不是句式"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不能作为句子改写的结果"}, {"text": "复数", "is_correct": false, "explanation": "搭配：“改成”的对象应是句式，“复数”只用于名词，不说“改成复数”"}], "explanations": {"被动式": "被动式：指主语承受动作的句式，与“改成”的对象相符", "草坪": "语义：句子不能改成草坪，“草坪”不是句式", "苹果": "语义：“苹果”是水果，不能作为句子改写的结果", "复数": "搭配：“改成”的对象应是句式，“复数”只用于名词，不说“改成复数”"}, "sentence_index": 6, "correct_answer": "被动式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学的是一本被动式。", "explanation": "这里的量词不对。〈本〉用于书籍，被动式是语法形式，应该用〈种〉"}, {"text": "这是一座被动式，不难。", "explanation": "这里的量词不对。〈座〉用于山、楼房等大型固定物，被动式应该用〈种〉"}, {"text": "老师写下了一张被动式。", "explanation": "这里的量词不对。〈张〉用于纸张、桌子等平面的东西，被动式应该用〈种〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把被动式们的三种形式都列在了黑板上。", "corrected_sentence": "老师把被动式的三种形式都列在了黑板上。", "error_description": "错误：“被动式们”。正确：“被动式”。“被动式”是抽象的语法名称，不能加“们”表示复数，应直接说“被动式的三种形式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师让我们把主动句改被动式。", "corrected_sentence": "老师让我们把主动句改成被动式。", "error_description": "错误：“改被动式”。正确：“改成被动式”。表示变成另一种事物时，“改”后面要用结果补语“成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
