INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13681, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体厚实沉重；也形容人稳重、有分量，或情意深厚。", "primary_collocate": null, "pronunciation": "hòu zhòng", "ipa": "xoʊ˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "与此同时，被动式太阳能设计已见于古代建筑——厚重大理石墙体吸收日间热量，夜间缓慢释放，形成天然温控系统。", "target_word": "厚重", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这扇门又厚重又结实，一个人很难推开。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拉上厚重的窗帘，房间一下子暗了。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天大家都穿着厚重的棉衣。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为人厚重，大家都愿意相信他。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老教授声音厚重，听起来很让人放心。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人做事厚重，遇事总是三思而后行。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份厚重的情意，我一直记在心里。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古城的城墙厚重，已经站了几百年。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老校长待人厚重，老师们都很敬佩他。", "target_word": "厚重", "complexity_tier": "T3", "furigana": "hòu zhòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "厚重感", "label": "派生"}], "register": "中性", "sense_fingerprint": "形容物体厚实沉重，或人稳重、情意深厚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb351630-da49-476b-8754-b40ebd05cc45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厚重", "is_correct": true, "explanation": "正确答案。“厚重”形容石墙又厚又重，与“大理石墙体”搭配。"}, {"text": "轻盈", "is_correct": false, "explanation": "语义：轻盈指轻巧，与大理石墙体的分量相矛盾。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：清脆形容声音，不用来形容墙体的分量，句意不通"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：潮湿形容含水分的状态，与墙体的厚重分量无关，不合句意"}], "explanations": {"厚重": "正确答案。“厚重”形容石墙又厚又重，与“大理石墙体”搭配。", "轻盈": "语义：轻盈指轻巧，与大理石墙体的分量相矛盾。", "清脆": "语义：清脆形容声音，不用来形容墙体的分量，句意不通", "潮湿": "语义：潮湿形容含水分的状态，与墙体的厚重分量无关，不合句意"}, "sentence_index": 0, "correct_answer": "厚重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衬衫很厚重，适合夏天穿。", "explanation": "这里应该用〈轻薄〉。厚重指又厚又重，夏天穿的衬衫应说轻薄。"}, {"text": "这道数学题很厚重，我三分钟就做完了。", "explanation": "这里应该用〈简单〉。厚重形容物体的分量或人的稳重，不用于形容题目的难易。"}, {"text": "这个小孩做事很厚重，总是乱跑。", "explanation": "这里应该用〈毛躁〉。厚重表示稳重，与“总是乱跑”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厚重", "is_correct": true, "explanation": "正确答案。“厚重”形容人稳重，与“遇事总是三思而后行”相合。"}, {"text": "轻浮", "is_correct": false, "explanation": "语义：轻浮指举止不稳重，与“三思而后行”的谨慎形象相反。"}, {"text": "草率", "is_correct": false, "explanation": "语义：草率指做事马虎，与“三思而后行”的谨慎形象相反。"}, {"text": "随便", "is_correct": false, "explanation": "语义：随便指不拘束，与“三思而后行”的谨慎形象矛盾。"}], "explanations": {"厚重": "正确答案。“厚重”形容人稳重，与“遇事总是三思而后行”相合。", "轻浮": "语义：轻浮指举止不稳重，与“三思而后行”的谨慎形象相反。", "草率": "语义：草率指做事马虎，与“三思而后行”的谨慎形象相反。", "随便": "语义：随便指不拘束，与“三思而后行”的谨慎形象矛盾。"}, "sentence_index": 6, "correct_answer": "厚重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张纸很厚重，一阵风就吹走了。", "explanation": "这里应该用〈轻薄〉。厚重指又厚又重，与“一阵风就吹走”矛盾。"}, {"text": "这盆花很厚重，我一只手就能端起来。", "explanation": "这里应该用〈轻巧〉。厚重指分量大，与“一只手就能端起”矛盾。"}, {"text": "他走路的步子很厚重，像一阵风一样快。", "explanation": "这里应该用〈轻快〉。厚重形容稳重或分量，不形容步子轻快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块石头厚重很，搬起来很费力。", "corrected_sentence": "这块石头厚重得很，搬起来很费力。", "error_description": "错误形式：厚重很。正确形式：厚重得很。形容词后表示程度要用“得很”，不能只说“形容词+很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张桌子很厚重地，两个人才搬得动。", "corrected_sentence": "这张桌子很厚重，两个人才搬得动。", "error_description": "错误：“厚重地”。正确：“很厚重”。“地”用于修饰动词，“厚重”作谓语时不加“地”，去掉即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
