INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13683, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13683, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指建筑物中起分隔、围护作用的垂直构件，通常由砖石或混凝土等材料构成。", "primary_collocate": null, "pronunciation": "qiáng tǐ", "ipa": "tɕʰiaŋ˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "与此同时，被动式太阳能设计已见于古代建筑——厚重大理石墙体吸收日间热量，夜间缓慢释放，形成天然温控系统。", "target_word": "墙体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "地震以后，这座楼的墙体出现了裂缝。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在给墙体刷白色的涂料。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新墙体很厚，冬天房间里很暖和。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧房子的墙体里进了水，墙皮都掉了。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用红砖砌成了房子的墙体。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙体太薄，隔壁的声音听得很清楚。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师说这个墙体不能拆，因为它撑着楼板。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，厚厚的墙体能挡住外面的热气。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新建的墙体还没干，大家不要靠近。", "target_word": "墙体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "墙体材料", "label": "复合"}, {"form": "墙体裂缝", "label": "复合"}], "register": "中性", "sense_fingerprint": "建筑中起分隔围护作用的墙的主体结构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb351630-da49-476b-8754-b40ebd05cc45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13683, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墙体", "is_correct": true, "explanation": "墙体：建筑中厚重的墙主体，能吸收并缓慢释放热量，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能像墙体那样厚重蓄热，与“厚重大理石”矛盾。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：树叶不是建筑构件，不与“厚重大理石”搭配。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线不能吸收日间热量，与句意不符。"}], "explanations": {"墙体": "墙体：建筑中厚重的墙主体，能吸收并缓慢释放热量，符合句意。", "窗户": "语义：窗户不能像墙体那样厚重蓄热，与“厚重大理石”矛盾。", "树叶": "搭配：树叶不是建筑构件，不与“厚重大理石”搭配。", "电线": "语义：电线不能吸收日间热量，与句意不符。"}, "sentence_index": 0, "correct_answer": "墙体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刷了一张墙体。", "explanation": "这里应该用〈面〉。墙体是竖直的面状结构，常用“面”计量，不用“张”。"}, {"text": "墙上贴满了墙体。", "explanation": "这里应该用〈墙纸〉。“贴”用于墙纸、瓷砖等覆盖材料，墙体是建筑结构，不能贴在墙上。"}, {"text": "厨房的地面上铺满了墙体。", "explanation": "这里应该用〈瓷砖〉。“铺”用于瓷砖、地砖等平面材料，墙体是竖直的承重结构，不能铺在地面上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墙体", "is_correct": true, "explanation": "墙体：建筑中的墙，可以“太薄”，符合句意。"}, {"text": "山", "is_correct": false, "explanation": "语义：山不能说“太薄”，也不会让声音从中传过去。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包不作隔墙，不能说它“太薄”来隔音。"}, {"text": "面条", "is_correct": false, "explanation": "体貌：面条是细长的食物，不是能隔开房间的平面结构。"}], "explanations": {"墙体": "墙体：建筑中的墙，可以“太薄”，符合句意。", "山": "语义：山不能说“太薄”，也不会让声音从中传过去。", "书包": "搭配：书包不作隔墙，不能说它“太薄”来隔音。", "面条": "体貌：面条是细长的食物，不是能隔开房间的平面结构。"}, "sentence_index": 6, "correct_answer": "墙体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客厅中间摆着墙体，用来挡住视线。", "explanation": "这里应该用〈屏风〉。屏风可以摆放、移动，墙体是固定的建筑结构，不能摆放。"}, {"text": "他躺在墙体上睡觉，很快就睡着了。", "explanation": "这里应该用〈床〉。睡觉要躺在床上，墙体是竖直的建筑构件，不能躺在上面睡觉。"}, {"text": "墙上挂着墙体，很好看。", "explanation": "这里应该用〈画〉。“挂”的对象多是画、镜子等小物件，墙体是建筑结构，挂不上去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只墙体很厚。", "corrected_sentence": "这面墙体很厚。", "error_description": "量词错误：墙体是竖直的面状结构，量词应用“面”，“只”用于动物或小件物品，不能用来计量墙体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把旧墙体拆了掉。", "corrected_sentence": "工人把旧墙体拆掉了。", "error_description": "结果补语位置错误：“拆掉了”是正确形式，“拆了掉”的补语“掉”位置颠倒了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
