INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13684, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13684, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指食物或燃料等物质在体内或燃烧时释放出的能量，通常以卡路里为单位。", "primary_collocate": null, "pronunciation": "rè liàng", "ipa": "ʐɤ˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "运动员每天消耗的热量远超普通人。", "target_word": "热量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤燃烧时会放出大量热量。", "target_word": "热量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木柴燃烧时能释放很多热量。", "target_word": "热量", "complexity_tier": "T3", "furigana": "mù chái rán shāo shí néng shì fàng hěn duō rè liàng", "sentence_source": "generated"}, {"text": "这碗面条的热量不低。", "target_word": "热量", "complexity_tier": "T3", "furigana": "zhè wǎn miàn tiáo de rè liàng bù dī", "sentence_source": "generated"}, {"text": "这种燃料燃烧时，每克放出的热量很高。", "target_word": "热量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人体靠食物中的热量维持体温。", "target_word": "热量", "complexity_tier": "T3", "furigana": "rén tǐ kào shí wù zhōng de rè liàng wéi chí tǐ wēn", "sentence_source": "generated"}, {"text": "吃甜食容易摄入过多热量。", "target_word": "热量", "complexity_tier": "T3", "furigana": "chī tián shí róng yì shè rù guò duō rè liàng", "sentence_source": "generated"}, {"text": "厚厚的棉被能留住身体散出的热量。", "target_word": "热量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天然气燃烧时会释放热量，但要注意安全。", "target_word": "热量", "complexity_tier": "T3", "furigana": "tiān rán qì rán shāo shí huì shì fàng rè liàng dàn yào zhù yì ān quán", "sentence_source": "generated"}, {"text": "成年人每天需要足够的热量来工作。", "target_word": "热量", "complexity_tier": "T3", "furigana": "chéng nián rén měi tiān xū yào zú gòu de rè liàng lái gōng zuò", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物质燃烧或在体内释放的能量，可用卡路里计量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b8958f0-ffe2-4271-bc78-1dc054604ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13684, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "热量", "is_correct": true, "explanation": "热量（rè liàng）：物质燃烧或在体内释放的能量，即正确答案。"}, {"text": "热恋", "is_correct": false, "explanation": "rè liàn 与 rè liàng 的韵母不同（an 与 ang），意思是热恋。"}, {"text": "热浪", "is_correct": false, "explanation": "làng 与 liàng 少了介音 i，韵母不同，意思是热浪。"}, {"text": "热像", "is_correct": false, "explanation": "xiàng 与 liàng 声母不同（x 与 l），意思是热像，即热成像。"}], "explanations": {"热量": "热量（rè liàng）：物质燃烧或在体内释放的能量，即正确答案。", "热恋": "rè liàn 与 rè liàng 的韵母不同（an 与 ang），意思是热恋。", "热浪": "làng 与 liàng 少了介音 i，韵母不同，意思是热浪。", "热像": "xiàng 与 liàng 声母不同（x 与 l），意思是热像，即热成像。"}, "sentence_index": null, "correct_answer": "热量"}, "level_3": {"options": [{"text": "热量", "is_correct": true, "explanation": "热量：运动消耗的能量，与「消耗」搭配，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音不能被消耗，「消耗的声音」说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不能被消耗，与句意不合。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：字体不能被消耗，「消耗的字体」说不通。"}], "explanations": {"热量": "热量：运动消耗的能量，与「消耗」搭配，符合句意。", "声音": "搭配：声音不能被消耗，「消耗的声音」说不通。", "颜色": "搭配：颜色不能被消耗，与句意不合。", "字体": "搭配：字体不能被消耗，「消耗的字体」说不通。"}, "sentence_index": 0, "correct_answer": "热量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块饼干含有很多个热量。", "explanation": "量词用错。热量是抽象的能量，不能用“个”计量，应说“很多热量”。"}, {"text": "这份沙拉含有三只热量。", "explanation": "量词用错。“只”用于动物等，热量不能用“只”计量。"}, {"text": "这片面包含有一颗热量。", "explanation": "量词用错。“颗”用于粒状物，热量不能用“颗”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热量", "is_correct": true, "explanation": "热量：食物中所含、被身体摄入的能量，与“摄入过多”相符。"}, {"text": "图片", "is_correct": false, "explanation": "语义：图片不能被摄入，吃甜食摄入的是能量。"}, {"text": "分贝", "is_correct": false, "explanation": "搭配：“摄入”不搭配“分贝”，分贝是声音强度的单位。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体与吃甜食无关，不能被摄入。"}], "explanations": {"热量": "热量：食物中所含、被身体摄入的能量，与“摄入过多”相符。", "图片": "语义：图片不能被摄入，吃甜食摄入的是能量。", "分贝": "搭配：“摄入”不搭配“分贝”，分贝是声音强度的单位。", "字体": "语义：字体与吃甜食无关，不能被摄入。"}, "sentence_index": 6, "correct_answer": "热量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他发烧了，热量超过了三十八度。", "explanation": "这里应该用〈体温〉。热量是能量，不以“度”计量，人体冷热要说体温。"}, {"text": "这部手机的热量只剩百分之十了。", "explanation": "这里应该用〈电量〉。电量指电池的电，热量指物质释放的热能，不能说手机的热量。"}, {"text": "他对工作充满热量。", "explanation": "这里应该用〈热情〉。热量指物质释放的能量，形容人的情绪要用热情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块蛋糕的一个热量很高。", "corrected_sentence": "这块蛋糕的热量很高。", "error_description": "“一个热量”多了量词“一个”。热量是抽象的能量，不能用“个”计量，应直接说“热量很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "运动能把多余的热量喝掉。", "corrected_sentence": "运动能把多余的热量消耗掉。", "error_description": "动词搭配错误：热量不能「喝」，应说「消耗掉」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
