INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13685, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "对温度进行调节和控制。", "primary_collocate": null, "pronunciation": "wēn kòng", "ipa": "wən˥ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "与此同时，被动式太阳能设计已见于古代建筑——厚重大理石墙体吸收日间热量，夜间缓慢释放，形成天然温控系统。", "target_word": "温控", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台机器的温控很准。", "target_word": "温控", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冰箱靠温控保持低温。", "target_word": "温控", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "实验室对温控的要求非常高。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的温控能让药品保存得更久。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套房子的温控做得很好，冬天不冷。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温室里的温控出了问题，花都冻坏了。", "target_word": "温控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在调整大楼的温控系统。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古人没有空调，靠厚墙进行温控。", "target_word": "温控", "complexity_tier": "T3", "furigana": "gǔ rén méi yǒu kōng tiáo kào hòu qiáng jìn xíng wēn kòng", "sentence_source": "generated"}, {"text": "这家工厂把车间的温控交给了电脑。", "target_word": "温控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "温控器", "label": "复合"}], "register": "中性", "sense_fingerprint": "对温度的调节和控制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b8958f0-ffe2-4271-bc78-1dc054604ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温控", "is_correct": true, "explanation": "温控：调节温度的动作，与墙体调节日夜温度形成温控系统相符。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体与温度调节无关，“天然字体系统”说不通。"}, {"text": "时尚", "is_correct": false, "explanation": "语义：时尚不是调节温度的手段，无法构成天然系统。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道系统”不搭配“天然”，不能形成调温功能。"}], "explanations": {"温控": "温控：调节温度的动作，与墙体调节日夜温度形成温控系统相符。", "字体": "语义：字体与温度调节无关，“天然字体系统”说不通。", "时尚": "语义：时尚不是调节温度的手段，无法构成天然系统。", "味道": "搭配：“味道系统”不搭配“天然”，不能形成调温功能。"}, "sentence_index": 0, "correct_answer": "温控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的温控很高，我们热得出汗。", "explanation": "这里应该用〈温度〉。温控指调节温度的动作，不能形容温度的高低。"}, {"text": "早晚的温控很大，冷热悬殊。", "explanation": "这里应该用〈温差〉。温差指温度之间的差别，温控是调节的动作，不能说“很大”。"}, {"text": "他的温控很正常，没有发烧。", "explanation": "这里应该用〈体温〉。温控不指人的体温，说人的体温正常要用体温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温控", "is_correct": true, "explanation": "温控：调节温室温度的动作，与“花都冻坏了”的原因相符。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱与温室温度无关，不会导致花被冻坏。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词不能引起温室问题，与冻坏花的结果不相符。"}, {"text": "字幕", "is_correct": false, "explanation": "搭配：“温室里的字幕出了问题”搭配不当，温室里出问题应指温度设备。"}], "explanations": {"温控": "温控：调节温室温度的动作，与“花都冻坏了”的原因相符。", "乐谱": "语义：乐谱与温室温度无关，不会导致花被冻坏。", "歌词": "语义：歌词不能引起温室问题，与冻坏花的结果不相符。", "字幕": "搭配：“温室里的字幕出了问题”搭配不当，温室里出问题应指温度设备。"}, "sentence_index": 6, "correct_answer": "温控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂在车间装了一把温控，效果很好。", "explanation": "量词用错。温控是调节过程，不能用“把”计量，应说“一套温控系统”。"}, {"text": "这家店买了一条温控，用来控制冷气。", "explanation": "量词用错。“条”用于细长的东西，温控不能用“条”计量。"}, {"text": "我家新装了一只温控，冬天很暖和。", "explanation": "量词用错。“只”用于动物，温控不能用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台冰箱的温控吃得很好。", "corrected_sentence": "这台冰箱的温控做得很好。", "error_description": "动词搭配错误：「温控」应搭配「做」，不能说「吃」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂用电脑来管理车间是温控。", "corrected_sentence": "工厂用电脑来管理车间的温控。", "error_description": "“是”应为“的”。修饰语“车间”与“温控”之间要用“的”，应说“车间的温控”，不能用“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
