INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13688, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻新思想或发展可能的最初来源", "primary_collocate": null, "pronunciation": "zhǒng zi", "ipa": "ʈʂʊŋ˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "这些实践虽未形成理论体系，却为后世埋下创新的种子。", "target_word": "种子", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "那次旅行在他心里种下了热爱自然的种子。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书能在孩子心中播下梦想的种子。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次小会议成了后来这场改革的种子。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的鼓励，是他心里希望的种子。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "误会的种子一旦埋下，感情就会出问题。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱的种子需要耐心，才能长大。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把和平的种子带到了每一个国家。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争给这个地方留下了仇恨的种子。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个孩子心里都有一颗好奇的种子。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗种子", "label": "量词（颗）"}, {"form": "一粒种子", "label": "量词（粒）"}], "register": "中性", "sense_fingerprint": "种子-比喻思想、感情或事物发展的最初来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b8958f0-ffe2-4271-bc78-1dc054604ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "种子", "is_correct": true, "explanation": "种子（zhǒng zi）：比喻新思想或发展的最初来源。"}, {"text": "粽子", "is_correct": false, "explanation": "粽子（zòng zi）与种子（zhǒng zi）声母不同（z 与 zh），声调也不同，意思是粽子。"}, {"text": "虫子", "is_correct": false, "explanation": "虫子（chóng zi）与种子（zhǒng zi）声母不同（ch 与 zh），声调也不同，意思是小虫。"}, {"text": "长子", "is_correct": false, "explanation": "长子（zhǎng zi）与种子（zhǒng zi）韵母不同（ang 与 ong），意思是家中的大儿子。"}], "explanations": {"种子": "种子（zhǒng zi）：比喻新思想或发展的最初来源。", "粽子": "粽子（zòng zi）与种子（zhǒng zi）声母不同（z 与 zh），声调也不同，意思是粽子。", "虫子": "虫子（chóng zi）与种子（zhǒng zi）声母不同（ch 与 zh），声调也不同，意思是小虫。", "长子": "长子（zhǎng zi）与种子（zhǒng zi）韵母不同（ang 与 ong），意思是家中的大儿子。"}, "sentence_index": null, "correct_answer": "种子"}, "level_3": {"options": [{"text": "成果", "is_correct": false, "explanation": "搭配：“埋下”后接“种子、伏笔、祸根”一类，不说“埋下成果”，成果应说“取得”。"}, {"text": "种子", "is_correct": true, "explanation": "“埋下创新的种子”指为创新留下最初的来源，符合语境。"}, {"text": "祸根", "is_correct": false, "explanation": "语义：“祸根”指坏事的根源，与“创新”的积极意义相矛盾。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是具体物品，不能作为比喻义的最初来源，埋下玩具也与“创新”的语境不合。"}], "explanations": {"成果": "搭配：“埋下”后接“种子、伏笔、祸根”一类，不说“埋下成果”，成果应说“取得”。", "种子": "“埋下创新的种子”指为创新留下最初的来源，符合语境。", "祸根": "语义：“祸根”指坏事的根源，与“创新”的积极意义相矛盾。", "玩具": "语义：玩具是具体物品，不能作为比喻义的最初来源，埋下玩具也与“创新”的语境不合。"}, "sentence_index": 0, "correct_answer": "种子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的种子很便宜。", "explanation": "这里应该用〈价格〉。种子指事物的最初来源，不能用来说价钱。"}, {"text": "这次调查得出了明确的种子。", "explanation": "这里应该用〈结论〉。“得出”后接结论，种子指最初来源，不能被“得出”。"}, {"text": "这台机器的种子坏了。", "explanation": "这里应该用〈零件〉。种子指事物的最初来源，不能用来指机器的零件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会生长，与“需要耐心，才能长大”不符。"}, {"text": "种子", "is_correct": true, "explanation": "“爱的种子”指爱的萌芽，可以“长大”，符合语境。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不会长大，与“才能长大”相矛盾。"}, {"text": "伤口", "is_correct": false, "explanation": "搭配：“长大”用于生命体，伤口应说“愈合”，不说“长大”。"}], "explanations": {"石头": "语义：石头不会生长，与“需要耐心，才能长大”不符。", "种子": "“爱的种子”指爱的萌芽，可以“长大”，符合语境。", "椅子": "语义：椅子是家具，不会长大，与“才能长大”相矛盾。", "伤口": "搭配：“长大”用于生命体，伤口应说“愈合”，不说“长大”。"}, "sentence_index": 6, "correct_answer": "种子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的种子很晴朗。", "explanation": "这里应该用〈天气〉。种子指事物的最初来源，不能用来形容天气晴朗。"}, {"text": "他跑步的种子很快。", "explanation": "这里应该用〈速度〉。种子指事物的最初来源，不能用来形容快慢。"}, {"text": "他的种子跳得很快。", "explanation": "这里应该用〈心脏〉。种子指比喻义的最初来源，不能作“跳”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小实验，成了后来一系列发明的一只种子。", "corrected_sentence": "这个小实验，成了后来一系列发明的种子。", "error_description": "量词用错。种子的量词应为“颗”或“粒”，“只”多用于动物，不能修饰种子，所以不能说“一只种子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次演讲，在学生心里播了下希望的种子。", "corrected_sentence": "这次演讲，在学生心里播下了希望的种子。", "error_description": "动补结构的“了”位置错误。“播下”是动补结构，“了”应放在“下”之后，应说“播下了”，不能说“播了下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
