INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指公元1900年至1999年之间的时期。", "primary_collocate": null, "pronunciation": "èr shí shì jì", "ipa": "ɚ˥˩ ʂɨ˧˥ ʂɨ˥˩ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "二十世纪的石油危机爆发后，能源安全议题迫使各国重新审视技术路径。", "target_word": "二十世纪", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "二十世纪是一个科学快速发展的时代。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老桥建于二十世纪，已经很旧了。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷是在二十世纪出生的。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十世纪的战争给许多国家带来了痛苦。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史老师说，二十世纪发生了很多大事。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家是二十世纪最有名的诗人之一。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家是在二十世纪搬到北京的。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视机在二十世纪才走进普通人家。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多二十世纪的老照片。", "target_word": "二十世纪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "二十世紀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公元1900至1999年这一百年的历史时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb29fdd9-6bf5-4058-81eb-b0541dac5101') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二十世纪", "is_correct": true, "explanation": "正确：“二十世纪”是时期名词，可修饰“石油危机”，表示危机发生的时代，符合句意。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：“鸡蛋”不是时间，不能修饰“石油危机”。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“上午”是一天中的时段，不能修饰“石油危机”，句意不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能用来表示时代。"}], "explanations": {"二十世纪": "正确：“二十世纪”是时期名词，可修饰“石油危机”，表示危机发生的时代，符合句意。", "鸡蛋": "语义：“鸡蛋”不是时间，不能修饰“石油危机”。", "上午": "搭配：“上午”是一天中的时段，不能修饰“石油危机”，句意不通。", "椅子": "语义：“椅子”是家具，不能用来表示时代。"}, "sentence_index": 0, "correct_answer": "二十世纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现在我们生活在二十世纪。", "explanation": "这里应该用〈二十一世纪〉。说“现在”时身处的是二十一世纪，二十世纪已经过去。"}, {"text": "我们班有三个二十世纪。", "explanation": "这里应该用〈一个时代〉。二十世纪是固定的一个时期，不能用数量词计数。"}, {"text": "二十世纪的人会过得更好。", "explanation": "这里应该用〈下个世纪〉。二十世纪已经过去，不能用来说将来的人会过得怎样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二十世纪", "is_correct": true, "explanation": "正确：“二十世纪”是一个时代，可以修饰“诗人”，符合句意。"}, {"text": "公园", "is_correct": false, "explanation": "语义：“公园”是地点，不能表示时代。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：“西瓜”是水果，不能用来限定诗人的时代。"}, {"text": "体育课", "is_correct": false, "explanation": "搭配：“体育课”不能用来表示诗人活跃的时代，句意不通。"}], "explanations": {"二十世纪": "正确：“二十世纪”是一个时代，可以修饰“诗人”，符合句意。", "公园": "语义：“公园”是地点，不能表示时代。", "西瓜": "语义：“西瓜”是水果，不能用来限定诗人的时代。", "体育课": "搭配：“体育课”不能用来表示诗人活跃的时代，句意不通。"}, "sentence_index": 6, "correct_answer": "二十世纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去了二十世纪旅行。", "explanation": "这里应该用〈北京〉。二十世纪是时期，不是地点，不能说“去了二十世纪”。"}, {"text": "二十世纪是晚上八点。", "explanation": "这里应该用〈现在〉。二十世纪是一段时期，不能表示某个钟点。"}, {"text": "这件二十世纪很有意思。", "explanation": "这里应该用〈这个时代〉。二十世纪是时期，不用“件”计量，应说“这个时代”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家的老房子建在二十世纪初。", "corrected_sentence": "我家的老房子建于二十世纪初。", "error_description": "表示建造于某个时间时应用介词“于”，说“建于二十世纪初”，“建在”用于地点，不能用于时间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些人的父母在二十世纪时候很少出国。", "corrected_sentence": "这些人的父母在二十世纪的时候很少出国。", "error_description": "“二十世纪”修饰“时候”时中间应加“的”，说“二十世纪的时候”，不能说“二十世纪时候”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
