INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13693, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "石油危机指全球或地区因石油供应不足、价格暴涨等原因引发的经济动荡或社会问题。", "primary_collocate": null, "pronunciation": "shí yóu wēi jī", "ipa": "ʂɨ˧˥ iou̯˧˥ weɪ̯˥ tɕi˥", "syllable_count": 4, "sentences": [{"text": "直至二十世纪七十年代石油危机爆发，能源安全议题迫使各国重新审视技术路径。", "target_word": "石油危机", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "石油危机让汽油的价格涨了很多。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一九七三年的石油危机影响了全世界。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油危机时，很多国家都开始节约能源。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了那次石油危机的故事。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为石油危机，许多工厂不得不停工。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家说，石油危机会使物价上涨。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次石油危机过后，人们更重视节能了。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油危机发生时，加油站前排着长长的队。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，石油危机那年，他才十岁。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "石油危機", "label": "繁体"}, {"form": "次", "label": "量词"}], "register": "中性", "sense_fingerprint": "石油供应不足或价格暴涨引发的经济社会动荡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb29fdd9-6bf5-4058-81eb-b0541dac5101') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石油危机", "is_correct": true, "explanation": "正确：石油危机是指事件的名词，可以作“爆发”的主语，符合“直至七十年代……爆发”的语境。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：粮食是食物，不是突发的事件，不会“爆发”。"}, {"text": "物价", "is_correct": false, "explanation": "搭配：物价只说“上涨”或“飙升”，不说“爆发”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是事件，不能作“爆发”的主语。"}], "explanations": {"石油危机": "正确：石油危机是指事件的名词，可以作“爆发”的主语，符合“直至七十年代……爆发”的语境。", "粮食": "语义：粮食是食物，不是突发的事件，不会“爆发”。", "物价": "搭配：物价只说“上涨”或“飙升”，不说“爆发”。", "课本": "语义：课本是书，不是事件，不能作“爆发”的主语。"}, "sentence_index": 0, "correct_answer": "石油危机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都喝石油危机。", "explanation": "这里应该用〈咖啡〉。“喝”的对象是饮料，危机是事件，不能喝；早上喝的是咖啡。"}, {"text": "这个月石油危机涨了很多。", "explanation": "这里应该用〈油价〉。“石油危机”指危机事件，不能说“涨”；油价上涨才这样说。"}, {"text": "石油危机都很赚钱。", "explanation": "这里应该用〈石油公司〉。危机是事件，不会赚钱；赚钱的是石油公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石油危机", "is_correct": true, "explanation": "正确：石油危机是能引起物价变化的事件，可以作“使物价上涨”的施事。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是学习的场所，不会使物价上涨。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不是经济因素，不能使物价上涨。"}, {"text": "运动会", "is_correct": false, "explanation": "配价：“使物价上涨”需要能影响价格的施事，运动会不能充当这样的施事。"}], "explanations": {"石油危机": "正确：石油危机是能引起物价变化的事件，可以作“使物价上涨”的施事。", "教室": "语义：教室是学习的场所，不会使物价上涨。", "小说": "语义：小说是文学作品，不是经济因素，不能使物价上涨。", "运动会": "配价：“使物价上涨”需要能影响价格的施事，运动会不能充当这样的施事。"}, "sentence_index": 6, "correct_answer": "石油危机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "石油危机前排着长长的队。", "explanation": "这里应该用〈加油站〉。“石油危机”是事件，不能作为排队的地点；排队的是人，地点应是加油站。"}, {"text": "石油危机的产量增加了很多。", "explanation": "这里应该用〈原油〉。“石油危机”不是石油，不能说有“产量”。"}, {"text": "石油危机在海上航行。", "explanation": "这里应该用〈油轮〉。危机不会航行，在海上航行的是油轮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们经历了过石油危机。", "corrected_sentence": "我们经历过石油危机。", "error_description": "体标错误：“过”表示经历过，不能和“了”同时用在“经历”后面。正确形式是“我们经历过石油危机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷亲身经历过过石油危机。", "corrected_sentence": "爷爷亲身经历过石油危机。", "error_description": "体标重复：“经历过”的“过”只用一次，多加的一个“过”是错误的。正确形式是“爷爷亲身经历过石油危机。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
