INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13695, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13695, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能源安全指一个国家或地区能够稳定、可靠地获得所需能源，并且价格合理，不会因为供应中断或价格波动而影响正常生活和经济活动。", "primary_collocate": null, "pronunciation": "néng yuán ān quán", "ipa": "nɤŋ˧˥ ɥɛn˧˥ an˥ tɕʰɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "直至二十世纪七十年代石油危机爆发，能源安全议题迫使各国重新审视技术路径。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "各国都很重视能源安全。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能源安全关系到每个人的生活。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有能源安全，工厂就没有电用。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府一直在努力保障能源安全。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的能源安全受到了威胁。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发展太阳能有助于能源安全。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家今天谈了能源安全的问题。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能源安全对经济发展很重要。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天天气冷，大家更关心能源安全。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国家能源安全", "label": "复合"}], "register": "正式", "sense_fingerprint": "国家或地区稳定、可靠、价格合理地获得所需能源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1cec68-d878-4094-9209-243e8af8fb55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13695, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粮食安全", "is_correct": false, "explanation": "语义：前文讲的是石油危机引发的能源问题，“粮食安全”指食物供应，与语境不符。"}, {"text": "能源安全", "is_correct": true, "explanation": "能源安全：指国家稳定、可靠地获得能源，与石油危机引发的供应问题相符。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影与石油危机和技术路径无关，“电影议题”不能迫使各国重新审视技术路径。"}, {"text": "人口老龄化", "is_correct": false, "explanation": "语义：“人口老龄化”与石油危机无关，不能迫使各国重新审视技术路径。"}], "explanations": {"粮食安全": "语义：前文讲的是石油危机引发的能源问题，“粮食安全”指食物供应，与语境不符。", "能源安全": "能源安全：指国家稳定、可靠地获得能源，与石油危机引发的供应问题相符。", "电影": "语义：电影与石油危机和技术路径无关，“电影议题”不能迫使各国重新审视技术路径。", "人口老龄化": "语义：“人口老龄化”与石油危机无关，不能迫使各国重新审视技术路径。"}, "sentence_index": 0, "correct_answer": "能源安全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们国家的能源安全很丰富。", "explanation": "这里应该用〈资源〉。“丰富”描述资源多，能源安全指稳定获得能源的状态，不能用“丰富”来说它。"}, {"text": "到了冬天，城市遇到了能源安全。", "explanation": "这里应该用〈能源危机〉。能源安全是稳定供应的状态，不指已经发生的危机事件，不能说“遇到”。"}, {"text": "这个国家有大量的能源安全。", "explanation": "这里应该用〈能源储备〉。能源安全是状态，不能说“大量”；储存的能源才能用“大量”描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13695, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语言学习", "is_correct": false, "explanation": "语义：太阳能与语言学习无关，“有助于”后应接与能源相关的目标。"}, {"text": "能源", "is_correct": false, "explanation": "语义：“能源”是“能源安全”的截取，“有助于能源”语义残缺，应为“能源安全”。"}, {"text": "能源安全", "is_correct": true, "explanation": "能源安全：发展太阳能对国家稳定、可靠地获得能源有帮助，符合语境。"}, {"text": "交通堵塞", "is_correct": false, "explanation": "语义：“有助于”后接的应是积极目标，“交通堵塞”是负面现象，与发展太阳能的目的相反。"}], "explanations": {"语言学习": "语义：太阳能与语言学习无关，“有助于”后应接与能源相关的目标。", "能源": "语义：“能源”是“能源安全”的截取，“有助于能源”语义残缺，应为“能源安全”。", "能源安全": "能源安全：发展太阳能对国家稳定、可靠地获得能源有帮助，符合语境。", "交通堵塞": "语义：“有助于”后接的应是积极目标，“交通堵塞”是负面现象，与发展太阳能的目的相反。"}, "sentence_index": 6, "correct_answer": "能源安全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们需要一只能源安全来保护工厂。", "explanation": "这里应该用〈个〉。“只”是动物量词，不能用来计量“能源安全”这样的抽象概念。"}, {"text": "我们需要一块能源安全来保护工厂。", "explanation": "这里应该用〈个〉。“块”用于成块的实物，不能用来计量“能源安全”。"}, {"text": "我们需要一条能源安全来保护工厂。", "explanation": "这里应该用〈个〉。“条”用于细长的物件，不能用来计量“能源安全”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13695, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年，能源安全了很稳定。", "corrected_sentence": "这几年，能源安全很稳定。", "error_description": "错误形式是在名词“能源安全”后多加了“了”，写作“能源安全了很稳定”；正确形式是“能源安全很稳定”。形容词作谓语时，“了”不能紧跟在作主语的名词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13695, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们很关心这只能源安全。", "corrected_sentence": "我们很关心这种能源安全。", "error_description": "“这只”中的“只”是动物量词，不能计量抽象的“能源安全”；应为“这种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
