INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "导电能力介于导体和绝缘体之间的材料，如硅、锗等。", "primary_collocate": null, "pronunciation": "bàn dǎo tǐ", "ipa": "pan˥˩ taʊ˨˩˦ tʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "此时，半导体物理学的成熟为能源转型提供了关键支点。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "硅是一种常见的半导体。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里有很多半导体。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门生产半导体。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半导体的导电能力介于导体和绝缘体之间。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在半导体公司工作。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑芯片是用半导体做的。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半导体行业最近发展得很快。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上很多国家都在发展半导体。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种半导体材料很便宜。", "target_word": "半导体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "半導體", "label": "繁体"}, {"form": "半导体材料", "label": "复合"}, {"form": "半导体行业", "label": "复合"}], "register": "中性", "sense_fingerprint": "导电能力介于导体与绝缘体之间的材料，如硅、锗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1cec68-d878-4094-9209-243e8af8fb55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美术", "is_correct": false, "explanation": "语义：“美术”不是物理学的分支，“美术物理学”不成立，与“物理学的成熟”的语境相悖。"}, {"text": "体育", "is_correct": false, "explanation": "语义：“体育”与物理学无关，不能修饰“物理学”。"}, {"text": "半导体", "is_correct": true, "explanation": "半导体：导电能力介于导体与绝缘体之间的材料，可以作为“半导体物理学”的研究对象。"}, {"text": "食品", "is_correct": false, "explanation": "搭配：“食品”不是物理学的分支，“食品物理学”不成立，与“物理学的成熟”的语境不符。"}], "explanations": {"美术": "语义：“美术”不是物理学的分支，“美术物理学”不成立，与“物理学的成熟”的语境相悖。", "体育": "语义：“体育”与物理学无关，不能修饰“物理学”。", "半导体": "半导体：导电能力介于导体与绝缘体之间的材料，可以作为“半导体物理学”的研究对象。", "食品": "搭配：“食品”不是物理学的分支，“食品物理学”不成立，与“物理学的成熟”的语境不符。"}, "sentence_index": 0, "correct_answer": "半导体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根电线的内芯是用半导体做的，用来输送大电流。", "explanation": "这里应该用〈导体〉。输送大电流需要导电能力强的导体，半导体导电能力弱，不适合作输电的内芯。"}, {"text": "这把刀是用半导体做的。", "explanation": "这里应该用〈金属〉。刀需要良好的机械强度与导电或加工性能，半导体不是刀具常用的金属材料。"}, {"text": "这个灯泡的灯丝是用半导体做的，通电后会发光。", "explanation": "这里应该用〈钨〉。灯丝需要耐高温、导电性好的金属，半导体不能用作灯丝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木头", "is_correct": false, "explanation": "语义：木头是绝缘材料，不能用来做电脑芯片。"}, {"text": "面粉", "is_correct": false, "explanation": "搭配：“做的”用于食物时才搭配“面粉”，“电脑芯片”不是食物。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建筑材料，与电脑芯片的制造无关。"}, {"text": "半导体", "is_correct": true, "explanation": "半导体：电脑芯片以半导体材料制成，符合语境。"}], "explanations": {"木头": "语义：木头是绝缘材料，不能用来做电脑芯片。", "面粉": "搭配：“做的”用于食物时才搭配“面粉”，“电脑芯片”不是食物。", "水泥": "语义：水泥是建筑材料，与电脑芯片的制造无关。", "半导体": "半导体：电脑芯片以半导体材料制成，符合语境。"}, "sentence_index": 6, "correct_answer": "半导体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只半导体很便宜。", "explanation": "这里应该用〈种〉。“只”是动物量词，不能用来计量“半导体”。"}, {"text": "这头半导体很便宜。", "explanation": "这里应该用〈种〉。“头”用于牲畜，不能用来计量“半导体”。"}, {"text": "这条半导体很便宜。", "explanation": "这里应该用〈种〉。“条”用于细长的物件，不能用来计量“半导体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种半导体了很稳定。", "corrected_sentence": "这种半导体很稳定。", "error_description": "错误形式是在名词“半导体”后多加了“了”，写作“半导体了很稳定”；正确形式是“半导体很稳定”。形容词作谓语时，“了”不能紧跟在作主语的名词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一只半导体，用来修电脑。", "corrected_sentence": "我买了一块半导体，用来修电脑。", "error_description": "“只”是动物量词，不能用来计量“半导体”；应为“块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
