INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13697, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "光子是光的基本粒子，没有质量，以光速运动，是电磁辐射的量子。", "primary_collocate": null, "pronunciation": "guāng zǐ", "ipa": "kuaŋ˥ tsɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "光伏效应——光子撞击硅晶材料释放电子形成电流——从实验室现象蜕变为发电技术。", "target_word": "光子", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "光子是光的最小单位。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳发出的光由很多光子组成。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光子跑得非常快。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用仪器测量光子。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个光子的能量很小。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光子没有质量。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能电池吸收光子后产生电。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光里的光子方向一致。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光子撞到物体，会把能量传给它。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "光子能量", "label": "复合"}], "register": "中性", "sense_fingerprint": "光和电磁辐射的基本粒子，无质量，以光速运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1cec68-d878-4094-9209-243e8af8fb55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13697, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "光子", "is_correct": true, "explanation": "光子 guāng zǐ 指光的基本粒子，是本题的正确答案。"}, {"text": "公子", "is_correct": false, "explanation": "公子 gōng zǐ 与 guāng zǐ 韵母不同（ong 与 ang），意思是贵族子弟。"}, {"text": "筐子", "is_correct": false, "explanation": "筐子 kuāng zi 与 guāng 声母不同（k 与 g），意思是箩筐。"}, {"text": "框子", "is_correct": false, "explanation": "框子 kuàng zi 与 guāng 声母不同（k 与 g），声调也不同（去声），意思是框架。"}, {"text": "管子", "is_correct": false, "explanation": "管子 guǎn zi 与 guāng zǐ 韵母不同（an 与 ang），声调也不同，意思是管道。"}], "explanations": {"光子": "光子 guāng zǐ 指光的基本粒子，是本题的正确答案。", "公子": "公子 gōng zǐ 与 guāng zǐ 韵母不同（ong 与 ang），意思是贵族子弟。", "筐子": "筐子 kuāng zi 与 guāng 声母不同（k 与 g），意思是箩筐。", "框子": "框子 kuàng zi 与 guāng 声母不同（k 与 g），声调也不同（去声），意思是框架。", "管子": "管子 guǎn zi 与 guāng zǐ 韵母不同（an 与 ang），声调也不同，意思是管道。"}, "sentence_index": null, "correct_answer": "光子"}, "level_3": {"options": [{"text": "光子", "is_correct": true, "explanation": "光伏效应中撞击硅晶材料、释放电子的是光的基本粒子，只有光子符合。"}, {"text": "电流", "is_correct": false, "explanation": "语义：句中“形成电流”是撞击之后的结果，电流不会去撞击硅晶材料。"}, {"text": "发电机", "is_correct": false, "explanation": "搭配：“撞击硅晶材料”需要粒子作主语，发电机是设备，不能这样搭配。"}, {"text": "实验室", "is_correct": false, "explanation": "语义：实验室是场所，不是撞击材料的粒子，而且句中已用“实验室现象”指代场所。"}], "explanations": {"光子": "光伏效应中撞击硅晶材料、释放电子的是光的基本粒子，只有光子符合。", "电流": "语义：句中“形成电流”是撞击之后的结果，电流不会去撞击硅晶材料。", "发电机": "搭配：“撞击硅晶材料”需要粒子作主语，发电机是设备，不能这样搭配。", "实验室": "语义：实验室是场所，不是撞击材料的粒子，而且句中已用“实验室现象”指代场所。"}, "sentence_index": 0, "correct_answer": "光子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喝了一杯光子，味道很甜。", "explanation": "这里应该用〈果汁〉。光子是看不见的粒子，不能像饮料一样喝。"}, {"text": "屋里飞进来一只光子。", "explanation": "这里应该用〈个〉。光子是粒子，不是动物，量词“只”不能用于光子。"}, {"text": "太阳是一个很大的光子。", "explanation": "这里应该用〈光源〉。光子是极小的粒子，太阳这类发光体要说光源，不能说光子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光子", "is_correct": true, "explanation": "光子是光的基本粒子，静止质量为零，所以说“没有质量”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头有质量，与“没有质量”矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车有明显的质量，句子说它没有质量，与常识冲突。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“没有质量”说的是基本粒子，水是物质，不能这样搭配。"}], "explanations": {"光子": "光子是光的基本粒子，静止质量为零，所以说“没有质量”。", "石头": "语义：石头有质量，与“没有质量”矛盾。", "汽车": "语义：汽车有明显的质量，句子说它没有质量，与常识冲突。", "水": "搭配：“没有质量”说的是基本粒子，水是物质，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "光子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树上结满了光子。", "explanation": "这里应该用〈果实〉。光子是粒子，不能像果实那样挂在树上。"}, {"text": "妈妈去市场买了一斤光子。", "explanation": "这里应该用〈青菜〉。光子是看不见的粒子，不是可以按斤买卖的食物。"}, {"text": "我的光子比小明高一头。", "explanation": "这里应该用〈个子〉。光子不是人，不能用来描述身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个实验用来观察一只光子的运动。", "corrected_sentence": "这个实验用来观察一个光子的运动。", "error_description": "量词错误：光子是粒子，应说“一个光子”，不能说“一只光子”（“只”多用于动物或成对物品中的一件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这束光里的光子跑地很快。", "corrected_sentence": "这束光里的光子跑得很快。", "error_description": "助词错误：程度补语应用“得”，不能用“地”（“地”用于状语），应说“跑得很快”，不能说“跑地很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
