INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "运动物体与另一物体猛然相碰。", "primary_collocate": null, "pronunciation": "zhuàng jī", "ipa": "ʈʂwɑŋ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "光伏效应——光子撞击硅晶材料释放电子形成电流——从实验室现象蜕变为发电技术。", "target_word": "撞击", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "海浪不停地撞击着岩石。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车撞击护栏后停了下来。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小石头撞击玻璃，发出很大的声音。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两艘船在雾中互相撞击，船身都坏了。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔倒时头部撞击到了地面。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陨石撞击地球，会留下很大的坑。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点撞击窗户，发出噼里啪啦的响声。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，门不停地撞击着墙壁。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一块石头从山上滚下来，撞击了车顶。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撞击了", "label": "体标（了）"}, {"form": "撞击着", "label": "体标（着）"}, {"form": "撞击过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "运动的物体猛然撞上另一物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: 噼 (Zipf 1.82)']::text[], 'dc1cec68-d878-4094-9209-243e8af8fb55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撞击", "is_correct": true, "explanation": "撞击指光子猛烈地冲击硅晶材料，与“释放电子”的物理过程相合。"}, {"text": "吸收", "is_correct": false, "explanation": "配价：“吸收”的宾语应是光子，这里说“光子吸收硅晶材料”，方向颠倒。"}, {"text": "抚摸", "is_correct": false, "explanation": "语义：抚摸是轻柔的动作，与光子击打材料并释放电子的过程不符。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“硅晶材料”作宾语。"}], "explanations": {"撞击": "撞击指光子猛烈地冲击硅晶材料，与“释放电子”的物理过程相合。", "吸收": "配价：“吸收”的宾语应是光子，这里说“光子吸收硅晶材料”，方向颠倒。", "抚摸": "语义：抚摸是轻柔的动作，与光子击打材料并释放电子的过程不符。", "游泳": "配价：“游泳”是不及物动词，不能带“硅晶材料”作宾语。"}, "sentence_index": 0, "correct_answer": "撞击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春风轻轻撞击着柳树，柳条慢慢摆动。", "explanation": "这里应该用〈拂〉。撞击强调猛烈相碰，轻柔的春风应该用拂。"}, {"text": "老师在黑板上撞击了今天的作业。", "explanation": "这里应该用〈写〉。撞击的是硬物相碰，布置作业要用写。"}, {"text": "妈妈轻轻撞击了宝宝的脸，宝宝笑了起来。", "explanation": "这里应该用〈亲〉。撞击力度太猛，对宝宝的温柔动作要用亲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撞击", "is_correct": true, "explanation": "撞击指陨石猛烈地撞上地球表面，与留下大坑的结果相合。"}, {"text": "照射", "is_correct": false, "explanation": "语义：照射是光线的作用，陨石不会照射地球，也不会因此留下大坑。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”多用于水和植物，不能用于陨石撞击地球。"}, {"text": "发射", "is_correct": false, "explanation": "配价：“发射”需要发射者和射向，陨石不能发射地球。"}], "explanations": {"撞击": "撞击指陨石猛烈地撞上地球表面，与留下大坑的结果相合。", "照射": "语义：照射是光线的作用，陨石不会照射地球，也不会因此留下大坑。", "浇灌": "搭配：“浇灌”多用于水和植物，不能用于陨石撞击地球。", "发射": "配价：“发射”需要发射者和射向，陨石不能发射地球。"}, "sentence_index": 6, "correct_answer": "撞击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在路上撞击了老同学，两人高兴地聊了起来。", "explanation": "这里应该用〈撞见〉。撞击指猛烈相碰，偶遇熟人要用撞见。"}, {"text": "妈妈用火撞击汤，汤很快就熟了。", "explanation": "这里应该用〈煮〉。撞击不能用来加热食物，煮汤要用煮。"}, {"text": "我们在电影院撞击了两个小时。", "explanation": "这里应该用〈看〉。撞击指猛烈相碰，看电影要用看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公交车猛烈得撞击了路边的护栏。", "corrected_sentence": "公交车猛烈地撞击了路边的护栏。", "error_description": "状语助词错误：修饰动词的状语应用“地”，不能用“得”（“得”用于补语），应说“猛烈地撞击”，不能说“猛烈得撞击”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这颗陨石了撞击着地面，留下很大的坑。", "corrected_sentence": "这颗陨石撞击着地面，留下很大的坑。", "error_description": "体标错误：“了”误加在动词“撞击”之前，应删去，正确说法是“这颗陨石撞击着地面”，不能说“这颗陨石了撞击着地面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
