INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13699, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "硅晶是硅元素形成的晶体，具有规则的结构和良好的导电性，常用于制造电子元件。", "primary_collocate": null, "pronunciation": "guī jīng", "ipa": "kwei˥ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "光伏效应——光子撞击硅晶材料释放电子形成电流——从实验室现象蜕变为发电技术。", "target_word": "硅晶", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂用硅晶制造电子元件。", "target_word": "硅晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硅晶的结构很规则，导电性也很好。", "target_word": "硅晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能电池板的主要材料是硅晶。", "target_word": "硅晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把硅晶切成很薄的片。", "target_word": "硅晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司每年生产大量的硅晶。", "target_word": "硅晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里放着一块闪闪发光的硅晶。", "target_word": "硅晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的芯片是用硅晶做的。", "target_word": "硅晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硅晶价格上涨，电池的成本也提高了。", "target_word": "硅晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究更纯的硅晶。", "target_word": "硅晶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块硅晶", "label": "量词（块）"}], "register": "中性", "sense_fingerprint": "由硅元素形成、结构规则、可导电的晶体材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1cec68-d878-4094-9209-243e8af8fb55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13699, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "硅晶", "is_correct": true, "explanation": "正确：句中指光伏发电所用的半导体材料，与“光伏效应”“释放电子”相符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是绝缘体，光子撞击后不会释放电子形成电流，与“光伏效应”不合。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料同样是绝缘材料，无法产生光伏效应，与句中的科学语境不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是光伏半导体材料，光子撞击后不会释放电子形成电流，与句意不合。"}], "explanations": {"硅晶": "正确：句中指光伏发电所用的半导体材料，与“光伏效应”“释放电子”相符。", "玻璃": "语义：玻璃是绝缘体，光子撞击后不会释放电子形成电流，与“光伏效应”不合。", "塑料": "语义：塑料同样是绝缘材料，无法产生光伏效应，与句中的科学语境不合。", "石头": "语义：石头不是光伏半导体材料，光子撞击后不会释放电子形成电流，与句意不合。"}, "sentence_index": 0, "correct_answer": "硅晶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她戴着一条硅晶项链，很漂亮。", "explanation": "这里应该用〈水晶〉。硅晶是工业用的半导体材料，首饰用的透明晶体要说水晶。"}, {"text": "这个杯盖是用硅晶做的，又软又耐热。", "explanation": "这里应该用〈硅胶〉。硅晶质地硬而脆，不能做柔软耐热的杯盖；柔软耐热的材料说硅胶。"}, {"text": "工厂里放着一本硅晶。", "explanation": "这里应该用〈块〉。量词“本”用于书册，硅晶是块状材料，应说“一块硅晶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13699, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硅晶", "is_correct": true, "explanation": "正确：与“一块”“闪闪发光”相符，指实验室中展示的硅晶材料。"}, {"text": "木头", "is_correct": false, "explanation": "体貌：木头不会闪闪发光，与句中的“闪闪发光”矛盾。"}, {"text": "泥土", "is_correct": false, "explanation": "体貌：泥土灰暗无光，与“闪闪发光”不合。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不会作为闪闪发光的样品放在实验室里，句义不合。"}], "explanations": {"硅晶": "正确：与“一块”“闪闪发光”相符，指实验室中展示的硅晶材料。", "木头": "体貌：木头不会闪闪发光，与句中的“闪闪发光”矛盾。", "泥土": "体貌：泥土灰暗无光，与“闪闪发光”不合。", "面包": "语义：面包是食物，不会作为闪闪发光的样品放在实验室里，句义不合。"}, "sentence_index": 6, "correct_answer": "硅晶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个花瓶是硅晶做的，很好看。", "explanation": "这里应该用〈陶瓷〉。硅晶是制造电子元件的材料，花瓶这类日用器皿要用陶瓷。"}, {"text": "他买了一台硅晶。", "explanation": "这里应该用〈块〉。“台”用于机器、设备，硅晶是块状材料，应说“一块硅晶”。"}, {"text": "这扇窗户是硅晶做的，很透明。", "explanation": "这里应该用〈玻璃〉。硅晶是半导体材料，窗户要用玻璃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13699, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人从箱子里拿出一张硅晶。", "corrected_sentence": "工人从箱子里拿出一块硅晶。", "error_description": "量词错误：“张”用于纸张、桌子等扁平物，硅晶是块状材料，应说“一块硅晶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13699, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些芯片是用两硅晶做的。", "corrected_sentence": "这些芯片是用两块硅晶做的。", "error_description": "量词漏掉：数词“两”后要加量词“块”，应说“两块硅晶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
