INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13700, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电子是原子中带负电的粒子，围绕原子核运动，是电流的基本载体。", "primary_collocate": null, "pronunciation": "diàn zǐ", "ipa": "tjɛn˥˩ tsɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "电子围绕原子核不停地运动。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子带负电，质子带正电。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属里的电子可以自由移动。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电流是电子流动形成的。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个原子失去电子，就会带正电。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用仪器观察电子的运动。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子比原子核小得多。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导线里有很多电子在移动。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原子里有质子、中子和电子。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯亮了，是因为电子在导线里流动。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个电子", "label": "量词（个）"}, {"form": "電子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "原子中带负电、围绕原子核运动的粒子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1cec68-d878-4094-9209-243e8af8fb55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13700, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电子", "is_correct": true, "explanation": "正确：电子（diàn zǐ），指原子中带负电的粒子。"}, {"text": "点子", "is_correct": false, "explanation": "diǎn（第三声）与 diàn（第四声）声调不同，“点子”意思是主意。"}, {"text": "链子", "is_correct": false, "explanation": "liàn 与 diàn 声母不同（l 与 d），“链子”意思是链条。"}, {"text": "辫子", "is_correct": false, "explanation": "biàn 与 diàn 声母不同（b 与 d），“辫子”意思是编起来的头发。"}, {"text": "片子", "is_correct": false, "explanation": "piàn 与 diàn 声母不同（p 与 d），“片子”意思是影片或片状的东西。"}, {"text": "面子", "is_correct": false, "explanation": "miàn 与 diàn 声母不同（m 与 d），“面子”意思是颜面。"}], "explanations": {"电子": "正确：电子（diàn zǐ），指原子中带负电的粒子。", "点子": "diǎn（第三声）与 diàn（第四声）声调不同，“点子”意思是主意。", "链子": "liàn 与 diàn 声母不同（l 与 d），“链子”意思是链条。", "辫子": "biàn 与 diàn 声母不同（b 与 d），“辫子”意思是编起来的头发。", "片子": "piàn 与 diàn 声母不同（p 与 d），“片子”意思是影片或片状的东西。", "面子": "miàn 与 diàn 声母不同（m 与 d），“面子”意思是颜面。"}, "sentence_index": null, "correct_answer": "电子"}, "level_3": {"options": [{"text": "电子", "is_correct": true, "explanation": "正确：电子是绕原子核运动的粒子，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是静止的物体，不会围绕原子核不停地运动。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会围绕原子核运动，与句中的微观语境不合。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“河流”不能与“围绕原子核”搭配，句中的运动主体应是粒子。"}], "explanations": {"电子": "正确：电子是绕原子核运动的粒子，与句意相符。", "石头": "语义：石头是静止的物体，不会围绕原子核不停地运动。", "桌子": "语义：桌子是家具，不会围绕原子核运动，与句中的微观语境不合。", "河流": "搭配：“河流”不能与“围绕原子核”搭配，句中的运动主体应是粒子。"}, "sentence_index": 0, "correct_answer": "电子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电子升高，电流就变大了。", "explanation": "这里应该用〈电压〉。升高的是电压，电子是原子里的粒子，不说“电子升高”。"}, {"text": "电池两端的电压会形成电子。", "explanation": "这里应该用〈电流〉。电压“形成”的是电流，电子是粒子，不说“形成电子”。"}, {"text": "这个氢原子里有一只电子。", "explanation": "这里应该用〈个〉。量词“只”用于动物和成对的器物，电子应说“一个电子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电子", "is_correct": true, "explanation": "正确：电子比原子核小得多，与句意相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳远比原子核大，不能说它比原子核小得多。"}, {"text": "地球", "is_correct": false, "explanation": "语义：地球体积远大于原子核，句意不合。"}, {"text": "云", "is_correct": false, "explanation": "体貌：云是大团的水汽，体积远大于原子核，与“小得多”矛盾。"}], "explanations": {"电子": "正确：电子比原子核小得多，与句意相符。", "太阳": "语义：太阳远比原子核大，不能说它比原子核小得多。", "地球": "语义：地球体积远大于原子核，句意不合。", "云": "体貌：云是大团的水汽，体积远大于原子核，与“小得多”矛盾。"}, "sentence_index": 6, "correct_answer": "电子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "导线两端加上电子，灯就亮了。", "explanation": "这里应该用〈电压〉。电子是粒子，不能加在导线两端，加上的是电压。"}, {"text": "这个开关一按，电子就接通了，灯亮了。", "explanation": "这里应该用〈电路〉。开关接通的是电路，电子是粒子，不能被接通。"}, {"text": "电线是用电子做的，导电很好。", "explanation": "这里应该用〈铜〉。电子不是制作电线的材料，电线用铜或铝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个原子里有三块电子。", "corrected_sentence": "这个原子里有三个电子。", "error_description": "量词错误：电子是粒子，应用量词“个”，“块”用于块状物，不能用于电子，应说“三个电子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电池里有两电子在跑。", "corrected_sentence": "电池里有两个电子在跑。", "error_description": "量词漏掉：数词“两”后要加量词“个”，应说“两个电子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13701, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13701, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13701, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电流是指电荷在导体中定向移动形成的物理现象，通常用安培作为单位。", "primary_collocate": null, "pronunciation": "diàn liú", "ipa": "tjɛn˥˩ ljou˧˥", "syllable_count": 2, "sentences": [{"text": "光伏效应——光子撞击硅晶材料释放电子形成电流——从实验室现象蜕变为发电技术。", "target_word": "电流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "电流通过灯泡，灯泡就亮了。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电流的单位是安培。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导线太细，电流太大会发热。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池能让电路里产生电流。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，他用仪器测量了电流的大小。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电流从电池的正极流向负极。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电阻越大，电流就越小。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铜线能让电流顺利通过。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电流太强，会伤害人体。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}, {"form": "电流表", "label": "复合"}], "register": "中性", "sense_fingerprint": "电荷定向移动形成的物理量，单位安培", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e92c63b-3679-442a-a17d-628878172573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13701, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电流", "is_correct": true, "explanation": "正确：电子定向移动形成的是电流，符合光伏发电的物理过程。"}, {"text": "云彩", "is_correct": false, "explanation": "语义：释放的电子不会形成云彩，与光伏发电的物理过程不符。"}, {"text": "霞光", "is_correct": false, "explanation": "语域：“霞光”是文学用语，不适合物理说明文，且与发电过程不符。"}, {"text": "泡沫", "is_correct": false, "explanation": "语义：电子不会形成泡沫，句意与硅晶发电的过程不符。"}], "explanations": {"电流": "正确：电子定向移动形成的是电流，符合光伏发电的物理过程。", "云彩": "语义：释放的电子不会形成云彩，与光伏发电的物理过程不符。", "霞光": "语域：“霞光”是文学用语，不适合物理说明文，且与发电过程不符。", "泡沫": "语义：电子不会形成泡沫，句意与硅晶发电的过程不符。"}, "sentence_index": 0, "correct_answer": "电流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个插座的电流是220伏。", "explanation": "这里应该用〈电压〉。电压的单位是伏特，电流的单位是安培，两者不能互换。"}, {"text": "屋里的电流老化了，得换一下。", "explanation": "这里应该用〈电线〉。电线是导线，会老化；电流是电荷的定向移动，不会老化。"}, {"text": "手机的电流只剩百分之十了。", "explanation": "这里应该用〈电量〉。电量指电池存电的多少，电流是电荷的定向移动，不能说“电流只剩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13701, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电流", "is_correct": true, "explanation": "正确：电流从电池的正极流向负极，符合电路的描述。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水不会从电池的正极流出，句意不通。"}, {"text": "人群", "is_correct": false, "explanation": "语义：人群不会从电池的正极流向负极，与电学描述不符。"}, {"text": "血液", "is_correct": false, "explanation": "搭配：“正极、负极”是电学术语，只能与电荷、电流搭配，不能与血液搭配。"}], "explanations": {"电流": "正确：电流从电池的正极流向负极，符合电路的描述。", "河水": "语义：河水不会从电池的正极流出，句意不通。", "人群": "语义：人群不会从电池的正极流向负极，与电学描述不符。", "血液": "搭配：“正极、负极”是电学术语，只能与电荷、电流搭配，不能与血液搭配。"}, "sentence_index": 6, "correct_answer": "电流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段电流里装了一个开关。", "explanation": "这里应该用〈电路〉。电路是由导线和元件组成的通路，可以装开关；电流是电荷的移动，不能装开关。"}, {"text": "电流已经接好了，可以通电了。", "explanation": "这里应该用〈线路〉。线路可以接好；电流是电荷的定向移动，不能被接好。"}, {"text": "这台电器每小时耗了三度电流。", "explanation": "这里应该用〈电能〉。“度”是电能的单位，电流的单位是安培，不能用“度”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根导线里通过了一条电流。", "corrected_sentence": "这根导线里通过了一股电流。", "error_description": "量词错误：“电流”应搭配量词“股”，“条”用于细长的东西，不能修饰“电流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电池接通后，产生了很大地电流。", "corrected_sentence": "电池接通后，产生了很大的电流。", "error_description": "结构助词错误：“很大”修饰名词“电流”时要用“的”，应说“很大的电流”；“地”用于修饰动词，不能用在名词前，不能说“很大地电流”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
