INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13702, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "晶体是原子、离子或分子在空间按一定规律周期性排列的固体。", "primary_collocate": null, "pronunciation": "jīng tǐ", "ipa": "tɕiŋ˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "第一代晶体硅太阳能电池虽转化效率不足15%，却证明了光能直接转化为电能的可行性。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "盐是一种常见的晶体。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晶体里的原子排得很整齐。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究这种晶体的结构。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰和盐一样，都是晶体。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃不是晶体，它的原子排得不整齐。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晶体有固定的熔点。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有一块很大的晶体。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石英是一种天然晶体。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用显微镜给我们看晶体的形状。", "target_word": "晶体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晶體", "label": "繁体"}, {"form": "晶体管", "label": "复合"}, {"form": "单晶体", "label": "复合"}, {"form": "块", "label": "量词"}], "register": "书面", "sense_fingerprint": "晶体|固体|原子规律排列", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92b8e895-07d2-430a-a35a-f19f0da65d06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晶体", "is_correct": true, "explanation": "「晶体硅」指原子有规则排列的硅材料，与句中「第一代晶体硅」的用法一致。"}, {"text": "非晶体", "is_correct": false, "explanation": "语义：「第一代」电池用的是晶体硅，非晶体硅属于后来的薄膜类型，与「第一代」不符。"}, {"text": "液体", "is_correct": false, "explanation": "搭配：太阳能电池的硅材料是固态，「液体硅电池」不是这里能用的说法。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：「玻璃硅」不是太阳能电池材料的说法，玻璃也不是硅的晶体形态。"}], "explanations": {"晶体": "「晶体硅」指原子有规则排列的硅材料，与句中「第一代晶体硅」的用法一致。", "非晶体": "语义：「第一代」电池用的是晶体硅，非晶体硅属于后来的薄膜类型，与「第一代」不符。", "液体": "搭配：太阳能电池的硅材料是固态，「液体硅电池」不是这里能用的说法。", "玻璃": "搭配：「玻璃硅」不是太阳能电池材料的说法，玻璃也不是硅的晶体形态。"}, "sentence_index": 0, "correct_answer": "晶体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水是一种晶体。", "explanation": "这里应该用〈液体〉。水常温下是液体，晶体指原子规律排列的固体，不能用来说水。"}, {"text": "氧气是一种晶体。", "explanation": "这里应该用〈气体〉。氧气常温下是气体，不是原子规律排列的固体。"}, {"text": "这块晶体像水一样慢慢流动。", "explanation": "这里应该用〈液体〉。晶体是固体，不会像水那样流动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晶体", "is_correct": true, "explanation": "晶体有固定的熔点，这是晶体的特性，符合句意。"}, {"text": "气体", "is_correct": false, "explanation": "语义：气体没有固定的熔点，「固定的熔点」说的是固体晶体的性质。"}, {"text": "沥青", "is_correct": false, "explanation": "语义：沥青属于非晶体，软化时没有固定的熔点，与「固定的熔点」的性质不符。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花是纤维材料，不具有规则结构，说它有固定熔点不符合常识。"}], "explanations": {"晶体": "晶体有固定的熔点，这是晶体的特性，符合句意。", "气体": "语义：气体没有固定的熔点，「固定的熔点」说的是固体晶体的性质。", "沥青": "语义：沥青属于非晶体，软化时没有固定的熔点，与「固定的熔点」的性质不符。", "棉花": "语义：棉花是纤维材料，不具有规则结构，说它有固定熔点不符合常识。"}, "sentence_index": 6, "correct_answer": "晶体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喝了一杯晶体，觉得很解渴。", "explanation": "这里应该用〈液体〉。晶体是固体，不能像水一样用杯子喝。"}, {"text": "这块毛巾是一种晶体。", "explanation": "这里应该用〈织物〉。毛巾是织物，纤维没有规则排列，不是晶体。"}, {"text": "这块橡皮是一种晶体。", "explanation": "这里应该用〈固体〉。橡皮是固体，但内部原子没有规律排列，不属于晶体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只晶体很纯净。", "corrected_sentence": "这块晶体很纯净。", "error_description": "量词错误：「晶体」是块状固体，应说「这块晶体」，不说「这只晶体」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把那块晶体拿了走。", "corrected_sentence": "老师把那块晶体拿走了。", "error_description": "补语位置错误：「拿走」是动补结构，「了」应放在「拿走」之后，不能插在「拿」和「走」中间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
