INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13707, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电能是指电荷运动或积累所产生的能量，可以转化为光、热、动力等形式。", "primary_collocate": null, "pronunciation": "diàn néng", "ipa": "tjɛn˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "第一代晶体硅太阳能电池虽转化效率不足15%，却证明了光能直接转化为电能的可行性。", "target_word": "电能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "区块链技术赋能点对点电力交易，家庭富余电能可直接售予社区用户；人工智能算法则通过气象数据与用电行为预测，实现跨区域源荷动态平衡。", "target_word": "电能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "电灯把电能转化成光能和热能。", "target_word": "电能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机工作时会消耗电能。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电池里储存着电能。", "target_word": "电能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电表记录家里用了多少电能。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风力发电机把风能变成电能。", "target_word": "电能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动汽车靠电能行驶。", "target_word": "电能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "节约电能，要随手关灯。", "target_word": "电能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "输电线路在传送时会损失一部分电能。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "电能表", "label": "复合"}], "register": "科技", "sense_fingerprint": "电荷运动或积累产生的能量，可转化为光、热、动力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a88376a6-aa5b-449c-a391-acd929036bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13707, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风能", "is_correct": false, "explanation": "语义：晶体硅太阳能电池转化出的是电能，不会把光能转化成风能。"}, {"text": "电能", "is_correct": true, "explanation": "正确：光能经太阳能电池直接转化后得到的是电能，与句中“光能直接转化为……”相符。"}, {"text": "水能", "is_correct": false, "explanation": "语义：水能来自水流，与光伏电池的光电转换无关。"}, {"text": "电阻", "is_correct": false, "explanation": "搭配：“转化为”后接能量形式，“电阻”指导体对电流的阻碍，不是能量。"}], "explanations": {"风能": "语义：晶体硅太阳能电池转化出的是电能，不会把光能转化成风能。", "电能": "正确：光能经太阳能电池直接转化后得到的是电能，与句中“光能直接转化为……”相符。", "水能": "语义：水能来自水流，与光伏电池的光电转换无关。", "电阻": "搭配：“转化为”后接能量形式，“电阻”指导体对电流的阻碍，不是能量。"}, "sentence_index": 0, "correct_answer": "电能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天坚持运动，身体里的电能很充足。", "explanation": "这里应该用〈能量〉。电能专指由电产生的能量，人的精力不说“电能”。"}, {"text": "这个变压器输出的电能很高。", "explanation": "这里应该用〈电压〉。描述电的高低要用“电压”，电能是能量，不用“高”来形容。"}, {"text": "手机的电能不足，该充电了。", "explanation": "这里应该用〈电量〉。手机剩余可用的电要说“电量”，电能指能量这一概念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水泥", "is_correct": false, "explanation": "语义：风力发电机只输出电能，不会变出水泥。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：风能转化后的结果是电，不是冰块。"}, {"text": "电能", "is_correct": true, "explanation": "正确：风力发电机把风能转化后得到的是电能，与“变成”相符。"}, {"text": "湿度", "is_correct": false, "explanation": "搭配：“变成”后接能量或物质，“湿度”是空气状态的量度，不能作为转化结果。"}], "explanations": {"水泥": "语义：风力发电机只输出电能，不会变出水泥。", "冰块": "语义：风能转化后的结果是电，不是冰块。", "电能": "正确：风力发电机把风能转化后得到的是电能，与“变成”相符。", "湿度": "搭配：“变成”后接能量或物质，“湿度”是空气状态的量度，不能作为转化结果。"}, "sentence_index": 6, "correct_answer": "电能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根导线里的电能很大。", "explanation": "这里应该用〈电流〉。描述导线中电的流动强弱要用“电流”，电能指能量。"}, {"text": "这台发动机的电能很强劲。", "explanation": "这里应该用〈动力〉。发动机的推动力要说“动力”，电能是能量形式，不用来形容强弱。"}, {"text": "这台电热水器的电能是三千瓦。", "explanation": "这里应该用〈功率〉。“瓦”计量的是功率，电能应以“度”或“千瓦时”计量，不能用瓦数来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家里用了一个电能。", "corrected_sentence": "家里用了一些电能。", "error_description": "量词错误：电能是不可数的能量，不能用“个”计量；应说“一些电能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套装置能把太阳光转化电能。", "corrected_sentence": "这套装置能把太阳光转化成电能。", "error_description": "错误：“转化电能”；正确：“转化成电能”。“把……转化”后须接“成”或“为”引出结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
