INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13710, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指物体一层层叠加而成的结构或状态。", "primary_collocate": null, "pronunciation": "dié céng", "ipa": "tjɛ˧˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "叠层", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这种电池采用叠层设计。", "target_word": "叠层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叠层的好处是能多吸收一些光。", "target_word": "叠层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木板是叠层的，很结实。", "target_word": "叠层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这块岩石有明显的叠层。", "target_word": "叠层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叠层结构让这块板子更结实。", "target_word": "叠层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查板子的叠层。", "target_word": "叠层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山边的石头有一道道叠层。", "target_word": "叠层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究了这种电池的叠层。", "target_word": "叠层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布的叠层很薄，摸着很软。", "target_word": "叠层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "疊層", "label": "繁体"}, {"form": "叠层结构", "label": "复合"}, {"form": "叠层电池", "label": "复合"}], "register": "书面", "sense_fingerprint": "叠层|一层层叠加的结构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92b8e895-07d2-430a-a35a-f19f0da65d06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叠层", "is_correct": true, "explanation": "「多结叠层电池」指多层叠加结构的电池，与句中的光伏技术一致。"}, {"text": "木板", "is_correct": false, "explanation": "语义：光伏电池的多结结构不是木板，木板不能用于「多结……电池」。"}, {"text": "布料", "is_correct": false, "explanation": "语义：布料不能构成光谱响应的多结电池结构，与句意不符。"}, {"text": "积木", "is_correct": false, "explanation": "搭配：「积木电池」不是这里能用的说法，积木是玩具，不能说「多结积木电池」。"}], "explanations": {"叠层": "「多结叠层电池」指多层叠加结构的电池，与句中的光伏技术一致。", "木板": "语义：光伏电池的多结结构不是木板，木板不能用于「多结……电池」。", "布料": "语义：布料不能构成光谱响应的多结电池结构，与句意不符。", "积木": "搭配：「积木电池」不是这里能用的说法，积木是玩具，不能说「多结积木电池」。"}, "sentence_index": 0, "correct_answer": "叠层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手的叠层很动听。", "explanation": "这里应该用〈音色〉。叠层指物体一层层叠加的结构，形容声音要说〈音色〉。"}, {"text": "这篇文章的叠层很清楚。", "explanation": "这里应该用〈层次〉。叠层指物体一层层叠加的结构，文章的条理要说〈层次〉。"}, {"text": "这道数学题的叠层很难。", "explanation": "这里应该用〈难度〉。叠层指物体一层层叠加的结构，题目的难易要说〈难度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叠层", "is_correct": true, "explanation": "「检查板子的叠层」指检查板子一层层叠加的结构，符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "语义：板子没有心情可以检查，「心情」与板子无关。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：板子不会发出可以检查的歌声，与板子的结构无关。"}, {"text": "诗句", "is_correct": false, "explanation": "语义：板子不是文字，不存在可检查的诗句。"}], "explanations": {"叠层": "「检查板子的叠层」指检查板子一层层叠加的结构，符合句意。", "心情": "语义：板子没有心情可以检查，「心情」与板子无关。", "歌声": "语义：板子不会发出可以检查的歌声，与板子的结构无关。", "诗句": "语义：板子不是文字，不存在可检查的诗句。"}, "sentence_index": 6, "correct_answer": "叠层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的回答叠层很有条理。", "explanation": "这里应该用〈条理〉。叠层指物体一层层叠加的结构，回答的条理不是叠层。"}, {"text": "他的叠层比我还高。", "explanation": "这里应该用〈身高〉。叠层指物体一层层叠加的结构，人的高矮要说〈身高〉。"}, {"text": "这杯咖啡的叠层很香。", "explanation": "这里应该用〈香味〉。叠层指物体一层层叠加的结构，咖啡的气味要说〈香味〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只叠层结构很结实。", "corrected_sentence": "这种叠层结构很结实。", "error_description": "量词错误：「叠层结构」应用量词〈种〉，不用〈只〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "岩石上有明显地叠层。", "corrected_sentence": "岩石上有明显的叠层。", "error_description": "的地混用：修饰名词「叠层」要用「的」，不用「地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
