INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13712, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "物体对光或其他信号产生反应的能力", "primary_collocate": null, "pronunciation": "xiǎng yìng", "ipa": "ɕiaŋ˨˩˦ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个传感器对光的响应很快。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕的触摸响应非常灵敏。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑的响应速度比以前快多了。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛对强光的响应是缩小瞳孔。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个按钮没有响应，可能坏了。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站的响应太慢，我等了很久。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料对温度变化有明显响应。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老式收音机对弱信号几乎没有响应。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师在测试机器的响应时间。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向日葵对阳光有明显的响应。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "响应速度", "label": "复合词"}, {"form": "响应时间", "label": "复合词"}], "register": "中性", "sense_fingerprint": "响应：物体或设备对光、信号等刺激产生反应的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90865500-d708-484f-b474-f4f4acd19e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "响应", "is_correct": true, "explanation": "正确。“对光的响应”指传感器对光产生反应的能力，与“很快”搭配自然。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“亮度”描述明暗程度，不能用“很快”来形容，“亮度很快”不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”描述色彩，不说快慢，不能与“很快”搭配。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，与传感器对光的反应无关，句意不通。"}], "explanations": {"响应": "正确。“对光的响应”指传感器对光产生反应的能力，与“很快”搭配自然。", "亮度": "搭配：“亮度”描述明暗程度，不能用“很快”来形容，“亮度很快”不通。", "颜色": "搭配：“颜色”描述色彩，不说快慢，不能与“很快”搭配。", "重量": "语义：“重量”指物体的轻重，与传感器对光的反应无关，句意不通。"}, "sentence_index": 0, "correct_answer": "响应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的响应很重，一下子就把箱子扛起来了。", "explanation": "这里应该用〈力气〉。“力气”可以说大小，“响应”不能用来形容人的力量。"}, {"text": "这座山的响应很高，爬起来很费力。", "explanation": "这里应该用〈海拔〉。山的高度用“海拔”，“响应”不能描述山的高低。"}, {"text": "这张照片响应了城市的面貌。", "explanation": "这里应该用〈反映〉。“反映”指显示、表现情况，“响应”指对信号或要求作出反应，不能表示显示面貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "响应", "is_correct": true, "explanation": "正确。“对温度变化有明显响应”指材料对温度变化产生反应，句意通顺。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：材料没有情绪，“情绪”不能用来描述材料对温度变化的反应。"}, {"text": "名字", "is_correct": false, "explanation": "语义：材料不会对温度变化产生“名字”，与“对温度变化”的语义不合。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“明显”不修饰“座位”，“有明显座位”不能这样搭配。"}], "explanations": {"响应": "正确。“对温度变化有明显响应”指材料对温度变化产生反应，句意通顺。", "情绪": "语义：材料没有情绪，“情绪”不能用来描述材料对温度变化的反应。", "名字": "语义：材料不会对温度变化产生“名字”，与“对温度变化”的语义不合。", "座位": "搭配：“明显”不修饰“座位”，“有明显座位”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "响应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个仪器的响应很重，搬起来很费力。", "explanation": "这里应该用〈重量〉。“重量”可以说轻重，“响应”不能用“重”来形容。"}, {"text": "网络的响应很大，网页总是打不开。", "explanation": "这里应该用〈延迟〉。延迟指等待的时间，可以说“大、小”；“响应”不能表示拖延的时长。"}, {"text": "这台机器的响应很贵，买一台要二十万。", "explanation": "这里应该用〈价格〉。价格可以说贵，“响应”不能用“贵”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个开关给按键的响应很快。", "corrected_sentence": "这个开关对按键的响应很快。", "error_description": "错误：“给按键的响应”。正确：“对按键的响应”。“对”引出“响应”的对象，这里应用“对”而非“给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台仪器对声音有一只快速的响应。", "corrected_sentence": "这台仪器对声音有一种快速的响应。", "error_description": "错误：“一只快速的响应”。正确：“一种快速的响应”。“只”用于动物或成对的物品，“响应”是抽象名词，应用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
