INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "钙钛矿是一类具有特定晶体结构的化合物，常见于太阳能电池等高科技领域，因其高效的光电转换性能而受到广泛研究。", "primary_collocate": null, "pronunciation": "gài tài kuàng", "ipa": "kai˥˩ tʰai˥˩ kʰuaŋ˥˩", "syllable_count": 3, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "钙钛矿", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "钙钛矿可以用来做太阳能电池。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块钙钛矿是深色的。", "target_word": "钙钛矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家正在研究钙钛矿的晶体结构。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钙钛矿电池的光电转换效率很高。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里的钙钛矿样品需要小心保存。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用钙钛矿做的薄膜又轻又薄。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想把钙钛矿电池卖到国外。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钙钛矿的成本比硅低很多。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文写的是钙钛矿材料。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鈣鈦礦", "label": "繁体"}, {"form": "钙钛矿电池", "label": "复合"}], "register": "书面", "sense_fingerprint": "具特定晶体结构的化合物，用于太阳能电池", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5845f11-6b3d-4f3d-90b8-a89f81eb4318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13713, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钙钛矿", "is_correct": true, "explanation": "正确：“钙钛矿材料”是句中指的光伏电池材料，能以低廉成本与柔性特质改变制造逻辑。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐不是电池材料，不能“以其低廉成本与柔性特质颠覆传统制造逻辑”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能用于制造光伏器件，与句中讨论的电池技术无关。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”描述人或动物的身体，不能用来指代制造材料。"}], "explanations": {"钙钛矿": "正确：“钙钛矿材料”是句中指的光伏电池材料，能以低廉成本与柔性特质改变制造逻辑。", "早餐": "语义：早餐不是电池材料，不能“以其低廉成本与柔性特质颠覆传统制造逻辑”。", "歌曲": "语义：歌曲不能用于制造光伏器件，与句中讨论的电池技术无关。", "体重": "体貌：“体重”描述人或动物的身体，不能用来指代制造材料。"}, "sentence_index": 0, "correct_answer": "钙钛矿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "钙钛矿是一种元素，它是制造太阳能电池的常用材料。", "explanation": "这里应该用〈硅〉。硅是单质元素，钙钛矿是由多种元素组成的化合物，不能说它是一种元素。"}, {"text": "体温计里装的是钙钛矿。", "explanation": "这里应该用〈水银〉。水银是液态金属，装在体温计里；钙钛矿是固态晶体化合物，不能这样用。"}, {"text": "钙钛矿是一种金属，很轻，也很结实。", "explanation": "这里应该用〈钛〉。钛是金属单质，钙钛矿是化合物，不是金属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钙钛矿", "is_correct": true, "explanation": "正确：“用钙钛矿做的薄膜”指以钙钛矿材料制成的薄膜，符合语境。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能用来做薄膜。"}, {"text": "体温", "is_correct": false, "explanation": "体貌：“体温”是人或动物身体的温度，不能作为制膜材料。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学作品，不能用来制造薄膜。"}], "explanations": {"钙钛矿": "正确：“用钙钛矿做的薄膜”指以钙钛矿材料制成的薄膜，符合语境。", "饼干": "语义：饼干是食品，不能用来做薄膜。", "体温": "体貌：“体温”是人或动物身体的温度，不能作为制膜材料。", "诗歌": "语义：诗歌是文学作品，不能用来制造薄膜。"}, "sentence_index": 6, "correct_answer": "钙钛矿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钙钛矿是一种很软的矿物，可以用来写字。", "explanation": "这里应该用〈石墨〉。石墨柔软，可以用来写字；钙钛矿是硬脆的晶体化合物，不能用来写字。"}, {"text": "他吃了一块钙钛矿。", "explanation": "这里应该用〈饼干〉。钙钛矿是晶体化合物，不能吃；“吃”应用于食物。"}, {"text": "钙钛矿很柔软，常用来做衣服。", "explanation": "这里应该用〈棉花〉。棉花柔软，可以做衣服；钙钛矿是硬脆的晶体，不能说它很柔软、常用来做衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家用钙钛矿的做太阳能电池。", "corrected_sentence": "科学家用钙钛矿做太阳能电池。", "error_description": "多余的“的”：“钙钛矿”直接作“用”的宾语，后面接动词“做”，中间不能加“的”；正确说法是“用钙钛矿做太阳能电池”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只钙钛矿材料很轻。", "corrected_sentence": "这种钙钛矿材料很轻。", "error_description": "量词误用：“材料”不能用量词“只”（“只”多用于动物或成对的物品），应用“种”，说“这种钙钛矿材料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13714, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "刚性", "is_correct": true, "explanation": "反义：刚性指物体不易变形的性质，与柔性形成对立。"}, {"text": "速度", "is_correct": false, "explanation": "无关：速度与柔性没有反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "无关：温度与柔性没有反义关系。"}, {"text": "密度", "is_correct": false, "explanation": "无关：密度与柔性没有反义关系。"}], "correct_answer": "刚性", "explanations": {"刚性": "反义：刚性指物体不易变形的性质，与柔性形成对立。", "速度": "无关：速度与柔性没有反义关系。", "温度": "无关：温度与柔性没有反义关系。", "密度": "无关：密度与柔性没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13714, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "刚性", "is_correct": true, "explanation": "反义：刚性指物体不易变形的性质，与柔性形成对立。"}, {"text": "亮度", "is_correct": false, "explanation": "无关：亮度与柔性没有反义关系。"}, {"text": "频率", "is_correct": false, "explanation": "无关：频率与柔性没有反义关系。"}, {"text": "长度", "is_correct": false, "explanation": "无关：长度与柔性没有反义关系。"}], "correct_answer": "刚性", "explanations": {"刚性": "反义：刚性指物体不易变形的性质，与柔性形成对立。", "亮度": "无关：亮度与柔性没有反义关系。", "频率": "无关：频率与柔性没有反义关系。", "长度": "无关：长度与柔性没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指物体柔软、易弯曲的性质，也指灵活的、可调整的。", "primary_collocate": null, "pronunciation": "róu xìng", "ipa": "ɻou̯˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "柔性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种材料的柔性很好，可以弯很多次。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的管理很有柔性。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "薄膜的柔性让它可以贴在手上。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要提高生产线的柔性。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师测试了这块板的柔性。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "柔性好的材料不容易断。", "target_word": "柔性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机屏幕的柔性越来越高。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "计划要有一定的柔性，才能应对变化。", "target_word": "柔性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种布的柔性让衣服穿着很舒服。", "target_word": "柔性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "柔性材料", "label": "复合"}, {"form": "柔性屏", "label": "复合"}], "register": "书面", "sense_fingerprint": "柔性|名词|物体柔软易弯曲的性质，也指灵活可调整", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef9cf912-3233-4a4e-8b9e-0ce8bdd8a849') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柔性", "is_correct": true, "explanation": "柔性指材料柔软可弯的性质，修饰“特质”，符合“颠覆传统制造逻辑”的语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是材料的特质，“以其低廉的价格特质”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与“颠覆制造逻辑”无关，不能作为特质的内容。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“特质”前多接性质或特征，“速度”不能修饰“特质”。"}], "explanations": {"柔性": "柔性指材料柔软可弯的性质，修饰“特质”，符合“颠覆传统制造逻辑”的语境。", "价格": "语义：价格不是材料的特质，“以其低廉的价格特质”说不通。", "颜色": "语义：颜色与“颠覆制造逻辑”无关，不能作为特质的内容。", "速度": "搭配：“特质”前多接性质或特征，“速度”不能修饰“特质”。"}, "sentence_index": 0, "correct_answer": "柔性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是个很柔性的人，大家都很喜欢她。", "explanation": "这里应该用〈温柔〉。柔性指物体柔软、可调整，形容人的性格要用温柔。"}, {"text": "我们测试了一片柔性。", "explanation": "这里应该用〈种〉。柔性是抽象的性质，量词不用“片”（“片”用于薄的物体），应说“一种柔性”。"}, {"text": "他的声音很柔性，听着很舒服。", "explanation": "这里应该用〈柔和〉。形容声音、语气要用柔和，柔性指物体可弯曲或可调整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柔性", "is_correct": true, "explanation": "柔性指材料柔软可弯的性质，作主语，句意是“柔性好的材料不容易断”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与材料断裂无关，“温度好的材料”说不通。"}, {"text": "密度", "is_correct": false, "explanation": "搭配：“密度”的高低用“高”“低”或“大”“小”，不说“密度好”。"}, {"text": "形象", "is_correct": false, "explanation": "搭配：“好”多用于形容人或事物的形象，“形象好的材料”不成立。"}], "explanations": {"柔性": "柔性指材料柔软可弯的性质，作主语，句意是“柔性好的材料不容易断”。", "温度": "语义：温度与材料断裂无关，“温度好的材料”说不通。", "密度": "搭配：“密度”的高低用“高”“低”或“大”“小”，不说“密度好”。", "形象": "搭配：“好”多用于形容人或事物的形象，“形象好的材料”不成立。"}, "sentence_index": 6, "correct_answer": "柔性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头很柔性，敲起来很响。", "explanation": "这里应该用〈坚硬〉。形容石头的硬要用坚硬，柔性指柔软、可弯曲，不能形容石头。"}, {"text": "这扇铁门的柔性很强，关起来很结实。", "explanation": "这里应该用〈坚固〉。门要求牢固，柔性指可弯曲或可调整，铁门不能说柔性很强。"}, {"text": "今天的天气很柔性，适合出门。", "explanation": "这里应该用〈温和〉。柔性用于物体或系统的可弯曲、可调整，形容天气要说温和。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块板的柔性地很好。", "corrected_sentence": "这块板的柔性很好。", "error_description": "“柔性”是名词，后面不能加状语标记“地”；“柔性很好”直接作谓语，应去掉“地”，说“柔性很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这层薄膜有一只柔性，可以反复弯折。", "corrected_sentence": "这层薄膜有一种柔性，可以反复弯折。", "error_description": "“柔性”是抽象性质名词，量词应用“种”，不能用“只”（“只”多用于动物或单个物品）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
