INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13717, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "双面指具有两个不同的表面，或用于形容事物有两方面的特性。", "primary_collocate": null, "pronunciation": "shuāng miàn", "ipa": "ʂwɑŋ˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "双面", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这张卡片是双面的。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用双面打印，可以省纸。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件外套双面都能穿。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木板双面都刷了漆。", "target_word": "双面", "complexity_tier": "T3", "furigana": "zhè kuài mù bǎn shuāng miàn dōu shuā le qī.", "sentence_source": "generated"}, {"text": "网络有好的一面，也有坏的一面，是双面的。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面旗子双面都有图案。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策的影响是双面的，要全面看待。", "target_word": "双面", "complexity_tier": "T3", "furigana": "zhè xiàng zhèng cè de yǐng xiǎng shì shuāng miàn de, yào quán miàn kàn dài.", "sentence_source": "generated"}, {"text": "这块磨刀石是双面的，两面都能磨。", "target_word": "双面", "complexity_tier": "T3", "furigana": "zhè kuài mó dāo shí shì shuāng miàn de, liǎng miàn dōu néng mó.", "sentence_source": "generated"}, {"text": "这种布是双面的，两边颜色不同。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "双面的", "label": "定语形式"}, {"form": "双面性", "label": "复合"}, {"form": "雙面", "label": "繁体"}], "register": "中性", "sense_fingerprint": "双面：有两个不同的面，或有两方面的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5845f11-6b3d-4f3d-90b8-a89f81eb4318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双面", "is_correct": true, "explanation": "双面：两面都能受光，正好配合“地面反射光捕获”。"}, {"text": "单面", "is_correct": false, "explanation": "语义：单面组件只有一面受光，无法借地面反射光发电，与句中“地面反射光捕获”相矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：光伏语境中的“组件”指发电部件，“窗户”不是光伏组件，句意不通。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：“组件设计”搭配的是光伏设备，不能与“拖鞋”组合。"}], "explanations": {"双面": "双面：两面都能受光，正好配合“地面反射光捕获”。", "单面": "语义：单面组件只有一面受光，无法借地面反射光发电，与句中“地面反射光捕获”相矛盾。", "窗户": "语义：光伏语境中的“组件”指发电部件，“窗户”不是光伏组件，句意不通。", "拖鞋": "搭配：“组件设计”搭配的是光伏设备，不能与“拖鞋”组合。"}, "sentence_index": 0, "correct_answer": "双面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这次比赛的双面冠军。", "explanation": "这里应该用〈双料〉。双面只指物体的两面或两方面的特性，不能用来说同时获得两项荣誉。"}, {"text": "双面达成了协议。", "explanation": "这里应该用〈双方〉。双面指物体的两个面或事物的两方面特性，不能指参与的各方。"}, {"text": "这件事有很多双面。", "explanation": "这里应该用〈方面〉。双面只指两面或两方面的特性，不能用“很多”来计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "双面", "is_correct": true, "explanation": "双面：指旗子的两面，与“都有图案”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”本身不能“有图案”，句意不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”不是可以印图案的表面，与“都有图案”不合。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是可以附着图案的表面，与“都有图案”不合。"}], "explanations": {"双面": "双面：指旗子的两面，与“都有图案”相合。", "颜色": "语义：“颜色”本身不能“有图案”，句意不通。", "重量": "语义：“重量”不是可以印图案的表面，与“都有图案”不合。", "声音": "语义：“声音”不是可以附着图案的表面，与“都有图案”不合。"}, "sentence_index": 6, "correct_answer": "双面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都拿双面的薪水。", "explanation": "这里应该用〈双倍〉。双面只指物体的两面或两方面的特性，不能用来说薪水加倍。"}, {"text": "这家公司实行双面周末制度。", "explanation": "这里应该用〈双休〉。双面不能用来说每周休息两天。"}, {"text": "那只母鸡生了一个双面蛋。", "explanation": "这里应该用〈双黄〉。双面指物体的两个面，不能用来说蛋黄成双。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请双面打印了这份报告。", "corrected_sentence": "请双面打印这份报告。", "error_description": "错误：祈使句“请……”后不能带“了”。“打印了”应为“打印”，正确句为“请双面打印这份报告。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把木椅双面的都刷了漆。", "corrected_sentence": "这把木椅双面都刷了漆。", "error_description": "错误：“双面”作状语修饰“刷”时后面不加“的”。加了“的”后“双面的”变成名词性短语，句子不通。应为“双面都刷了漆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
