INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "组件是指构成整体系统的各个独立单元或部件。", "primary_collocate": null, "pronunciation": "zǔ jiàn", "ipa": "tsu˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "组件", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台机器的每个组件都很重要。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在检查电脑里的组件。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个组件坏了，整台机器不能用。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "软件由很多组件组成。", "target_word": "组件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他买了新的太阳能组件。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂每天生产几千个组件。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要把旧组件换成新的。", "target_word": "组件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的主要组件有屏幕和电池。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修车时，他先拆下了坏掉的组件。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套系统的组件都是独立的。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "光伏组件", "label": "复合"}], "register": "中性", "sense_fingerprint": "构成系统的独立部件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb540fec-9cec-4bcb-8643-5a997deb09c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "组件", "is_correct": true, "explanation": "组件（zǔ jiàn）指构成整体的独立单元，是本词的读音和意思。"}, {"text": "主见", "is_correct": false, "explanation": "主见（zhǔ jiàn）：声母 zh 与 z 不同，意思是自己的见解。"}, {"text": "组间", "is_correct": false, "explanation": "组间（zǔ jiān）：jiàn 与 jiān 声调不同（第四声与第一声），意思是组与组之间。"}, {"text": "足见", "is_correct": false, "explanation": "足见（zú jiàn）：zǔ 与 zú 声调不同（第三声与第二声），意思是足以看出。"}], "explanations": {"组件": "组件（zǔ jiàn）指构成整体的独立单元，是本词的读音和意思。", "主见": "主见（zhǔ jiàn）：声母 zh 与 z 不同，意思是自己的见解。", "组间": "组间（zǔ jiān）：jiàn 与 jiān 声调不同（第四声与第一声），意思是组与组之间。", "足见": "足见（zú jiàn）：zǔ 与 zú 声调不同（第三声与第二声），意思是足以看出。"}, "sentence_index": null, "correct_answer": "组件"}, "level_3": {"options": [{"text": "组件", "is_correct": true, "explanation": "组件：构成系统的独立部件。「双面组件设计」指光伏组件的双面结构，与前文的光伏技术语境一致。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭，不是光伏电池的部件，放进「双面___设计」与语境不符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是可以喝的液体，不能作为光伏设备的双面设计对象。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「双面天气设计」不成搭配，天气不能被设计成双面结构。"}], "explanations": {"组件": "组件：构成系统的独立部件。「双面组件设计」指光伏组件的双面结构，与前文的光伏技术语境一致。", "早餐": "语义：早餐是一顿饭，不是光伏电池的部件，放进「双面___设计」与语境不符。", "饮料": "语义：饮料是可以喝的液体，不能作为光伏设备的双面设计对象。", "天气": "搭配：「双面天气设计」不成搭配，天气不能被设计成双面结构。"}, "sentence_index": 0, "correct_answer": "组件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个组件有五百名成员，每天都开会。", "explanation": "这里应该用〈组织〉。组织指由人组成的团体，有成员和会议；组件是物体的独立部件，不能指团体。"}, {"text": "这家公司有三个组件，分别负责销售和财务。", "explanation": "这里应该用〈部门〉。部门是机构内按职能划分的单位；组件指机器或系统中的部件，不用来划分公司。"}, {"text": "我买了一只组件，装在电脑里了。", "explanation": "这里量词应与「组件」搭配：组件用〈个〉或〈套〉，不用〈只〉。「只」多用于动物或成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组件", "is_correct": true, "explanation": "组件：可以被生产出来的独立部件，与「工厂每天生产几千个」的语境相符。"}, {"text": "人", "is_correct": false, "explanation": "语义：人不是工厂生产出来的产品，「生产几千个人」与语境不符。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不是工厂生产的东西，「生产几千个星星」与语境不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是工厂生产的东西，不能「每天生产几千个天气」。"}], "explanations": {"组件": "组件：可以被生产出来的独立部件，与「工厂每天生产几千个」的语境相符。", "人": "语义：人不是工厂生产出来的产品，「生产几千个人」与语境不符。", "星星": "语义：星星不是工厂生产的东西，「生产几千个星星」与语境不符。", "天气": "语义：天气不是工厂生产的东西，不能「每天生产几千个天气」。"}, "sentence_index": 6, "correct_answer": "组件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的组件很高，一看就是运动员。", "explanation": "这里应该用〈身材〉。组件指构成机器或系统的部件，不能用来形容人的身形。"}, {"text": "这块地的组件有三亩，全种了麦子。", "explanation": "这里应该用〈面积〉。组件指构成系统的部件，不能用来说土地的大小。"}, {"text": "他用组件把螺丝拧紧了。", "explanation": "这里应该用〈工具〉。组件是机器里的一部分，不能拿来当工具使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器有十只组件。", "corrected_sentence": "这台机器有十个组件。", "error_description": "量词错误：「组件」应用量词「个」（或「套」），说「十只组件」是错误的，正确说法是「十个组件」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电脑里有一条组件坏了。", "corrected_sentence": "电脑里有一个组件坏了。", "error_description": "量词错误：「组件」应用量词「个」，「条」用于细长的东西，不能用来数组件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
