INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13719, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体表面将接收到的光线返回出去的光。", "primary_collocate": null, "pronunciation": "fǎn shè guāng", "ipa": "fan˨˩˦ ʂɤ˥˩ kwɑŋ˥", "syllable_count": 3, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "反射光", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水面的反射光很刺眼。", "target_word": "反射光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "镜子会产生反射光。", "target_word": "反射光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雪地上的反射光让他睁不开眼。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白色墙面的反射光比较多。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车窗的反射光晃了司机的眼。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一束反射光照在了墙上。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黑色的东西几乎没有反射光。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他戴着墨镜挡住反射光。", "target_word": "反射光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖面上有一道反射光。", "target_word": "反射光", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "束", "label": "量词"}, {"form": "道", "label": "量词"}], "register": "中性", "sense_fingerprint": "物体表面返回的光线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb540fec-9cec-4bcb-8643-5a997deb09c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13719, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反射光", "is_correct": true, "explanation": "反射光：物体表面返回的光。「地面反射光捕获」指被地面反射的光，与发电的语境相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是光，无法被地面反射后捕获来发电。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味不是光，不能通过地面反射被捕获。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：「捕获影子」不成搭配，影子不是可以收集的光能。"}], "explanations": {"反射光": "反射光：物体表面返回的光。「地面反射光捕获」指被地面反射的光，与发电的语境相符。", "声音": "语义：声音不是光，无法被地面反射后捕获来发电。", "气味": "语义：气味不是光，不能通过地面反射被捕获。", "影子": "搭配：「捕获影子」不成搭配，影子不是可以收集的光能。"}, "sentence_index": 0, "correct_answer": "反射光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳是地球最主要的反射光。", "explanation": "这里应该用〈光源〉。光源是自身发光的物体，如太阳；反射光是物体返回的光，不能指太阳本身。"}, {"text": "他在屋里点着了反射光，照亮了桌子。", "explanation": "这里应该用〈蜡烛〉。蜡烛自身燃烧发光，可以点着；反射光是物体返回的光，不能被点着。"}, {"text": "他把反射光关掉，屋里就暗了。", "explanation": "这里应该用〈台灯〉。台灯自身发光，可以开关；反射光是物体返回的光，没有开关，不能关掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反射光", "is_correct": true, "explanation": "反射光：物体表面返回的光。「一束反射光照在了墙上」符合语境。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能「照在墙上」，这一动作需要光作主语。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子不能「照在墙上」，这一动作只能用于光。"}, {"text": "头发", "is_correct": false, "explanation": "搭配：「照在墙上」不搭配「头发」，头发不能像光一样照射。"}], "explanations": {"反射光": "反射光：物体表面返回的光。「一束反射光照在了墙上」符合语境。", "花": "语义：花不能「照在墙上」，这一动作需要光作主语。", "绳子": "语义：绳子不能「照在墙上」，这一动作只能用于光。", "头发": "搭配：「照在墙上」不搭配「头发」，头发不能像光一样照射。"}, "sentence_index": 6, "correct_answer": "反射光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上有一把反射光。", "explanation": "这里量词应与「反射光」搭配：反射光用〈束〉或〈道〉，「把」用于有柄的东西，不能数反射光。"}, {"text": "他打开反射光，照向黑暗的角落。", "explanation": "这里应该用〈手电筒〉。手电筒自身发光，可以打开；反射光是物体返回的光，不能人为打开。"}, {"text": "电灯是屋里的主要反射光。", "explanation": "这里应该用〈灯泡〉。灯泡是自身发光的光源；反射光是物体返回的光，不能说电灯是反射光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上有一只反射光。", "corrected_sentence": "墙上有一束反射光。", "error_description": "量词错误：「反射光」应用量词「束」或「道」，「只」多用于动物或成对的东西，说「一只反射光」是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖面上有一对反射光，很刺眼。", "corrected_sentence": "湖面上有一道反射光，很刺眼。", "error_description": "量词错误：「反射光」应用量词「道」，「对」用于成对的东西，不能用来数反射光。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13720, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "释放", "is_correct": true, "explanation": "反义：「捕获」指捉住，「释放」指放开使其恢复自由，二者意思相反。"}, {"text": "种植", "is_correct": false, "explanation": "语义：「种植」指栽培植物，与捉住目标没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "语义：「思考」指用脑子想问题，与捉住目标无关，不构成反义。"}, {"text": "建造", "is_correct": false, "explanation": "语义：「建造」指修建房屋、设施，与捉住目标没有反义关系。"}], "correct_answer": "释放", "explanations": {"释放": "反义：「捕获」指捉住，「释放」指放开使其恢复自由，二者意思相反。", "种植": "语义：「种植」指栽培植物，与捉住目标没有反义关系。", "思考": "语义：「思考」指用脑子想问题，与捉住目标无关，不构成反义。", "建造": "语义：「建造」指修建房屋、设施，与捉住目标没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13720, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "释放", "is_correct": true, "explanation": "反义：「捕获」指捉住，「释放」指放开使其恢复自由，二者意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：「讨论」指交换意见，与捉住目标无关，不构成反义。"}, {"text": "生长", "is_correct": false, "explanation": "语义：「生长」指生物发育、长大，与捉住目标没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：「搬运」指把物体从一处移到另一处，与「捕获」不是反义关系。"}], "correct_answer": "释放", "explanations": {"释放": "反义：「捕获」指捉住，「释放」指放开使其恢复自由，二者意思相反。", "讨论": "语义：「讨论」指交换意见，与捉住目标无关，不构成反义。", "生长": "语义：「生长」指生物发育、长大，与捉住目标没有反义关系。", "搬运": "语义：「搬运」指把物体从一处移到另一处，与「捕获」不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "捉住、逮住，指通过追捕或设伏等方式使目标无法逃脱。", "primary_collocate": null, "pronunciation": "bǔ huò", "ipa": "pu˨˩˦ xwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "捕获", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "渔民昨天捕获了一条大鱼。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察终于捕获了那个小偷。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猎人用网捕获了一只鸟。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖里的鱼很多，渔民却只捕获了几条。", "target_word": "捕获", "complexity_tier": "T3", "furigana": "hú lǐ de yú hěn duō, yú mín què zhǐ bǔhuò le jǐ tiáo.", "sentence_source": "generated"}, {"text": "科学家捕获过一只罕见的海豚。", "target_word": "捕获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在森林里捕获了一头鹿。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔船出海一周，捕获了很多鱼。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鸟很难捕获。", "target_word": "捕获", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察在海上捕获了走私船。", "target_word": "捕获", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "捕获了", "label": "体标"}, {"form": "捕获过", "label": "体标"}], "register": "中性", "sense_fingerprint": "通过追捕或设伏捉住目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb540fec-9cec-4bcb-8643-5a997deb09c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捕获", "is_correct": true, "explanation": "正确。「捕获」指把目标捉住，这里指把反射光捉住并加以利用，使发电量提升，符合语境。"}, {"text": "制造", "is_correct": false, "explanation": "语义：反射光是已经存在的光，不能被「制造」出来，与「地面反射光」矛盾。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：「删除」多用于文件、数据，不说删除光，也与「提升发电量」的语境不符。"}, {"text": "屏蔽", "is_correct": false, "explanation": "语义：屏蔽光会减少而非提升发电量，与后半句「使发电量提升」直接矛盾。"}], "explanations": {"捕获": "正确。「捕获」指把目标捉住，这里指把反射光捉住并加以利用，使发电量提升，符合语境。", "制造": "语义：反射光是已经存在的光，不能被「制造」出来，与「地面反射光」矛盾。", "删除": "搭配：「删除」多用于文件、数据，不说删除光，也与「提升发电量」的语境不符。", "屏蔽": "语义：屏蔽光会减少而非提升发电量，与后半句「使发电量提升」直接矛盾。"}, "sentence_index": 0, "correct_answer": "捕获"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在考试中捕获了好成绩。", "explanation": "这里应该用〈获得〉。捕获指捉住逃跑的目标，成绩这类抽象结果要用「获得」。"}, {"text": "我们很快捕获了这份合同。", "explanation": "这里应该用〈签订〉。捕获针对要捉住的目标，合同要用「签订」。"}, {"text": "秋天，农民捕获了很多果实。", "explanation": "这里应该用〈收获〉。捕获用于捉住动物等目标，果实、庄稼要用「收获」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捕获", "is_correct": true, "explanation": "正确。「捕获」指追捕或设伏后捉住目标，这里指他们在森林里捉住了一头鹿。"}, {"text": "印刷", "is_correct": false, "explanation": "语义：「印刷」指用印版复制文字图像，无法施于一头鹿，与森林里的语境不符。"}, {"text": "烘焙", "is_correct": false, "explanation": "搭配：「烘焙」多用于面包、饼干等食物，不搭配「一头鹿」。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：「熨烫」用于衣物，不能用于一头鹿，也与森林里的语境不符。"}], "explanations": {"捕获": "正确。「捕获」指追捕或设伏后捉住目标，这里指他们在森林里捉住了一头鹿。", "印刷": "语义：「印刷」指用印版复制文字图像，无法施于一头鹿，与森林里的语境不符。", "烘焙": "搭配：「烘焙」多用于面包、饼干等食物，不搭配「一头鹿」。", "熨烫": "搭配：「熨烫」用于衣物，不能用于一头鹿，也与森林里的语境不符。"}, "sentence_index": 6, "correct_answer": "捕获"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的军队一天之内就捕获了那座城市。", "explanation": "这里应该用〈攻占〉。捕获针对逃跑的人或动物，城市这类地点要用「攻占」。"}, {"text": "园丁在花园里捕获了一株月季。", "explanation": "这里应该用〈栽种〉。捕获指捉住逃跑的目标，植物要用「栽种」。"}, {"text": "我们用卷尺捕获了这座山的高度。", "explanation": "这里应该用〈测量〉。捕获指捉住目标，山的高度要用「测量」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "巡逻队把三名偷渡者都捕获。", "corrected_sentence": "巡逻队把三名偷渡者都捕获了。", "error_description": "把字句缺少补语：「把」字句的动词后要有「了」或补语，「把三名偷渡者都捕获」应改为「把三名偷渡者都捕获了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨晚没捕获了任何野兽。", "corrected_sentence": "他们昨晚没捕获任何野兽。", "error_description": "「了」用错：否定句中「没」加动词后不能再带「了」，「没捕获了」应改为「没捕获」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
