INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13721, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13721, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "发电量指发电设备在单位时间内产生的电能数量，通常以千瓦时为单位。", "primary_collocate": null, "pronunciation": "fā diàn liàng", "ipa": "fa˥ tjɛn˥˩ ljɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "发电量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年风电场的发电量比去年多了。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气好的时候，太阳能的发电量更高。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座水电站每年的发电量很大。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天风大，发电量会增加。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师每天记录电站的发电量。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发电量用千瓦时来计算。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云多的时候，电池板的发电量会下降。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月电厂的发电量达到了新高。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想办法提高风车的发电量。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "总发电量", "label": "复合"}, {"form": "年发电量", "label": "复合"}, {"form": "發電量", "label": "繁体"}], "register": "中性", "sense_fingerprint": "发电设备在一定时间内产生的电能总量，以千瓦时计", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb540fec-9cec-4bcb-8643-5a997deb09c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13721, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发电量", "is_correct": true, "explanation": "正确。“发电量”是发电设备产出的电能，可以按百分比提升。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色不能按百分比提升，这里提升的对象应是产出的电能。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会因设计而提升，这里提升的对象应是产出的电能。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”可以说浓淡，但不说“提升20%以上”。"}], "explanations": {"发电量": "正确。“发电量”是发电设备产出的电能，可以按百分比提升。", "颜色": "体貌：颜色不能按百分比提升，这里提升的对象应是产出的电能。", "年龄": "语义：年龄不会因设计而提升，这里提升的对象应是产出的电能。", "味道": "搭配：“味道”可以说浓淡，但不说“提升20%以上”。"}, "sentence_index": 0, "correct_answer": "发电量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的发电量是两公斤。", "explanation": "这里应该用〈重量〉。公斤是质量单位，机器的重量要说重量；发电量是电能，用千瓦时计。"}, {"text": "这座风电场每天的发电量是二十四小时。", "explanation": "这里应该用〈发电时长〉。小时是时间单位，发电设备运行了多久要说发电时长；发电量是电能总量，用千瓦时计。"}, {"text": "这块电池的发电量是一千毫安时。", "explanation": "这里应该用〈容量〉。毫安时表示电池能储存多少电，要说容量；电池只储存电能，不产生电能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13721, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发电量", "is_correct": true, "explanation": "正确。电能的总量以千瓦时计算，与“发电量”相符。"}, {"text": "电压", "is_correct": false, "explanation": "搭配：“电压”用伏特计量，不能与“千瓦时”搭配。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度用摄氏度计量，不以电能单位计算。"}, {"text": "时长", "is_correct": false, "explanation": "语义：时长用时间单位计量，“千瓦时”是电能单位，两者不相容。"}], "explanations": {"发电量": "正确。电能的总量以千瓦时计算，与“发电量”相符。", "电压": "搭配：“电压”用伏特计量，不能与“千瓦时”搭配。", "温度": "语义：温度用摄氏度计量，不以电能单位计算。", "时长": "语义：时长用时间单位计量，“千瓦时”是电能单位，两者不相容。"}, "sentence_index": 6, "correct_answer": "发电量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条线路的发电量是二百二十伏。", "explanation": "这里应该用〈电压〉。伏是电压的单位，线路两端的电压要说电压；发电量是电能总量。"}, {"text": "这台发动机的发电量是八十摄氏度。", "explanation": "这里应该用〈温度〉。摄氏度是温度单位，发动机的冷热程度要说温度。"}, {"text": "这个月的发电量是三百元。", "explanation": "这里应该用〈电费〉。元是货币单位，用电要付的钱要说电费；发电量是电能，不用钱计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座风电场今年的发电量跟去年多两成。", "corrected_sentence": "这座风电场今年的发电量比去年多两成。", "error_description": "比较词误用：比较多少要用“比”，“跟”不能引出比较对象。正确形式为“发电量比去年多两成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个电站的发电量增加地很快。", "corrected_sentence": "这个电站的发电量增加得很快。", "error_description": "结构助词误用：“增加”后引出补语须用“得”，不能用“地”。正确形式为“增加得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
