INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13722, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "风能是指空气流动所产生的动能，是一种清洁、可再生的能源，通常用于风力发电。", "primary_collocate": null, "pronunciation": "fēng néng", "ipa": "fɤŋ˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "风能技术同样经历范式革命。", "target_word": "风能", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "风能是一种干净的能源。", "target_word": "风能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个地方风大，适合用风能发电。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风能不会用完，也不会污染空气。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想用风能给村子送电。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风能越来越便宜，很多国家都在用。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风吹动叶片产生的能量就是风能。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方的风很大，风能很丰富。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近有一座用风能发电的小站。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和煤比起来，风能对环境好得多。", "target_word": "风能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "風能", "label": "繁体"}, {"form": "风能发电", "label": "复合"}], "register": "书面", "sense_fingerprint": "空气流动产生的动能，清洁可再生的能源，用于风力发电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef9cf912-3233-4a4e-8b9e-0ce8bdd8a849') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风能", "is_correct": true, "explanation": "风能指空气流动产生的动能，作“技术”的修饰语，符合“同样经历范式革命”的语境。"}, {"text": "风景", "is_correct": false, "explanation": "语义：风景指自然景致，不是能源，“风景技术”说不通。"}, {"text": "风险", "is_correct": false, "explanation": "搭配：“风险”说的是危害，不能修饰“技术”，应说“风险管理”。"}, {"text": "风俗", "is_correct": false, "explanation": "语义：风俗指社会习惯，与科学技术无关，句子无法成立。"}], "explanations": {"风能": "风能指空气流动产生的动能，作“技术”的修饰语，符合“同样经历范式革命”的语境。", "风景": "语义：风景指自然景致，不是能源，“风景技术”说不通。", "风险": "搭配：“风险”说的是危害，不能修饰“技术”，应说“风险管理”。", "风俗": "语义：风俗指社会习惯，与科学技术无关，句子无法成立。"}, "sentence_index": 0, "correct_answer": "风能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片海边的风能场有两百台风车。", "explanation": "这里应该用〈风电场〉。风能指能量，成片的发电设施叫风电场，不说“风能场”。"}, {"text": "今天的风能越来越快。", "explanation": "这里应该用〈风速〉。描述风的快慢要用风速；风能是能量，不说“快”或“慢”。"}, {"text": "风能吹得树摇摇晃晃。", "explanation": "这里应该用〈风〉。风能指风的能量，不会直接吹动树，吹树的是风本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风能", "is_correct": true, "explanation": "风能是风吹动叶片产生的能量，与句中的定义相符。"}, {"text": "风速", "is_correct": false, "explanation": "语义：风速指风的快慢，是速度，不是能量，“能量就是风速”不成立。"}, {"text": "风筝", "is_correct": false, "explanation": "语义：风筝是玩具，不是能量，与句中的定义相矛盾。"}, {"text": "风雨", "is_correct": false, "explanation": "搭配：“风雨”多指困难或恶劣天气，不能用“就是”来定义“能量”。"}], "explanations": {"风能": "风能是风吹动叶片产生的能量，与句中的定义相符。", "风速": "语义：风速指风的快慢，是速度，不是能量，“能量就是风速”不成立。", "风筝": "语义：风筝是玩具，不是能量，与句中的定义相矛盾。", "风雨": "搭配：“风雨”多指困难或恶劣天气，不能用“就是”来定义“能量”。"}, "sentence_index": 6, "correct_answer": "风能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "草原上的风能转个不停。", "explanation": "这里应该用〈风车〉。风车靠风转动，风能是能量，本身不会转。"}, {"text": "我家买了一台风能，用来发电。", "explanation": "这里应该用〈种〉。风能是能源类别，量词用“种”，“台”指机器。"}, {"text": "这场风能吹倒了很多树，很危险。", "explanation": "这里应该用〈风暴〉。风暴会造成树倒、船沉，风能是能量，不能直接造成破坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村子的电来自一只风能。", "corrected_sentence": "我们村子的电来自一种风能。", "error_description": "“风能”是能源类名词，量词应用“种”，不能用“只”（“只”多用于动物或单个物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小站用风能很发电。", "corrected_sentence": "这个小站用风能发电。", "error_description": "“很”是程度副词，不能修饰动词“发电”，应删去“很”，说“用风能发电”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13723, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "垂直", "is_correct": true, "explanation": "“垂直”与“水平”是一对反义词，指与地面成直角的方向。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”指地球上方的空间，不表示方向，与“水平”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”指水流的通道，与“水平”的方向义不构成反义。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”指大面积的海水，与“水平”的方向义无关。"}], "correct_answer": "垂直", "explanations": {"垂直": "“垂直”与“水平”是一对反义词，指与地面成直角的方向。", "天空": "语义：“天空”指地球上方的空间，不表示方向，与“水平”没有反义关系。", "河流": "语义：“河流”指水流的通道，与“水平”的方向义不构成反义。", "海洋": "语义：“海洋”指大面积的海水，与“水平”的方向义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13723, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "垂直", "is_correct": true, "explanation": "“垂直”与“水平”是一对反义词，指与地面成直角的方向。"}, {"text": "森林", "is_correct": false, "explanation": "语义：“森林”指大片树木组成的地域，与“水平”的方向义无关。"}, {"text": "草原", "is_correct": false, "explanation": "语义：“草原”指长满草的平坦地带，与“水平”不构成反义。"}, {"text": "山峰", "is_correct": false, "explanation": "语义：“山峰”指山的最高处，不是方向词，与“水平”没有反义关系。"}], "correct_answer": "垂直", "explanations": {"垂直": "“垂直”与“水平”是一对反义词，指与地面成直角的方向。", "森林": "语义：“森林”指大片树木组成的地域，与“水平”的方向义无关。", "草原": "语义：“草原”指长满草的平坦地带，与“水平”不构成反义。", "山峰": "语义：“山峰”指山的最高处，不是方向词，与“水平”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13723, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "与地面平行、不倾斜的。", "primary_collocate": null, "pronunciation": "shuǐ píng", "ipa": "ʂweɪ˨˩˦ pʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这条线是水平的。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在空中水平飞行。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在检查桌子是不是水平。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手臂水平地举起来。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在纸上画一条水平的线。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子不水平，杯子会滑下去。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把双手水平伸向前方。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面总是水平的。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镜子挂得不水平，看着很难受。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水平方向和垂直方向不一样。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水平线", "label": "复合"}, {"form": "水平面", "label": "复合"}], "register": "中性", "sense_fingerprint": "水平：与地面平行的方向或位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35ae327-211b-4fbe-844b-b4c09f23498b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13723, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水平", "is_correct": true, "explanation": "“水平”在此指与地面平行的方向，用来说明线的走向，句意通顺。"}, {"text": "天空", "is_correct": false, "explanation": "语义：线的走向不能用“天空”来描述，天空不是线的属性。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”是一大片水域，不能作为线的方向。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“是……的”要说线的形状或走向，“颜色”不能用来说线的方向。"}], "explanations": {"水平": "“水平”在此指与地面平行的方向，用来说明线的走向，句意通顺。", "天空": "语义：线的走向不能用“天空”来描述，天空不是线的属性。", "海洋": "语义：“海洋”是一大片水域，不能作为线的方向。", "颜色": "搭配：“是……的”要说线的形状或走向，“颜色”不能用来说线的方向。"}, "sentence_index": 0, "correct_answer": "水平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的水平在班里是最高的。", "explanation": "这是“水平”的另一个义项（能力达到的程度），与本义项“与地面平行”无关。"}, {"text": "他的游泳水平很高。", "explanation": "这是“水平”的另一个义项（能力达到的程度），与“与地面平行”无关。"}, {"text": "把柱子水平立起来。", "explanation": "这里应该用〈竖直〉。立起来的柱子是竖直的，“水平”指与地面平行，不能用来描述立起的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水平", "is_correct": true, "explanation": "“水平”修饰“伸”，表示手臂与地面平行地伸出，符合句意。"}, {"text": "向后", "is_correct": false, "explanation": "语义：“向后”与“伸向前方”方向相反，句子自相矛盾。"}, {"text": "向下", "is_correct": false, "explanation": "语义：“向下”与“向前方”方向不同，句中两个方向冲突。"}, {"text": "倒退着", "is_correct": false, "explanation": "搭配：“伸”不与“倒退着”搭配，倒退是走路的方式，不能说明手的伸法。"}], "explanations": {"水平": "“水平”修饰“伸”，表示手臂与地面平行地伸出，符合句意。", "向后": "语义：“向后”与“伸向前方”方向相反，句子自相矛盾。", "向下": "语义：“向下”与“向前方”方向不同，句中两个方向冲突。", "倒退着": "搭配：“伸”不与“倒退着”搭配，倒退是走路的方式，不能说明手的伸法。"}, "sentence_index": 6, "correct_answer": "水平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条水平很长。", "explanation": "这里应该用〈直线〉。“水平”指与地面平行的方向或位置，不能作为一条线的名称。"}, {"text": "他水平着站在那里。", "explanation": "这里应该用〈直立〉。人站立时身体是竖直的，“水平”指与地面平行，不能用来描述站立。"}, {"text": "这块斜面很水平。", "explanation": "这里应该用〈倾斜〉。斜面本身是倾斜的，不能说它是水平的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把木板水平的放在桌子上。", "corrected_sentence": "他把木板水平地放在桌子上。", "error_description": "状语标记错误：“水平”修饰动词“放”，是方式状语，应用“地”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书架要摆地水平。", "corrected_sentence": "书架要摆得水平。", "error_description": "补语标记错误：“摆”后的补语要用“得”引出，应说“摆得水平”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
