INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13724, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "圆柱形零件，用于支撑轮子或传递动力。", "primary_collocate": null, "pronunciation": "zhóu", "ipa": "ʈʂou˧˥", "syllable_count": 1, "sentences": [{"text": "传统风车的水平轴结构被保留，但空气动力学模拟与复合材料的应用，使叶片长度突破百米级，扫风面积呈几何倍数增长。", "target_word": "轴", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这根轴断了，车轮不转了。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮子套在轴上，才能转起来。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人给机器的轴上了油。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根轴很粗，能承受很大的力。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电机的轴带动着风扇转动。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把旧轴换成了新轴。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轴转得太快，机器开始发热。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢做的轴比木头做的更结实。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风车的轴把动力传给发电机。", "target_word": "轴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "车轴", "label": "复合"}, {"form": "轴承", "label": "复合"}, {"form": "軸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机械中支撑轮子、传递动力的圆柱形零件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb540fec-9cec-4bcb-8643-5a997deb09c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13724, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。zhóu（第二声）指机械中支撑轮子、传递动力的圆柱形零件。"}, {"text": "周", "is_correct": false, "explanation": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是周围、周期。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 zhóu（第二声）声调不同，意思是手臂中间的关节。"}, {"text": "愁", "is_correct": false, "explanation": "chóu 与 zhóu 声母不同（ch 与 zh），意思是忧愁。"}, {"text": "皱", "is_correct": false, "explanation": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是衣物或皮肤上的褶痕。"}], "explanations": {"轴": "正确。zhóu（第二声）指机械中支撑轮子、传递动力的圆柱形零件。", "周": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是周围、周期。", "肘": "zhǒu（第三声）与 zhóu（第二声）声调不同，意思是手臂中间的关节。", "愁": "chóu 与 zhóu 声母不同（ch 与 zh），意思是忧愁。", "皱": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是衣物或皮肤上的褶痕。"}, "sentence_index": null, "correct_answer": "轴"}, "level_3": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。「轴」指机械中支撑轮子、传递动力的零件，符合风车水平结构的语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不承担支撑或传动作用，与风车的水平结构不符。"}, {"text": "围墙", "is_correct": false, "explanation": "语义：围墙是围挡用的墙体，与风车的传动结构无关。"}, {"text": "台阶", "is_correct": false, "explanation": "体貌：台阶呈阶梯状，不是水平的圆柱形传动件。"}], "explanations": {"轴": "正确。「轴」指机械中支撑轮子、传递动力的零件，符合风车水平结构的语境。", "窗户": "语义：窗户不承担支撑或传动作用，与风车的水平结构不符。", "围墙": "语义：围墙是围挡用的墙体，与风车的传动结构无关。", "台阶": "体貌：台阶呈阶梯状，不是水平的圆柱形传动件。"}, "sentence_index": 0, "correct_answer": "轴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用一根铁轴撑住了屋顶。", "explanation": "这里应该用〈铁杆〉。轴是支撑轮子、传递动力的零件，撑屋顶的长条要用「杆」。"}, {"text": "这座桥由几根石轴支撑。", "explanation": "这里应该用〈石柱〉。轴是支撑轮子、传递动力的零件，桥的支柱要用「柱」。"}, {"text": "他拿着一根木轴敲了敲门。", "explanation": "这里应该用〈木棍〉。轴是圆柱形传动零件，拿在手里敲门的棍子要用「棍」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13724, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。zhóu（第二声）指机械中支撑轮子、传递动力的圆柱形零件。"}, {"text": "粥", "is_correct": false, "explanation": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是稀饭。"}, {"text": "昼", "is_correct": false, "explanation": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是白天。"}, {"text": "筹", "is_correct": false, "explanation": "chóu 与 zhóu 声母不同（ch 与 zh），意思是筹划、筹集。"}, {"text": "州", "is_correct": false, "explanation": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是行政区划。"}], "explanations": {"轴": "正确。zhóu（第二声）指机械中支撑轮子、传递动力的圆柱形零件。", "粥": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是稀饭。", "昼": "zhòu（第四声）与 zhóu（第二声）声调不同，意思是白天。", "筹": "chóu 与 zhóu 声母不同（ch 与 zh），意思是筹划、筹集。", "州": "zhōu（第一声）与 zhóu（第二声）声调不同，意思是行政区划。"}, "sentence_index": null, "correct_answer": "轴"}, "level_3": {"options": [{"text": "轴", "is_correct": true, "explanation": "正确。「轴」指机械中的传动零件，与「换成了新轴」的说法相合。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡与句中的「新轴」不是同类零件，换成这样的说法不通。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗是餐具，无法与「新轴」对换，语境不符。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：皮鞋是穿着的物品，不与「换成新轴」这种机械说法搭配。"}], "explanations": {"轴": "正确。「轴」指机械中的传动零件，与「换成了新轴」的说法相合。", "灯泡": "语义：灯泡与句中的「新轴」不是同类零件，换成这样的说法不通。", "碗": "语义：碗是餐具，无法与「新轴」对换，语境不符。", "皮鞋": "搭配：皮鞋是穿着的物品，不与「换成新轴」这种机械说法搭配。"}, "sentence_index": 6, "correct_answer": "轴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "渔民用一根粗轴拴住了小船。", "explanation": "这里应该用〈绳子〉。轴是支撑轮子、传递动力的零件，拴船要用「绳子」。"}, {"text": "他用两根木轴搭起了屋子。", "explanation": "这里应该用〈木梁〉。轴是圆柱形零件，搭屋顶的横木要用「梁」。"}, {"text": "老人拄着一根铁轴走路。", "explanation": "这里应该用〈拐杖〉。轴是传动零件，拄着走路要用「拐杖」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台发动机里有一只轴断了。", "corrected_sentence": "这台发动机里有一根轴断了。", "error_description": "量词错误：轴是细长的棍状零件，应用「根」，「只」多用于动物。「一只轴」应改为「一根轴」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给车床换了一颗新轴。", "corrected_sentence": "他给车床换了一根新轴。", "error_description": "量词错误：轴是细长的棍状零件，应用「根」，「颗」多用于小而圆的东西。「一颗新轴」应改为「一根新轴」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
