INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "长度是物体在空间上两端之间的距离。", "primary_collocate": null, "pronunciation": "cháng dù", "ipa": "ʈʂʰɑŋ˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "传统风车的水平轴结构被保留，但空气动力学模拟与复合材料的应用，使叶片长度突破百米级，扫风面积呈几何倍数增长。", "target_word": "长度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条河的长度有三百公里。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请量一下这块布的长度。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的长度是两米。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的长度超过一千米。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道这根绳子的长度。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子的长度太短，穿着不舒服。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把木板剪成同样的长度。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头发的长度刚到肩膀。", "target_word": "长度", "complexity_tier": "T3", "furigana": "tā tóufa de chángdù gāng dào jiānbǎng", "sentence_source": "generated"}, {"text": "这两条鱼长度差不多。", "target_word": "长度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "长度单位", "label": "复合"}, {"form": "長度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体两端之间的空间距离，可以测量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb540fec-9cec-4bcb-8643-5a997deb09c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "长度", "is_correct": true, "explanation": "正确。长度指物体两端之间的距离，读 cháng dù。"}, {"text": "长途", "is_correct": false, "explanation": "tú（第二声）与 dù（第四声）声母与声调都不同，意思是远距离的路程。"}, {"text": "长处", "is_correct": false, "explanation": "chù 与 dù 声母不同（ch 与 d），声调相同（第四声），意思是优点。"}, {"text": "长裤", "is_correct": false, "explanation": "kù 与 dù 声母不同（k 与 d），声调相同（第四声），意思是长的裤子。"}], "explanations": {"长度": "正确。长度指物体两端之间的距离，读 cháng dù。", "长途": "tú（第二声）与 dù（第四声）声母与声调都不同，意思是远距离的路程。", "长处": "chù 与 dù 声母不同（ch 与 d），声调相同（第四声），意思是优点。", "长裤": "kù 与 dù 声母不同（k 与 d），声调相同（第四声），意思是长的裤子。"}, "sentence_index": null, "correct_answer": "长度"}, "level_3": {"options": [{"text": "长度", "is_correct": true, "explanation": "正确。“长度”指叶片两端之间的距离，与“突破百米级”的尺度相符。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量以千克计，不能与“百米级”这样的长度尺度搭配。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”说升高或降低，不能说“突破百米级”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格以金额计算，与“百米级”的长度单位不相容。"}], "explanations": {"长度": "正确。“长度”指叶片两端之间的距离，与“突破百米级”的尺度相符。", "重量": "语义：重量以千克计，不能与“百米级”这样的长度尺度搭配。", "温度": "搭配：“温度”说升高或降低，不能说“突破百米级”。", "价格": "语义：价格以金额计算，与“百米级”的长度单位不相容。"}, "sentence_index": 0, "correct_answer": "长度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的长度是一米八。", "explanation": "这里应该用〈身高〉。长度指物体两端之间的距离，人的高矮要说身高。"}, {"text": "两座城市的长度是三百公里。", "explanation": "这里应该用〈距离〉。长度说物体自身的长短，两地之间的远近要用距离。"}, {"text": "这口井的长度是十米。", "explanation": "这里应该用〈深度〉。井是从地面向下挖的，从上到下的深浅要说深度；长度只用于两端之间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "长度", "is_correct": true, "explanation": "正确。长度指物体两端之间的距离，读 cháng dù。"}, {"text": "长路", "is_correct": false, "explanation": "lù 与 dù 声母不同（l 与 d），声调相同（第四声），意思是很长的道路。"}, {"text": "长短", "is_correct": false, "explanation": "duǎn（第三声）与 dù（第四声）韵母与声调都不同，意思是长和短。"}, {"text": "长笛", "is_correct": false, "explanation": "dí（第二声）与 dù（第四声）韵母与声调不同，意思是一种管乐器。"}, {"text": "长大", "is_correct": false, "explanation": "dà（第四声）与 dù 韵母不同（a 与 u），声调相同，意思是人或动物长成大人或变大。"}], "explanations": {"长度": "正确。长度指物体两端之间的距离，读 cháng dù。", "长路": "lù 与 dù 声母不同（l 与 d），声调相同（第四声），意思是很长的道路。", "长短": "duǎn（第三声）与 dù（第四声）韵母与声调都不同，意思是长和短。", "长笛": "dí（第二声）与 dù（第四声）韵母与声调不同，意思是一种管乐器。", "长大": "dà（第四声）与 dù 韵母不同（a 与 u），声调相同，意思是人或动物长成大人或变大。"}, "sentence_index": null, "correct_answer": "长度"}, "level_3": {"options": [{"text": "长度", "is_correct": true, "explanation": "正确。这里说裤子的长短，“太短”正好与长度搭配。"}, {"text": "宽度", "is_correct": false, "explanation": "搭配：“宽度”只说宽窄，不说长短，这里不能说“太短”。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色没有长短之分，不能用“太短”来描述裤子。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能用长短来描述，与“太短”的意思矛盾。"}], "explanations": {"长度": "正确。这里说裤子的长短，“太短”正好与长度搭配。", "宽度": "搭配：“宽度”只说宽窄，不说长短，这里不能说“太短”。", "颜色": "体貌：颜色没有长短之分，不能用“太短”来描述裤子。", "味道": "语义：味道不能用长短来描述，与“太短”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "长度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的长度是两个小时。", "explanation": "这里应该用〈时长〉。长度只用于空间上的长短，比赛持续的时间要说时长。"}, {"text": "这只猫的长度是四公斤。", "explanation": "这里应该用〈体重〉。公斤是重量单位，猫的重量要说体重，长度指两端之间的距离。"}, {"text": "这间屋子的长度是二十五摄氏度。", "explanation": "这里应该用〈温度〉。摄氏度是温度单位，屋子的冷热程度要说温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根木棍的长度跟那根短一些。", "corrected_sentence": "这根木棍的长度比那根短一些。", "error_description": "比较词误用：比较长短要用“比”，“跟”不能引出比较对象。正确形式为“这根木棍的长度比那根短一些”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两根管子的长度差地不多。", "corrected_sentence": "这两根管子的长度差得不多。", "error_description": "结构助词误用：“差”后引出补语须用“得”，不能用“地”。正确形式为“差得不多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
