INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指空调、风扇等设备的风向自动左右摆动的功能，使空气流动更均匀。", "primary_collocate": null, "pronunciation": "sǎo fēng", "ipa": "sɑʊ˨˩˦ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这台空调的扫风让冷气均匀地吹向整个房间，不再只吹一个地方。", "target_word": "扫风", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这台空调有扫风功能。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我喜欢开着扫风。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开扫风，房间凉得更均匀。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调的扫风坏了，只能吹一边。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遥控器上的扫风键在哪儿？", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉时我会关掉扫风。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开了扫风以后，风不再直吹我了。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个风扇也有扫风功能吗？", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扫风让整个客厅都凉快了。", "target_word": "扫风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "空调风扇风向自动左右摆动的功能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff80419-2652-460d-9a29-0cfc782ab013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扫风", "is_correct": true, "explanation": "正确：“扫风”指风向左右摆动的功能，正是它让冷气均匀地吹向整个房间。"}, {"text": "定时", "is_correct": false, "explanation": "搭配：“定时”指设定开关时间，不能让冷气均匀地吹送。"}, {"text": "除湿", "is_correct": false, "explanation": "语义：“除湿”指降低空气湿度，与冷气的吹送方向无关。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：“睡眠”指睡眠模式，本身不能让冷气均匀吹送，句意不通。"}], "explanations": {"扫风": "正确：“扫风”指风向左右摆动的功能，正是它让冷气均匀地吹向整个房间。", "定时": "搭配：“定时”指设定开关时间，不能让冷气均匀地吹送。", "除湿": "语义：“除湿”指降低空气湿度，与冷气的吹送方向无关。", "睡眠": "语义：“睡眠”指睡眠模式，本身不能让冷气均匀吹送，句意不通。"}, "sentence_index": 0, "correct_answer": "扫风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用扫帚扫风，把客厅打扫干净了。", "explanation": "错用：“扫风”指空调或风扇的风向左右摆动，不是用扫帚清扫的动作。"}, {"text": "这棵树的扫风很好看。", "explanation": "错用：把“扫风”用成了树的特征。它只指空调或风扇的风向左右摆动，树木的枝叶只能说〈摇曳〉。"}, {"text": "这本书的扫风很精彩。", "explanation": "错用：“扫风”指设备的风向摆动，不能用来评价书的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扫风", "is_correct": true, "explanation": "正确：“关掉扫风”指关闭空调的风向摆动功能，符合睡觉时的情境。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“关掉”不能用于“早餐”，应说“吃掉”或“吃完”。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“关掉”不能用于“脚步”，脚步不能被关闭。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：“关掉报纸”表示关闭报纸这种物品，与睡觉时关闭设备的语境不符。"}], "explanations": {"扫风": "正确：“关掉扫风”指关闭空调的风向摆动功能，符合睡觉时的情境。", "早餐": "搭配：“关掉”不能用于“早餐”，应说“吃掉”或“吃完”。", "脚步": "搭配：“关掉”不能用于“脚步”，脚步不能被关闭。", "报纸": "语义：“关掉报纸”表示关闭报纸这种物品，与睡觉时关闭设备的语境不符。"}, "sentence_index": 6, "correct_answer": "扫风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们用扫风把地板扫干净了。", "explanation": "错用：“扫风”指设备的风向摆动，不是用来清扫地板的工具或动作。"}, {"text": "扫风的味道很香。", "explanation": "错用：“扫风”是设备的功能，不能用来描述气味。"}, {"text": "妈妈拿扇子给我扫风。", "explanation": "这里应该用〈扇风〉。扫风指空调或风扇的风向左右摆动，不是拿扇子来回扇动的动作；手动扇凉要说〈扇风〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台空调有一台扫风功能。", "corrected_sentence": "这台空调有一种扫风功能。", "error_description": "“扫风功能”的量词应用“种”，不能用“台”（“台”用于机器本身）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每次都扫风。", "corrected_sentence": "我每次都开扫风。", "error_description": "“扫风”是名词，作宾语前需要动词“开”，漏掉“开”就不能表示打开这个功能。正确形式是“我每次都开扫风”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
