INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13729, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用风力驱动风轮叶片旋转，带动发电机发电的场所。", "primary_collocate": null, "pronunciation": "fēng diàn chǎng", "ipa": "fɤŋ˥ tjɛn˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "海上风电场的兴起更将发电装置迁移至风力更稳定强劲的大陆架区域。", "target_word": "风电场", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "风电场建在海边，那里风很大。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座风电场有五十台大风车。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐车去参观了一座风电场。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风电场每年能为十万个家庭提供电。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在风电场检查发电机。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个风电场的叶片很长，风一吹就转个不停。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当地政府决定再建一座风电场。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风电场的叶片转得很慢，但很稳。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他毕业后到风电场工作了。", "target_word": "风电场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "海上风电场", "label": "复合"}, {"form": "風電場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "利用风力带动发电机发电的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31173b25-2d4d-4630-a105-47245d8daad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13729, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风电场", "is_correct": true, "explanation": "正确：“风电场”是利用风力发电的场所，与“风力更稳定强劲”的语境一致。"}, {"text": "水电站", "is_correct": false, "explanation": "语义：“水电站”靠水流发电，与句中强调的风力相矛盾。"}, {"text": "火电厂", "is_correct": false, "explanation": "搭配：“海上火电厂”不是常见说法，且火电厂靠燃料发电，与“风力”无关。"}, {"text": "养殖场", "is_correct": false, "explanation": "语义：“养殖场”是养殖的地方，与“发电装置”和“风力”无关，不能迁移至大陆架发电。"}], "explanations": {"风电场": "正确：“风电场”是利用风力发电的场所，与“风力更稳定强劲”的语境一致。", "水电站": "语义：“水电站”靠水流发电，与句中强调的风力相矛盾。", "火电厂": "搭配：“海上火电厂”不是常见说法，且火电厂靠燃料发电，与“风力”无关。", "养殖场": "语义：“养殖场”是养殖的地方，与“发电装置”和“风力”无关，不能迁移至大陆架发电。"}, "sentence_index": 0, "correct_answer": "风电场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家院子里有一座风电场，我们一家人就住在里面。", "explanation": "这里应该用〈住宅〉。风电场是发电的场所，不住人；供一家人居住的要用“住宅”。"}, {"text": "村边的这座风电场是农民用来磨面的。", "explanation": "这里应该用〈风车〉。风车可以用来磨面，风电场是利用风力发电的场所，不能用来磨面。"}, {"text": "这座风电场烧煤发电，污染很大。", "explanation": "这里应该用〈火电厂〉。风电场利用风力发电，不烧煤；烧煤发电的是火电厂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风电场", "is_correct": true, "explanation": "正确：“风电场”的风机叶片在风中转动发电，与句中“叶片很长，风一吹就转”相合。"}, {"text": "停车场", "is_correct": false, "explanation": "搭配：停车场没有叶片，不说“这个停车场的叶片很长”。"}, {"text": "养鸡场", "is_correct": false, "explanation": "语义：养鸡场不具备随风转动的大叶片，与句中的描述不符。"}, {"text": "水族馆", "is_correct": false, "explanation": "语义：水族馆展示水生动物，没有随风转动的叶片，与句意无关。"}], "explanations": {"风电场": "正确：“风电场”的风机叶片在风中转动发电，与句中“叶片很长，风一吹就转”相合。", "停车场": "搭配：停车场没有叶片，不说“这个停车场的叶片很长”。", "养鸡场": "语义：养鸡场不具备随风转动的大叶片，与句中的描述不符。", "水族馆": "语义：水族馆展示水生动物，没有随风转动的叶片，与句意无关。"}, "sentence_index": 6, "correct_answer": "风电场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民用风电场抽水，很省力。", "explanation": "这里应该用〈水车〉。风电场是发电的场所，不能用来抽水；抽水要用“水车”。"}, {"text": "这座风电场靠水流发电。", "explanation": "这里应该用〈水电站〉。风电场靠风力发电，不靠水流；靠水流发电的是水电站。"}, {"text": "我们在风电场里上课，老师讲得很认真。", "explanation": "这里应该用〈学校〉。风电场是发电的场所，不能用来上课；上课要在学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片海边新建了一台风电场，每年能发很多电。", "corrected_sentence": "这片海边新建了一座风电场，每年能发很多电。", "error_description": "错误形式：一台风电场；正确形式：一座风电场。量词“台”用于机器，风电场是场所，应用“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家附近的座风电场已经投入使用。", "corrected_sentence": "我家附近的一座风电场已经投入使用。", "error_description": "错误形式：我家附近的座风电场；正确形式：我家附近的一座风电场。量词“座”单独使用时前面需要数词或指示词，应补上“一”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
