INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13730, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指人或事物从一处转移到另一处，常指居住地或工作地点的改变。", "primary_collocate": null, "pronunciation": "qiān yí", "ipa": "tɕʰjɛn˥ i˧˥", "syllable_count": 2, "sentences": [{"text": "海上风电场的兴起更将发电装置迁移至风力更稳定强劲的大陆架区域。", "target_word": "迁移", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这意味着，同一代理可在不同计算平台间无缝迁移，其长期记忆与行为模式不受底层模型更迭的影响。", "target_word": "迁移", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司明年要迁移到新的工业园区。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "候鸟每年秋天都向南迁移。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护环境，政府要求工厂迁移。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多居民因为水库建设而迁移到外地。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把数据中心迁移到了南方。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员发现这些鱼群正在向北迁移。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子几十年前迁移过一次。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校迁移后，学生上学更方便了。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迁移了", "label": "完成体"}, {"form": "迁移过", "label": "经历体"}, {"form": "数据迁移", "label": "复合词"}, {"form": "遷移", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人或事物从一处转移到另一处（居住地、工作地点、装置、数据）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6fe7c9-33e8-4c2f-b2e6-ccbf82b54954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迁移", "is_correct": true, "explanation": "迁移（qiān yí）指人或事物从一处转移到另一处，是本题的目标词。"}, {"text": "前移", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，前移意思是向前挪动，不是迁移。"}, {"text": "歉意", "is_correct": false, "explanation": "qiàn（第四声）与 qiān（第一声）声调不同，歉意指抱歉的心情。"}, {"text": "千亿", "is_correct": false, "explanation": "第二个音节 yì（第四声）与 yí（第二声）声调不同，千亿是数目。"}, {"text": "浅易", "is_correct": false, "explanation": "qiǎn（第三声）与 qiān（第一声）声调不同，yì 与 yí 声调也不同，意思是浅显容易。"}], "explanations": {"迁移": "迁移（qiān yí）指人或事物从一处转移到另一处，是本题的目标词。", "前移": "qián（第二声）与 qiān（第一声）声调不同，前移意思是向前挪动，不是迁移。", "歉意": "qiàn（第四声）与 qiān（第一声）声调不同，歉意指抱歉的心情。", "千亿": "第二个音节 yì（第四声）与 yí（第二声）声调不同，千亿是数目。", "浅易": "qiǎn（第三声）与 qiān（第一声）声调不同，yì 与 yí 声调也不同，意思是浅显容易。"}, "sentence_index": null, "correct_answer": "迁移"}, "level_3": {"options": [{"text": "迁移", "is_correct": true, "explanation": "迁移至：指装置从一处转移到另一处，符合句中的发电装置与地点。"}, {"text": "削减", "is_correct": false, "explanation": "语义：削减指减少数量，与把装置转移到某区域的意思不符。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉、去除，不是把装置转移到另一处，与句意不符。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：隐藏是藏起来，句中要表达的是位置的转移。"}], "explanations": {"迁移": "迁移至：指装置从一处转移到另一处，符合句中的发电装置与地点。", "削减": "语义：削减指减少数量，与把装置转移到某区域的意思不符。", "拆除": "语义：“拆除”指拆掉、去除，不是把装置转移到另一处，与句意不符。", "隐藏": "语义：隐藏是藏起来，句中要表达的是位置的转移。"}, "sentence_index": 0, "correct_answer": "迁移"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心情从悲伤迁移为快乐。", "explanation": "这里应该用〈转变〉。迁移指人或事物从一处到另一处的位置转移，心情的变化要说转变。"}, {"text": "这个城市的经济迁移得很快。", "explanation": "这里应该用〈发展〉。迁移不用于经济或状态的进步，经济的变化要说发展。"}, {"text": "我的生日迁移到了下周。", "explanation": "这里应该用〈推迟〉。日期和日程不能迁移，改期要用推迟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13730, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "迁移", "is_correct": true, "explanation": "迁移（qiān yí）指人或事物从一处转移到另一处，是本题的目标词。"}, {"text": "千亿", "is_correct": false, "explanation": "第一音节 qiān 与目标相同，第二音节 yì（第四声）与 yí（第二声）声调不同；千亿是数目。"}, {"text": "谦逸", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，谦逸意思是谦虚、不张扬。"}, {"text": "潜移", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，潜移意思是暗中逐渐改变。"}], "explanations": {"迁移": "迁移（qiān yí）指人或事物从一处转移到另一处，是本题的目标词。", "千亿": "第一音节 qiān 与目标相同，第二音节 yì（第四声）与 yí（第二声）声调不同；千亿是数目。", "谦逸": "yì（第四声）与 yí（第二声）声调不同，谦逸意思是谦虚、不张扬。", "潜移": "qián（第二声）与 qiān（第一声）声调不同，潜移意思是暗中逐渐改变。"}, "sentence_index": null, "correct_answer": "迁移"}, "level_3": {"options": [{"text": "迁移", "is_correct": true, "explanation": "迁移到：指数据中心从一处迁到另一处，符合句中的对象与地点。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：凝固指液体变成固体，数据中心不能凝固到某地。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：熄灭多用于火、灯，不能用于数据中心。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：咀嚼指用牙齿把食物嚼碎，与数据中心的转移不符。"}], "explanations": {"迁移": "迁移到：指数据中心从一处迁到另一处，符合句中的对象与地点。", "凝固": "语义：凝固指液体变成固体，数据中心不能凝固到某地。", "熄灭": "搭配：熄灭多用于火、灯，不能用于数据中心。", "咀嚼": "语义：咀嚼指用牙齿把食物嚼碎，与数据中心的转移不符。"}, "sentence_index": 6, "correct_answer": "迁移"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的病情迁移得很快。", "explanation": "这里应该用〈好转〉。病情的好转是状态变化，迁移指空间位置的改变。"}, {"text": "今天的气温迁移到了零下。", "explanation": "这里应该用〈降低〉。气温数值的下降要说降低，迁移不用于温度的变化。"}, {"text": "他迁移了全国纪录。", "explanation": "这里应该用〈打破〉。纪录要说打破，迁移不能用来表示超越成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这群鸟明年春天会迁移北方。", "corrected_sentence": "这群鸟明年春天会迁移到北方。", "error_description": "错误形式：「迁移北方」缺少介词「到」。正确形式：「迁移到北方」。表示动作移向某地时，要用「到」引出地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两家银行合并后，总部迁移了到上海。", "corrected_sentence": "两家银行合并后，总部迁移到了上海。", "error_description": "错误形式：「迁移了到上海」，「了」位置错误。正确形式：「迁移到了上海」。动词后的「了」要放在介词短语「到上海」之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13731, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微弱", "is_correct": true, "explanation": "正确：“微弱”与“强劲”相反，指力量小，与风的力量强大正相对。"}, {"text": "平稳", "is_correct": false, "explanation": "“平稳”指平静稳定，不表示力量大小，与“强劲”不构成反义。"}, {"text": "潮湿", "is_correct": false, "explanation": "无关：潮湿描述空气或物体的水分，与力量强弱无关。"}, {"text": "缓慢", "is_correct": false, "explanation": "“缓慢”指速度慢，与风的力量强弱不构成反义。"}], "correct_answer": "微弱", "explanations": {"微弱": "正确：“微弱”与“强劲”相反，指力量小，与风的力量强大正相对。", "平稳": "“平稳”指平静稳定，不表示力量大小，与“强劲”不构成反义。", "潮湿": "无关：潮湿描述空气或物体的水分，与力量强弱无关。", "缓慢": "“缓慢”指速度慢，与风的力量强弱不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13731, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱", "is_correct": true, "explanation": "正确：“弱”与“强劲”相反，指力量小；马力弱与马力强劲正相对。"}, {"text": "迟缓", "is_correct": false, "explanation": "“迟缓”指速度慢，与马力的强弱不构成反义。"}, {"text": "平稳", "is_correct": false, "explanation": "“平稳”指稳定，不表示力量大小，不构成反义。"}, {"text": "柔和", "is_correct": false, "explanation": "“柔和”指性质温和，与力量强弱不构成反义。"}], "correct_answer": "弱", "explanations": {"弱": "正确：“弱”与“强劲”相反，指力量小；马力弱与马力强劲正相对。", "迟缓": "“迟缓”指速度慢，与马力的强弱不构成反义。", "平稳": "“平稳”指稳定，不表示力量大小，不构成反义。", "柔和": "“柔和”指性质温和，与力量强弱不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13731, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示力量强大，有劲。", "primary_collocate": null, "pronunciation": "qiáng jìn", "ipa": "tɕʰiɑŋ˧˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "海上风电场的兴起更将发电装置迁移至风力更稳定强劲的大陆架区域。", "target_word": "强劲", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "海边的风很强劲，我的帽子飞走了。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山顶的风太强劲，我们不敢往前走。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "强劲的北风吹了一整夜。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台车的动力很强劲，开得很快。", "target_word": "强劲", "complexity_tier": "T3", "furigana": "qiáng jìn", "sentence_source": "generated"}, {"text": "今天的风不够强劲，风车转得很慢。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "强劲的水流把小船冲到了远处。", "target_word": "强劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，强劲的寒风从北方吹过来。", "target_word": "强劲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风力强劲的地方，适合建风力发电站。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车的马力强劲，上坡一点也不慢。", "target_word": "强劲", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "強勁", "label": "繁体"}], "register": "书面", "sense_fingerprint": "风、水流、发动机等的力量强大、有劲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef9cf912-3233-4a4e-8b9e-0ce8bdd8a849') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13731, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强劲", "is_correct": true, "explanation": "正确：强劲，表示力量强大、有劲。"}, {"text": "前进", "is_correct": false, "explanation": "qián（第二声）与 qiáng 韵尾不同（-n 与 -ng），前进意思是向前移动。"}, {"text": "穷尽", "is_correct": false, "explanation": "jìn 相同，qióng 与 qiáng 主要元音不同（o 与 a），穷尽意思是用到没有剩余。"}, {"text": "详尽", "is_correct": false, "explanation": "xiáng 与 qiáng 声母不同（x 与 q），详尽意思是周密完整。"}], "explanations": {"强劲": "正确：强劲，表示力量强大、有劲。", "前进": "qián（第二声）与 qiáng 韵尾不同（-n 与 -ng），前进意思是向前移动。", "穷尽": "jìn 相同，qióng 与 qiáng 主要元音不同（o 与 a），穷尽意思是用到没有剩余。", "详尽": "xiáng 与 qiáng 声母不同（x 与 q），详尽意思是周密完整。"}, "sentence_index": null, "correct_answer": "强劲"}, "level_3": {"options": [{"text": "强劲", "is_correct": true, "explanation": "正确：强劲形容风力强大，与“风力更稳定”的描述一致。"}, {"text": "猛烈", "is_correct": false, "explanation": "语义：“猛烈”指剧烈、激烈，与“更稳定”互相矛盾。"}, {"text": "急促", "is_correct": false, "explanation": "搭配：“急促”多形容呼吸、节奏，不用来说风力，与“稳定”也矛盾。"}, {"text": "多变", "is_correct": false, "explanation": "语义：“多变”指变化多，与“更稳定”相矛盾。"}], "explanations": {"强劲": "正确：强劲形容风力强大，与“风力更稳定”的描述一致。", "猛烈": "语义：“猛烈”指剧烈、激烈，与“更稳定”互相矛盾。", "急促": "搭配：“急促”多形容呼吸、节奏，不用来说风力，与“稳定”也矛盾。", "多变": "语义：“多变”指变化多，与“更稳定”相矛盾。"}, "sentence_index": 0, "correct_answer": "强劲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对音乐有强劲的兴趣。", "explanation": "这里应该用〈强烈〉。强劲说的是风、水流、动力等力量大；“兴趣”的程度要用“强烈”。"}, {"text": "这个孩子的身体很强劲，从来不生病。", "explanation": "这里应该用〈强健〉。强劲不用来形容人的身体，身体健壮要说“强健”。"}, {"text": "她是一个强劲的人，遇到困难也不哭。", "explanation": "这里应该用〈坚强〉。强劲说的是力量，人的意志刚强要说“坚强”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13731, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强劲", "is_correct": true, "explanation": "正确：强劲形容水流力量大，能把小船冲到远处。"}, {"text": "平缓", "is_correct": false, "explanation": "语义：“平缓”指水势缓和，与“冲到了远处”相矛盾。"}, {"text": "微弱", "is_correct": false, "explanation": "语义：“微弱”指力量小，冲不到远处，与句意矛盾。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”通常只用于空气、物体，不能说“干燥的水流”，与“水流”搭配不当。"}], "explanations": {"强劲": "正确：强劲形容水流力量大，能把小船冲到远处。", "平缓": "语义：“平缓”指水势缓和，与“冲到了远处”相矛盾。", "微弱": "语义：“微弱”指力量小，冲不到远处，与句意矛盾。", "干燥": "搭配：“干燥”通常只用于空气、物体，不能说“干燥的水流”，与“水流”搭配不当。"}, "sentence_index": 6, "correct_answer": "强劲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的力气很强劲，走了两步就累倒了。", "explanation": "这里应该用〈弱〉。强劲说力量大，后半句“走了两步就累倒了”说明力气不足；力气不足要说“弱”。"}, {"text": "他的脚步很强劲，刚走进房间就摔倒了。", "explanation": "这里应该用〈无力〉。强劲说力量大，与“摔倒”矛盾；脚步无力要说“无力”。"}, {"text": "这位病人的呼吸很强劲，几乎说不出话。", "explanation": "这里应该用〈微弱〉。强劲说力量大，呼吸无力要说“微弱”，与“几乎说不出话”一致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一阵强劲地风刮了起来。", "corrected_sentence": "一阵强劲的风刮了起来。", "error_description": "“强劲”修饰名词“风”时要用结构助词“的”，不用“地”。“地”用于修饰动词，应改为“强劲的风”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆摩托车的马力有强劲，跑得很快。", "corrected_sentence": "这辆摩托车的马力很强劲，跑得很快。", "error_description": "“强劲”前要用程度副词“很”，说“很强劲”。“有”不能直接修饰形容词作谓语，“有强劲”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
