INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13733, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13733, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "涡轮机是一种将流体（如蒸汽、燃气或水）的能量转换为机械能的旋转式动力机械，常用于发电或推进。", "primary_collocate": null, "pronunciation": "wō lún jī", "ipa": "wɔ˥ lu̯ən˧˥ tɕi˥", "syllable_count": 3, "sentences": [{"text": "现代风力涡轮机已集成智能控制系统：激光雷达预判风速变化，实时调节桨距角以优化转矩；数字孪生技术则构建虚拟机组模型，实现故障预测性维护。", "target_word": "涡轮机", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台涡轮机正在发电。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流冲过来，涡轮机就转起来了。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查那台大涡轮机。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的发动机里有一台涡轮机。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，海边的涡轮机转得很快。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座电站装了四台涡轮机。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蒸汽推动涡轮机，带动发电机工作。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "涡轮机坏了，整个工厂都停电了。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工厂里负责维修涡轮机。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台涡轮机", "label": "量词"}, {"form": "渦輪機", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把蒸汽、燃气或水的能量转为机械能的旋转动力机械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '385e789d-21ea-49b5-b03e-4cf712cdbae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13733, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语言", "is_correct": false, "explanation": "搭配：“风力”不修饰“语言”，“现代风力语言”不成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是风力设备，与句中的风速、桨距角和机组语境不符。"}, {"text": "涡轮机", "is_correct": true, "explanation": "涡轮机：把流体能量转为机械能的旋转动力机械，风力设备指的正是它，与语境相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：句中讲风速、桨距角和机组，“手机”与风力设备无关，句子不通。"}], "explanations": {"语言": "搭配：“风力”不修饰“语言”，“现代风力语言”不成立。", "冰箱": "语义：冰箱不是风力设备，与句中的风速、桨距角和机组语境不符。", "涡轮机": "涡轮机：把流体能量转为机械能的旋转动力机械，风力设备指的正是它，与语境相符。", "手机": "语义：句中讲风速、桨距角和机组，“手机”与风力设备无关，句子不通。"}, "sentence_index": 0, "correct_answer": "涡轮机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台涡轮机能把电能储存起来。", "explanation": "这里应该用〈蓄电池〉。涡轮机是把流体能量转为机械能的机器，不能储存电能，储存电能的是蓄电池。"}, {"text": "这台涡轮机能把水烧开。", "explanation": "这里应该用〈锅炉〉。锅炉负责烧水，涡轮机是靠流体能量转动的机器，不能用来烧水。"}, {"text": "这台涡轮机是用来切割面包的。", "explanation": "这里应该用〈切片机〉。切片机用来切割食物，涡轮机是动力机械，用于发电或推进，不能用来切面包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢琴", "is_correct": false, "explanation": "语义：电站里装钢琴与发电的语境不符，句子不合情理。"}, {"text": "打字机", "is_correct": false, "explanation": "搭配：“装”与“打字机”不搭配，电站装的是发电设备。"}, {"text": "涡轮机", "is_correct": true, "explanation": "涡轮机：指把流体能量转为机械能的动力机械，“装四台”的电站设备正是它，与语境相符。"}, {"text": "收音机", "is_correct": false, "explanation": "语义：收音机不是发电设备，电站装收音机与语境不符。"}], "explanations": {"钢琴": "语义：电站里装钢琴与发电的语境不符，句子不合情理。", "打字机": "搭配：“装”与“打字机”不搭配，电站装的是发电设备。", "涡轮机": "涡轮机：指把流体能量转为机械能的动力机械，“装四台”的电站设备正是它，与语境相符。", "收音机": "语义：收音机不是发电设备，电站装收音机与语境不符。"}, "sentence_index": 6, "correct_answer": "涡轮机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台涡轮机能把文件打印出来。", "explanation": "这里应该用〈打印机〉。打印机用来把文件打印出来，涡轮机是靠流体能量转动的动力机械，不能打印文件。"}, {"text": "这台涡轮机能把食物变成力气。", "explanation": "这里应该用〈人体〉。人体能把食物变成力气，涡轮机是动力机械，靠流体能量转动，不能消化食物。"}, {"text": "这台涡轮机能把脏衣服洗干净。", "explanation": "这里应该用〈洗衣机〉。洗衣机用来洗衣服，涡轮机是用于发电或推进的动力机械，不能洗衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电站的工人检查了一只涡轮机。", "corrected_sentence": "电站的工人检查了一台涡轮机。", "error_description": "错误：量词“只”用错。“只”多用于动物，涡轮机是机器，应用量词“台”，正确为“一台涡轮机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把把涡轮机修好了。", "corrected_sentence": "工人把涡轮机修好了。", "error_description": "错误：“把”字重复出现。正确：一个“把”字句只用一个“把”，应说“工人把涡轮机修好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
